// Pure, React-free model builder for the work-order print templates (D-09).
// Every template renders from one normalized shape — rows, materials, tasks,
// totals, meta, company/bill-to/ship-to blocks — so adding a template never
// re-derives WorkOrder fields. Customer prices and internal cost/margin live in
// SEPARATE properties (row.unit_price vs row.internal.unit_cost, totals.subtotal
// vs totals.internal.*) so a customer-facing template can simply never read the
// internal side and cannot leak shop costs onto the sheet.

const clean = (v) => String(v ?? "").trim();

const num = (v, fallback = null) => {
  if (v === "" || v == null) return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
};

const moneyOrNull = (value) => {
  if (typeof value !== "number" && typeof value !== "string") return null;
  if (typeof value === "string" && value.trim() === "") return null;
  return num(value, null);
};

const firstText = (...vals) => {
  for (const v of vals) {
    const s = clean(v);
    if (s) return s;
  }
  return "";
};

// Accepts a string ("line1\nline2"), an array of strings, or an array of
// objects with name/label/line/text — anything reasonable becomes a line.
const textLines = (v) => {
  if (v == null) return [];
  const items = Array.isArray(v) ? v : [v];
  const out = [];
  for (const item of items) {
    if (item == null) continue;
    const raw = typeof item === "object"
      ? firstText(item.line, item.text, item.label, item.name, item.address)
      : String(item);
    for (const piece of raw.split(/\r?\n/)) {
      const s = clean(piece);
      if (s) out.push(s);
    }
  }
  return out;
};

const fmtQty = (v) => {
  const n = num(v, null);
  if (n == null) return "";
  return Number.isInteger(n) ? n : Math.round(n * 100) / 100;
};

const fmtDate = (v) => {
  const s = clean(v);
  if (!s) return "";
  const d = s.length === 10 ? new Date(`${s}T12:00:00`) : new Date(s);
  return Number.isNaN(d.getTime())
    ? s
    : d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
};

const formatUsd = (n) => {
  const value = num(n, null);
  return value == null
    ? ""
    : `$${value.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
};

export const PRINT_STAGE_LABELS = {
  estimating: "Estimating",
  sales: "Sales",
  permitting: "Permitting",
  design: "Design",
  production: "Production",
  fabrication: "Fabrication",
  installation: "Installation",
  completed: "Completed",
};

// WorkOrder.products[].operational_status → readable print label. Printed
// statuses stay English in every template (the Spanish sheet translates its
// own headers, not the underlying record data).
export const PRINT_PRODUCT_STATUS_LABELS = {
  order_review: "Order Review",
  site_survey: "Site Survey",
  awaiting_customer_action: "Awaiting Customer",
  awaiting_proof_approval: "Awaiting Proof Approval",
  proof_changes_requested: "Proof Changes Requested",
  permitting: "Permitting",
  proof_approved: "Proof Approved",
  design_review: "Design Review",
  in_design: "In Design",
  in_production: "In Production",
  quality_control: "Quality Control",
  service_repair: "Service Repair",
  install_or_removal_only: "Install / Removal Only",
  vended: "Vended",
  none: "",
};

const titleCase = (v) => {
  const s = clean(v).replace(/[_-]+/g, " ");
  return s ? s.replace(/\b[a-z]/g, (c) => c.toUpperCase()) : "";
};

const productStatus = (product) =>
  (PRINT_PRODUCT_STATUS_LABELS[clean(product?.operational_status)]
    ?? titleCase(product?.operational_status))
    || clean(product?.customer_facing_status);

// Customer-facing product notes only. Estimator notes are INTERNAL and must
// never travel into a print model.
const customerNotes = (product) => {
  const rows = Array.isArray(product?.notes) ? product.notes : [];
  return rows
    .filter((n) => ["customer", "client"].includes(clean(n?.channel).toLowerCase()))
    .map((n) => clean(n?.text))
    .filter(Boolean)
    .join(" · ");
};

// Quote-defaults record (company_name / company_logo_url / company_address …)
// maps to the print company block; an already-mapped company passes through.
export function mapPrintCompany(source) {
  const c = source || {};
  return {
    name: firstText(c.name, c.company_name),
    logo_url: firstText(c.logo_url, c.company_logo_url),
    address_lines: textLines(c.address_lines?.length ? c.address_lines : c.company_address),
    phone: firstText(c.phone, c.company_phone),
    email: firstText(c.email, c.company_email),
    website: firstText(c.website, c.company_website),
    license: firstText(c.license, c.company_license),
    footer_note: firstText(c.footer_note, c.quote_footer_text),
  };
}

export function buildWorkOrderPrintModel(workOrder, opts = {}) {
  const wo = workOrder || {};
  const company = mapPrintCompany(opts.company || opts.companyDefaults);

  const rows = (Array.isArray(wo.products) ? wo.products : []).map((p, i) => {
    const qty = fmtQty(p?.quantity);
    const unitPrice = moneyOrNull(p?.quoted_unit_price);
    const extPrice = moneyOrNull(p?.quoted_total) ?? (
      unitPrice != null && qty !== "" ? unitPrice * qty : null
    );
    const unitCost = moneyOrNull(p?.unit_cost);
    const extCost = moneyOrNull(p?.ext_cost ?? p?.extended_cost) ?? (
      unitCost != null && qty !== "" ? unitCost * qty : null
    );
    return {
      line: i + 1,
      name: firstText(p?.customer_description, p?.description) || "Item",
      type: clean(p?.product_type),
      qty,
      unit_price: unitPrice,
      ext_price: extPrice,
      internal: {
        unit_cost: unitCost,
        ext_cost: extCost,
        margin: extPrice != null && extCost != null ? extPrice - extCost : null,
      },
      status: productStatus(p),
      notes: customerNotes(p),
      due_date: fmtDate(p?.product_due_date || p?.design_due_date),
    };
  });

  const materials = (Array.isArray(wo.materials) ? wo.materials : []).map((mat) => {
    const qty = fmtQty(mat?.quantity);
    const unitCost = moneyOrNull(mat?.unit_cost);
    return {
      name: firstText(mat?.part_name, mat?.name, mat?.inventory_item_name) || "Part",
      type: clean(mat?.part_type),
      section: clean(mat?.section_name),
      qty,
      unit: clean(mat?.unit),
      unit_cost: unitCost,
      ext_cost: moneyOrNull(mat?.ext_cost ?? mat?.extended_cost) ?? (unitCost != null && qty !== "" ? unitCost * qty : null),
    };
  });

  const tasks = (Array.isArray(wo.notes) ? wo.notes : [])
    .map((task) => ({
      text: clean(task?.text),
      completed: !!task?.completed,
      is_milestone: !!task?.is_milestone,
      assigned_to: clean(task?.assigned_to),
      due_date: fmtDate(task?.due_date),
    }))
    .filter((task) => task.text);

  const subtotal = rows.reduce(
    (sum, row) => (row.ext_price == null ? sum : sum + row.ext_price),
    0,
  );
  const totalCost = rows.reduce(
    (sum, row) => (row.internal.ext_cost == null ? sum : sum + row.internal.ext_cost),
    0,
  );
  const hasCompleteCost = rows.length > 0 && rows.every((row) => row.internal.ext_cost != null);
  const hasCompletePrice = rows.length > 0 && rows.every((row) => row.ext_price != null);
  const totalMargin = hasCompleteCost && hasCompletePrice ? subtotal - totalCost : null;

  const estimateAmount = moneyOrNull(wo.estimate_amount);
  const depositAmount = moneyOrNull(wo.deposit_amount);
  const contractTotal = estimateAmount ?? subtotal;
  const balanceDue = contractTotal == null
    ? null
    : contractTotal - (depositAmount || 0);

  const billToLines = textLines(
    Array.isArray(wo.billing_address) || wo.billing_address
      ? wo.billing_address
      : wo.install_location,
  ).concat(textLines(wo.billing_address_line_2));
  const siteLines = textLines(wo.install_location).concat(textLines(wo.address_line_2));
  const locality = [clean(wo.township_city), clean(wo.county)].filter(Boolean).join(", ");
  if (locality) siteLines.push(locality);

  const clientName = firstText(wo.client_name, wo.contact_name);
  const contactName = clean(wo.contact_name);

  const meta = [
    { key: "stage", label: "Stage", value: PRINT_STAGE_LABELS[clean(wo.current_stage)] || titleCase(wo.current_stage) },
    { key: "start_date", label: "Start Date", value: fmtDate(wo.start_date) },
    { key: "due_date", label: "Due Date", value: fmtDate(wo.due_date) },
    { key: "install_date", label: "Install Date", value: fmtDate(wo.project_install_date) },
    { key: "project_manager", label: "Project Manager", value: clean(wo.project_manager) },
    { key: "sales_rep", label: "Sales Rep", value: clean(wo.sales_rep) },
    { key: "estimator", label: "Estimator", value: clean(wo.estimator) },
    { key: "designer", label: "Designer", value: clean(wo.designer) },
    { key: "project_type", label: "Project Type", value: clean(wo.project_type) },
    { key: "permit_number", label: "Permit #", value: clean(wo.permit_number) },
  ].filter((entry) => entry.value);

  const pieceCount = rows.reduce(
    (sum, row) => (row.qty === "" ? sum : sum + Number(row.qty)),
    0,
  );

  return {
    template_id: firstText(opts.templateId, opts.template_id),
    order_number: firstText(wo.order_number, wo.order_id, wo.id),
    job_code: clean(wo.job_code),
    document_title: clean(opts.documentTitle) || "Work Order",
    document_title_es: clean(opts.documentTitleEs) || "Orden de Trabajo",
    printed_at: opts.printedAt || new Date().toISOString(),
    footer_note: firstText(opts.footerNote, company.footer_note),
    work_order_title: clean(wo.title),
    description: clean(wo.description),
    asap: !!wo.asap,
    completed: !!wo.completed,
    piece_count: pieceCount || null,
    company,
    bill_to: {
      name: clientName,
      attention: contactName && contactName !== clientName ? contactName : "",
      address_lines: billToLines,
      phone: clean(wo.contact_phone),
      email: clean(wo.contact_email),
    },
    ship_to: {
      attention: contactName,
      address_lines: siteLines.length ? siteLines : billToLines,
    },
    rows,
    materials,
    tasks,
    task_counts: {
      done: tasks.filter((task) => task.completed).length,
      total: tasks.length,
    },
    totals: {
      subtotal,
      estimate_amount: estimateAmount,
      contract_total: contractTotal,
      deposit_required: !!wo.deposit_required,
      deposit_amount: depositAmount,
      deposit_invoiced: !!wo.deposit_invoiced,
      balance_due: balanceDue,
      internal: {
        total_cost: hasCompleteCost ? totalCost : null,
        total_margin: totalMargin,
        margin_pct: totalMargin != null && subtotal > 0
          ? Math.round((totalMargin / subtotal) * 100)
          : null,
        actual_cost: moneyOrNull(wo.actual_cost),
        profit_margin: moneyOrNull(wo.profit_margin),
      },
    },
    meta,
    fmt: { usd: formatUsd },
  };
}

export default buildWorkOrderPrintModel;

// Original work-order print — the classic portrait shop copy. Prints
// everything: customer prices AND internal cost/margin columns plus the
// materials manifest, so production keeps the full financial picture on one
// sheet. Portrait @page.

import {
  asapBadge,
  clean,
  companyBlock,
  escapeHtml,
  fieldLabel,
  htmlDoc,
  metaStrip,
  printedAtText,
  renderAddressLines,
  usd,
} from "./_shared";

const th = (label, align = "left") =>
  `<th style="padding:6px 8px;border-bottom:1.5px solid #334155;font-size:9px;font-weight:800;` +
  `text-transform:uppercase;letter-spacing:0.07em;color:#475569;text-align:${align};">${escapeHtml(label)}</th>`;

const td = (content, { align = "left", bold = false, color = "#0f172a", size = 12 } = {}) =>
  `<td style="padding:6px 8px;border-bottom:1px solid #e2e8f0;font-size:${size}px;` +
  `color:${color};text-align:${align};${bold ? "font-weight:700;" : ""}">${content}</td>`;

export function renderOriginalHtml(model, renderOptions = {}) {
  const m = model || {};
  const rows = Array.isArray(m.rows) ? m.rows : [];
  const materials = Array.isArray(m.materials) ? m.materials : [];
  const tasks = Array.isArray(m.tasks) ? m.tasks : [];
  const t = m.totals || {};
  const ti = t.internal || {};
  const fmt = m.fmt;
  const money = (n) => escapeHtml(usd(n, fmt));

  const productRows = rows.length
    ? rows.map((r, i) => {
        const bg = i % 2 ? "#f8fafc" : "#fff";
        return `<tr style="background:${bg};">` +
          td(`<span style="color:#64748b;">${escapeHtml(r.line ?? i + 1)}</span>`, { align: "right" }) +
          td(escapeHtml(r.name || "Item"), { bold: true }) +
          td(escapeHtml(r.type || "—")) +
          td(escapeHtml(r.qty === "" || r.qty == null ? "—" : r.qty), { align: "center" }) +
          td(money(r.unit_price), { align: "right" }) +
          td(money(r.ext_price), { align: "right", bold: true }) +
          td(`<span style="color:#64748b;">${money(r.internal?.unit_cost)}</span>`, { align: "right" }) +
          td(`<span style="color:#64748b;">${money(r.internal?.ext_cost)}</span>`, { align: "right" }) +
          td(`<span style="color:#64748b;">${money(r.internal?.margin)}</span>`, { align: "right" }) +
          td(escapeHtml(r.status || "—"), { size: 11 }) +
          `</tr>`;
      }).join("")
    : `<tr><td colspan="10" style="padding:14px;text-align:center;font-size:12px;color:#94a3b8;">No products on this work order.</td></tr>`;

  const materialRows = materials.length
    ? materials.map((mat, i) =>
        `<tr style="background:${i % 2 ? "#f8fafc" : "#fff"};">` +
          td(escapeHtml(mat.name), { bold: true }) +
          td(escapeHtml(mat.type || "—")) +
          td(escapeHtml(mat.section || "—"), { size: 11 }) +
          td(escapeHtml(`${mat.qty === "" || mat.qty == null ? "—" : mat.qty}${mat.unit ? ` ${mat.unit}` : ""}`), { align: "center" }) +
          td(money(mat.unit_cost), { align: "right" }) +
          td(money(mat.ext_cost), { align: "right" }) +
        `</tr>`
      ).join("")
    : "";

  const totalsRows = [
    ["Products Subtotal", t.subtotal],
    t.estimate_amount != null ? ["Contract Total (estimate)", t.estimate_amount] : null,
    t.deposit_required || t.deposit_amount != null
      ? [`Deposit Required${t.deposit_invoiced ? " (invoiced)" : ""}`, t.deposit_amount]
      : null,
    t.balance_due != null && t.deposit_amount != null ? ["Balance After Deposit", t.balance_due] : null,
    ti.total_cost != null ? ["Internal Cost", ti.total_cost] : null,
    ti.total_margin != null
      ? [`Internal Margin${ti.margin_pct != null ? ` (${ti.margin_pct}%)` : ""}`, ti.total_margin]
      : null,
    ti.actual_cost != null ? ["Actual Cost To Date", ti.actual_cost] : null,
    ti.profit_margin != null ? ["Profit Margin", ti.profit_margin] : null,
  ].filter(Boolean);

  const totalsHtml = `
    <table style="width:280px;margin-left:auto;margin-top:10px;border:1.5px solid #334155;">
      ${totalsRows.map(([label, value], i) => {
        const strong = /Subtotal|Contract|Balance/.test(label);
        return `<tr style="background:${strong ? "#f1f5f9" : "#fff"};">` +
          `<td style="padding:5px 10px;font-size:11px;color:#475569;border-bottom:1px solid #e2e8f0;">${escapeHtml(label)}</td>` +
          `<td style="padding:5px 10px;font-size:12px;text-align:right;border-bottom:1px solid #e2e8f0;${strong ? "font-weight:800;color:#0f172a;" : "color:#334155;"}">${money(value)}</td>` +
          `</tr>`;
      }).join("")}
    </table>`;

  const taskRows = tasks.map((task) =>
    `<tr>` +
    `<td style="padding:4px 8px;border-bottom:1px solid #e2e8f0;width:26px;text-align:center;">` +
    `<span style="display:inline-block;width:11px;height:11px;border:1.5px solid #334155;border-radius:2px;background:${task.completed ? "#334155" : "#fff"};"></span></td>` +
    `<td style="padding:4px 8px;border-bottom:1px solid #e2e8f0;font-size:12px;${task.completed ? "color:#94a3b8;text-decoration:line-through;" : "color:#0f172a;"}">` +
    `${escapeHtml(task.text)}${task.is_milestone ? ' <span style="font-size:9px;font-weight:800;color:#7c3aed;">MILESTONE</span>' : ""}</td>` +
    `<td style="padding:4px 8px;border-bottom:1px solid #e2e8f0;font-size:11px;color:#64748b;white-space:nowrap;">${escapeHtml([task.assigned_to, task.due_date].filter(Boolean).join(" · "))}</td>` +
    `</tr>`
  ).join("");

  const bodyHtml = `
<div style="max-width:8.5in;margin:0 auto;padding:0.3in;">
  <div style="display:flex;justify-content:space-between;align-items:flex-start;gap:16px;border-bottom:2.5px solid #0f172a;padding-bottom:10px;">
    ${companyBlock(m.company)}
    <div style="text-align:right;">
      <div style="font-size:22px;font-weight:800;letter-spacing:0.06em;color:#0f172a;text-transform:uppercase;">
        ${escapeHtml(m.document_title || "Work Order")}
      </div>
      <div style="font-size:12px;color:#475569;margin-top:2px;">
        Order <span style="font-weight:700;color:#0f172a;">${escapeHtml(m.order_number)}</span>
      </div>
      ${m.job_code ? `<div style="font-size:10px;color:#94a3b8;font-family:monospace;margin-top:2px;">${escapeHtml(m.job_code)}</div>` : ""}
      <div style="font-size:10px;color:#94a3b8;margin-top:2px;">Printed ${escapeHtml(printedAtText(m.printed_at))}</div>
      <div style="margin-top:4px;">${asapBadge(m)}${m.completed ? ' <span style="display:inline-block;background:#059669;color:#fff;font-size:9px;font-weight:800;letter-spacing:0.08em;padding:2px 8px;border-radius:3px;">COMPLETED</span>' : ""}</div>
    </div>
  </div>

  <div style="display:flex;gap:12px;margin-top:10px;">
    <div style="flex:1;border:1.5px solid #334155;border-radius:4px;padding:10px 12px;">
      ${fieldLabel("Bill To")}
      <div style="font-size:13px;font-weight:700;color:#0f172a;margin-top:2px;">${escapeHtml(m.bill_to?.name || "—")}</div>
      ${m.bill_to?.attention ? `<div style="font-size:11px;color:#475569;">Attn: ${escapeHtml(m.bill_to.attention)}</div>` : ""}
      <div style="font-size:12px;color:#0f172a;line-height:1.5;margin-top:2px;">${renderAddressLines(m.bill_to?.address_lines || [])}</div>
      ${m.bill_to?.phone || m.bill_to?.email
        ? `<div style="font-size:11px;color:#475569;margin-top:2px;">${[m.bill_to.phone, m.bill_to.email].filter(Boolean).map(escapeHtml).join(" &middot; ")}</div>`
        : ""}
    </div>
    <div style="flex:1;border:1.5px solid #334155;border-radius:4px;padding:10px 12px;">
      ${fieldLabel("Install Site")}
      <div style="font-size:12px;color:#0f172a;line-height:1.5;margin-top:2px;">${renderAddressLines(m.ship_to?.address_lines || [])}</div>
      ${m.ship_to?.attention ? `<div style="font-size:11px;color:#475569;">Attn: ${escapeHtml(m.ship_to.attention)}</div>` : ""}
    </div>
  </div>

  ${m.work_order_title
    ? `<div style="margin-top:10px;"><div style="font-size:14px;font-weight:700;color:#0f172a;">${escapeHtml(m.work_order_title)}</div></div>`
    : ""}
  ${m.description
    ? `<div style="margin-top:4px;font-size:12px;color:#334155;white-space:pre-wrap;">${escapeHtml(m.description)}</div>`
    : ""}

  ${metaStrip(m.meta)}

  <div class="wo-table-scroll" role="region" aria-label="Work Order products" tabindex="0">
  <table style="width:100%;margin-top:12px;border:1.5px solid #334155;">
    <thead>
      <tr style="background:#f1f5f9;">
        ${th("#", "right")}${th("Product / Description")}${th("Type")}${th("Qty", "center")}
        ${th("Unit Price", "right")}${th("Ext Price", "right")}
        ${th("Unit Cost", "right")}${th("Ext Cost", "right")}${th("Margin", "right")}
        ${th("Status")}
      </tr>
    </thead>
    <tbody>${productRows}</tbody>
  </table>
  </div>
  <div style="margin-top:4px;font-size:10px;color:#64748b;">
    ${rows.length} line${rows.length === 1 ? "" : "s"}${m.piece_count ? ` · ${escapeHtml(m.piece_count)} total pieces` : ""}
  </div>

  ${totalsHtml}

  ${materials.length
    ? `<div style="margin-top:14px;page-break-inside:avoid;">
        <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:0.08em;color:#475569;border-bottom:1px solid #cbd5e1;padding-bottom:3px;">
          Materials Manifest (internal) — ${materials.length}
        </div>
        <div class="wo-table-scroll" role="region" aria-label="Work Order materials" tabindex="0">
        <table style="width:100%;margin-top:6px;">
          <thead><tr style="background:#f8fafc;">${th("Part")}${th("Type")}${th("Section")}${th("Qty", "center")}${th("Unit Cost", "right")}${th("Ext Cost", "right")}</tr></thead>
          <tbody>${materialRows}</tbody>
        </table>
        </div>
      </div>`
    : ""}

  ${tasks.length
    ? `<div style="margin-top:14px;">
        <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:0.08em;color:#475569;border-bottom:1px solid #cbd5e1;padding-bottom:3px;">
          Production Checklist — ${m.task_counts?.done ?? 0}/${m.task_counts?.total ?? tasks.length} done
        </div>
        <table style="width:100%;margin-top:4px;">${taskRows}</table>
      </div>`
    : ""}

  <div style="display:flex;gap:24px;margin-top:26px;page-break-inside:avoid;">
    ${["Received By", "Approved By", "Date"].map((lbl) =>
      `<div style="flex:1;"><div style="height:26px;border-bottom:1px solid #94a3b8;"></div>` +
      `<div style="font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;color:#64748b;padding-top:2px;text-align:center;">${escapeHtml(lbl)}</div></div>`
    ).join("")}
  </div>

  <div style="display:flex;justify-content:space-between;margin-top:20px;padding-top:6px;border-top:1px solid #cbd5e1;font-size:9px;color:#94a3b8;">
    <span>${escapeHtml(m.footer_note || "")}</span>
    <span>${escapeHtml(m.document_title || "Work Order")} &mdash; ${escapeHtml(m.order_number)}${m.job_code ? ` (${escapeHtml(m.job_code)})` : ""}</span>
  </div>
</div>`;

  return htmlDoc({
    title: `${m.document_title || "Work Order"} — ${m.order_number || ""}`,
    bodyHtml,
    autoPrint: renderOptions.autoPrint !== false,
    extraCss: `
  @page { margin: 0.55in; }
  .sheet { max-width: 8.5in; }
  .wo-table-scroll { max-width: 100%; overflow-x: auto; }
  @media print { .wo-table-scroll { max-width: none; overflow: visible; } }
    `,
  });
}

export default {
  id: "original",
  label: "Original",
  renderHtml: renderOriginalHtml,
