import { getModuleLabel } from "./moduleRegistry";
import { computeOrderDueDate, computeProductDueDate, recalcOnProofApproval } from "../../../base44/shared/dueDateEngine.ts";
import { OPERATIONAL_STATUS_SET, customerFacingLabel } from "../../../base44/shared/productStatusModel.ts";
import { mutateWorkOrderArrayField } from "../workflow/workOrderPersistence";
import { NotificationTriggers } from "@/components/workflow/NotificationService";
import { staffEntities } from "@/components/staff/staffEntities";
import { DEPOSIT_GATED_STATUSES, depositGateApplies, depositGateMessage } from "./depositGate";
import { acceptedCustomerUnitPrice } from "./customerPricing";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const norm = (value) => String(value || "").trim().toLowerCase();
const firstNonBlank = (...values) => values.find((value) => value !== undefined && value !== null && String(value).trim() !== "") ?? "";

// B-14: canonical initial operational status for conversion-seeded products —
// the locked vocabulary's first WIP value ("order_review") per
// base44/shared/productStatusModel.ts. Guarded so a partially-stubbed test
// bundle (shared imports stubbed to {}) still seeds the same value.
export const INITIAL_OPERATIONAL_STATUS =
  (Array.isArray(OPERATIONAL_STATUS_SET) && OPERATIONAL_STATUS_SET[0]) || "order_review";

const asObjectList = (value) =>
  (Array.isArray(value) ? value.filter((row) => row && typeof row === "object") : []);

// B-14: resolve the parts that drive one line's lead-time due dates through
// the estimate's own part refs. Precedence, most direct first: part rows
// embedded on the line (or on its builder snapshot), then the caller-loaded
// BuilderPart pool matched by estimate_line_id/line_id, then by the line's
// builder_product_id link. Inactive parts never contribute lead.
export function resolveEstimateLineParts(line = {}, partsPool = []) {
  const embedded = [
    line?.parts, line?.part_list, line?.builder_parts,
    line?.builder_snapshot?.parts, line?.builder_snapshot?.part_list,
  ].find((list) => Array.isArray(list) && list.length > 0);
  if (embedded) return asObjectList(embedded).filter((part) => part.is_active !== false);
  const pool = asObjectList(partsPool).filter((part) => part.is_active !== false);
  if (!pool.length) return [];
  const lineId = String(line?.line_id || "").trim();
  const builderProductId = String(line?.builder_product_id || "").trim();
  return pool.filter((part) =>
    (lineId && (
      String(part?.estimate_line_id || "").trim() === lineId ||
      String(part?.line_id || "").trim() === lineId
    )) ||
    (builderProductId && String(part?.builder_product_id || "").trim() === builderProductId)
  );
}

// B-14: gather the estimate's BuilderPart rows for due-date seeding — the
// same two paths buildEstimateMaterialsManifest uses (estimate_id stamp
// first, builder_product_id fallback for legacy parts) — so conversion
// callers can hand the pool to buildEstimateWorkOrderProducts via
// options.parts / pricing.parts. Pure read; failures return [].
export async function loadEstimateConversionParts(estimate = {}, { entity = null } = {}) {
  const Part = entity || staffEntities?.BuilderPart;
  if (typeof Part?.filter !== "function") return [];
  const estimateId = String(estimate?.id || "").trim();
  const lines = Array.isArray(estimate?.line_items) ? estimate.line_items : [];
  const builderProductIds = [...new Set(lines.map((l) => String(l?.builder_product_id || "").trim()).filter(Boolean))];
  const seen = new Set();
  const parts = [];
  const push = (row) => {
    const id = String(row?.id || "").trim();
    if (!id || seen.has(id)) return;
    seen.add(id);
    parts.push(row);
  };
  if (estimateId) {
    (await Part.filter({ estimate_id: estimateId }, "created_date", 500).catch(() => []))
      .forEach(push);
  }
  for (const bpid of builderProductIds) {
    if (parts.some((p) => String(p?.builder_product_id || "").trim() === bpid)) continue;
    (await Part.filter({ builder_product_id: bpid }, "created_date", 500).catch(() => []))
      .forEach(push);
  }
  return parts;
}

// B-14: seed WorkOrder products[] from estimate line_items. Each seeded row
// carries the canonical initial operational_status (blank/"none" line states
// fold to order_review; a real line status is preserved), dual due dates
// computed from resolved part leads through the shared engine (design parts
// use design_lead_days, production uses product_lead_days — max across the
// line's parts, anchored at the conversion moment), responsibility from the
// line then the estimate's defaults, and name/qty/price from the priced line.
// ADD-only: every pre-existing field w-8/w-32 put on the row still emits.
export function buildEstimateWorkOrderProducts(estimate = {}, pricing = {}, options = {}) {
  const pricedByLine = new Map(
    (pricing.sections || [])
      .filter((section) => section?.line_id)
      .map((section) => [section.line_id, section])
  );

  // Part pool for lead resolution: explicit options.parts wins, then
  // pricing.parts, then an estimate.parts payload — each line slices out its
  // own refs via resolveEstimateLineParts.
  const partsPool = asObjectList(options?.parts ?? pricing?.parts ?? estimate?.parts);
  // Leads anchor at the conversion moment by default (options.anchor_date /
  // conversionDate / now, or a pricing-level anchor) so seeded deadlines run
  // from order creation — the same rule recalcOnProofApproval applies later.
  const anchorDate =
    firstNonBlank(options?.anchor_date, options?.conversionDate, options?.now, pricing?.anchor_date) ||
    new Date();
  const dueOptions = {
    clock: options?.clock ?? pricing?.clock ?? null,
    design_clock: options?.design_clock ?? pricing?.design_clock ?? null,
    tier: options?.tier ?? pricing?.lead_tier ?? "standard",
    respect_hard_dates: true,
    push_forward_only: false,
    label: "estimate_conversion",
  };

  return (estimate.line_items || []).map((line, index) => {
    const priced = pricedByLine.get(line.line_id) || line;
    const quantity = Math.max(0, num(priced.quantity, num(line.customer_quantity, 1)));
    const unitPrice = num(priced.unitRaw, acceptedCustomerUnitPrice(line));
    const adjustedTotal = Number.isFinite(Number(priced.adjusted))
      ? Number(priced.adjusted)
      : unitPrice * quantity * (1 + num(line.adjustment_percent) / 100);
    const productName = line.client_product_name || line.project_name || getModuleLabel(line.module_key) || `Product ${index + 1}`;

    // Dual dates: computeProductDueDate echoes the carried (w-32-imported)
    // dates when the line resolves no parts, so nothing regresses for
    // part-less lines — and a hard_due_date row with a stored date holds it.
    const lineParts = resolveEstimateLineParts(line, partsPool);
    const due = typeof computeProductDueDate === "function"
      ? computeProductDueDate({
          parts: lineParts,
          anchor_date: anchorDate,
          hard_due_date: Boolean(line.hard_due_date),
          product_due_date: firstNonBlank(line.product_due_date, priced.product_due_date),
          design_due_date: firstNonBlank(line.design_due_date, priced.design_due_date),
          ...dueOptions,
        })
      : { due_date: line.product_due_date || "", design_due_date: line.design_due_date || "" };

    const explicitStatus = String(line.operational_status || "").trim();
    const seededStatus = explicitStatus && norm(explicitStatus) !== "none"
      ? explicitStatus
      : INITIAL_OPERATIONAL_STATUS;

    return {
      id: line.builder_product_id || line.line_id || line.project_id || `estimate-product-${index + 1}`,
      description: productName,
      // SIP/production Product Type is an explicit classification selected on
      // the estimator Product. Builder/module names are not interchangeable
      // with the production taxonomy, so never guess a fallback here.
      product_type: line.production_product_type || "",
      estimate_line_id: line.line_id || "",
      builder_product_id: line.builder_product_id || "",
      source_project_id: line.project_id || "",
      module_key: line.module_key || "",
      quantity,
      quoted_unit_price: unitPrice,
      quoted_total: adjustedTotal,
      category: line.product_category || "",
      customer_description: line.customer_description || "",
      estimator_notes: line.product_notes || "",
      operational_status: seededStatus,
      operational_substatus: line.operational_substatus || "",
      // Seeded products get the canonical customer-facing label for their
      // initial status (locked vocabulary first, legacy alias map second);
      // an explicit line value always wins.
      customer_facing_status: firstNonBlank(
        line.customer_facing_status,
        typeof customerFacingLabel === "function" ? customerFacingLabel(seededStatus) : "",
        customerFacingStatusLabel(seededStatus),
      ),
      fulfillment_state: line.fulfillment_state || "none",
      design_due_date: due.design_due_date || "",
      product_due_date: due.due_date || "",
      hard_due_date: Boolean(line.hard_due_date),
      designer: line.designer || "",
      assigned_to: line.assigned_to || "",
      // Responsibility seeds per-line first, then whatever estimate-level
      // default the estimate carries (default_responsibility /
      // sales_responsibility / responsibility), then a caller override.
      responsibility: firstNonBlank(
        line.responsibility,
        estimate.default_responsibility,
        estimate.sales_responsibility,
        estimate.responsibility,
        options?.default_responsibility,
        pricing?.default_responsibility,
      ),
      responsibility_color: firstNonBlank(line.responsibility_color, options?.responsibility_color),
      queue_priority: num(line.queue_priority, 0),
      proof_status: line.proof_status || "none",
      proof_file_url: line.proof_file_url || "",
      proof_file_name: line.proof_file_name || "",
      proof_version: num(line.proof_version, 0),
      proof_approved_version: num(line.proof_approved_version, 0),
    };
  });
}


// CoreBridge-style customer-facing labels: internal operational_status values are
// never shown to the customer directly; each maps to a safe display label.
export const OPERATIONAL_STATUS_CUSTOMER_LABELS = {
  order_review: "Prepping Your Order",
  site_survey: "Site Survey",
  awaiting_customer_action: "Customer Action Needed",
  awaiting_proof_approval: "Requires Proof Approval",
  permitting: "Permitting",
  proof_approved: "Proof Approved",
  design_review: "In Design",
  in_design: "In Design",
  in_production: "In Production",
  quality_control: "Quality Control",
  service_repair: "Service/Repair",
  install_or_removal_only: "Install or Removal Only",
  vended: "In Production",
  none: "",
};

export const OPERATIONAL_STATUS_VALUES = Object.keys(OPERATIONAL_STATUS_CUSTOMER_LABELS);

export const PROOF_STATUS_VALUES = ["none", "draft", "sent", "awaiting_approval", "approved", "revision_requested"];

export const FULFILLMENT_STATE_VALUES = [
  "none", "awaiting_pickup", "awaiting_installation", "awaiting_shipping",
  "awaiting_delivery", "picked_up", "installed", "shipped", "delivered",
];

// Operational fields mirrored between WorkOrder.products[] rows and the linked
// BuilderProduct record.
export const PRODUCT_OPERATIONAL_FIELDS = [
  "operational_status", "operational_substatus", "customer_facing_status",
  "fulfillment_state", "design_due_date", "product_due_date", "hard_due_date",
  "designer", "assigned_to", "responsibility", "queue_priority", "proof_status",
  "proof_file_url", "proof_file_name", "proof_version", "proof_approved_version",
  "operational_status_changed_at",
];

export function customerFacingStatusLabel(operationalStatus, explicit = "") {
  if (String(explicit || "").trim()) return String(explicit).trim();
  return OPERATIONAL_STATUS_CUSTOMER_LABELS[norm(operationalStatus)] || "";
}

const requireEnum = (value, allowed, label) => {
  const v = norm(value) || "none";
  if (!allowed.includes(v)) throw new Error(`Unknown ${label} "${String(value).trim()}".`);
  return v;
};

const requireDateString = (value, label = "due date") => {
  const v = String(value || "").trim();
  if (!v) return "";
  const parsed = /^\d{4}-\d{2}-\d{2}$/.test(v) ? new Date(`${v}T00:00:00`) : new Date(v);
  if (Number.isNaN(parsed.getTime())) throw new Error(`Invalid ${label} "${v}".`);
  return v;
};

export function buildProductOperationalPatch({
  operationalStatus, operationalSubstatus, proofStatus, fulfillmentState,
  designer, assignedTo, responsibility, queuePriority,
  designDueDate, productDueDate, hardDueDate,
  proofFileUrl, proofFileName, proofVersion, proofApprovedVersion, now,
} = {}) {
  const patch = {};
  if (operationalStatus !== undefined) {
    const status = requireEnum(operationalStatus, OPERATIONAL_STATUS_VALUES, "product status");
    patch.operational_status = status;
    patch.customer_facing_status = customerFacingStatusLabel(status);
    patch.operational_status_changed_at = (now ? new Date(now) : new Date()).toISOString();
  }
  if (operationalSubstatus !== undefined) patch.operational_substatus = String(operationalSubstatus || "").trim();
  if (proofStatus !== undefined) patch.proof_status = requireEnum(proofStatus, PROOF_STATUS_VALUES, "proof status");
  if (fulfillmentState !== undefined) patch.fulfillment_state = requireEnum(fulfillmentState, FULFILLMENT_STATE_VALUES, "fulfillment state");
  if (designer !== undefined) patch.designer = String(designer || "").trim();
  if (assignedTo !== undefined) patch.assigned_to = String(assignedTo || "").trim();
  if (responsibility !== undefined) patch.responsibility = String(responsibility || "").trim();
  if (queuePriority !== undefined) {
    const n = Number(queuePriority);
    patch.queue_priority = Math.max(0, Math.min(99, Math.round(Number.isFinite(n) ? n : 0)));
  }
  if (designDueDate !== undefined) patch.design_due_date = requireDateString(designDueDate);
  if (productDueDate !== undefined) patch.product_due_date = requireDateString(productDueDate);
  if (hardDueDate !== undefined) patch.hard_due_date = Boolean(hardDueDate);
  // Proof file/version fields: version 0 means "none" (no file / no approval).
  if (proofFileUrl !== undefined) patch.proof_file_url = String(proofFileUrl || "").trim();
  if (proofFileName !== undefined) patch.proof_file_name = String(proofFileName || "").trim();
  if (proofVersion !== undefined) {
    const n = Number(proofVersion);
    patch.proof_version = Math.max(0, Math.round(Number.isFinite(n) ? n : 0));
  }
  if (proofApprovedVersion !== undefined) {
    const n = Number(proofApprovedVersion);
    patch.proof_approved_version = Math.max(0, Math.round(Number.isFinite(n) ? n : 0));
  }
  return patch;
}

const sameField = (a, b) => {
  if (typeof a === "boolean" || typeof b === "boolean") return a === b;
  if (typeof a === "number" || typeof b === "number") return Number(a) === Number(b);
  return String(a ?? "") === String(b ?? "");
};

// Pure patch application: validates input, enforces the hard-due-date rule,
// auto-advances proof_approved when a proof is approved, and appends a capped
// status_history audit trail. Returns the SAME product object when nothing
// changes so callers can no-op.
export function applyProductOperationalPatch(product, patchInput, { now, actor = "", overrideHardDue = false } = {}) {
  const patch = buildProductOperationalPatch({ ...(patchInput || {}), now });
  const nowIso = (now ? new Date(now) : new Date()).toISOString();

  if (
    product?.hard_due_date === true &&
    typeof patch.product_due_date === "string" && patch.product_due_date &&
    String(product?.product_due_date || "") &&
    new Date(requireDateString(patch.product_due_date)).getTime() > new Date(requireDateString(product.product_due_date)).getTime() &&
    patch.hard_due_date !== false &&
    !overrideHardDue
  ) {
    throw new Error("This product has a hard due date; moving it later requires an explicit override.");
  }

  // Approving a proof while the product waits on that approval advances the
  // operational status automatically.
  if (
    patch.proof_status === "approved" &&
    patch.operational_status === undefined &&
    norm(product?.operational_status) === "awaiting_proof_approval"
  ) {
    patch.operational_status = "proof_approved";
    patch.customer_facing_status = customerFacingStatusLabel("proof_approved");
    patch.operational_status_changed_at = nowIso;
  }

  const trackable = [
    "operational_status", "operational_substatus", "customer_facing_status",
    "proof_status", "fulfillment_state", "design_due_date", "product_due_date",
    "hard_due_date", "designer", "assigned_to", "responsibility", "queue_priority",
    "proof_file_url", "proof_file_name", "proof_version", "proof_approved_version",
  ];
  const changed = {};
  for (const field of trackable) {
    if (patch[field] !== undefined && !sameField(product?.[field], patch[field])) changed[field] = patch[field];
  }
  if (!Object.keys(changed).length) return product;

  const entries = Object.keys(changed)
    .filter((field) => field !== "customer_facing_status")
    .map((field) => ({ at: nowIso, field, from: product?.[field] ?? "", to: changed[field], by: actor }));
  if (changed.operational_status !== undefined) changed.operational_status_changed_at = patch.operational_status_changed_at || nowIso;

  return {
    ...product,
    ...changed,
    status_history: [
      ...(Array.isArray(product?.status_history) ? product.status_history : []),
      ...entries,
    ].slice(-50),
  };
}

// CoreBridge rule mirrored: when every product on an estimate converts to an
// approved operational state, the order itself may advance. Keep this as a
// pure predicate so the work-order stage change stays an explicit caller step.
export function allProductsOperationallyApproved(products = []) {
  const list = (products || []).filter((product) => product && product.id);
  if (!list.length) return false;
  return list.every((product) => norm(product.operational_status) === "proof_approved" || norm(product.proof_status) === "approved");
}

const productKey = (product = {}) => {
  if (product.id) return `id:${product.id}`;
  return `name:${norm(product.description)}|type:${norm(product.product_type)}`;
};

// WorkOrder products may already have been edited by Sales/Production. Preserve
// those rows exactly and append only estimate Products that are not represented.
export function mergeWorkOrderProducts(existingProducts = [], estimateProducts = []) {
  const merged = [...(existingProducts || [])];
  const keys = new Set(merged.map(productKey));
  for (const product of estimateProducts || []) {
    const key = productKey(product);
    if (keys.has(key)) continue;
    keys.add(key);
    merged.push(product);
  }
  return merged;
}

export function selectExistingEstimateWorkOrder(rows = [], linkedWorkOrderId = "") {
  const activeRows = (rows || []).filter((row) => row?.deleted !== true);
  if (linkedWorkOrderId) {
    const linked = activeRows.find((row) => row.id === linkedWorkOrderId);
    if (linked) return linked;
  }
  return activeRows.slice().sort((a, b) => {
    const aTime = Date.parse(a?.created_date || a?.updated_date || "") || 0;
    const bTime = Date.parse(b?.created_date || b?.updated_date || "") || 0;
    if (aTime !== bTime) return aTime - bTime;
    return String(a?.id || "").localeCompare(String(b?.id || ""));
  })[0] || null;
}

export function convertedWorkOrderStage(existingStage) {
  // Do not move a WorkOrder backward if operations has already advanced it.
  if (existingStage && !["estimating", "sales"].includes(existingStage)) return existingStage;
  return "sales";
}

// --- D-06: conversion history events -----------------------------------------
// ProductActivity-shaped rows (base44/entities/ProductActivity.jsonc) emitted
// onto the WorkOrder payload as conversion_events[]. The frontend build path
// can't write backend-only entities itself, so the rows ride the payload and
// a backend/portal write path persists them later as the job's audit trail.
// `label` duplicates `note` — the order-history feed renders row.label first.

const CONVERSION_ACTOR_TYPES = ["staff", "customer", "vendor", "system"];

const conversionActorParts = (actor) => {
  if (actor && typeof actor === "object") {
    const type = CONVERSION_ACTOR_TYPES.includes(norm(actor.type)) ? norm(actor.type) : "staff";
    return { type, label: firstNonBlank(actor.label, actor.name, actor.email, actor.display_name) };
  }
  return { type: "staff", label: String(actor ?? "").trim() };
};

// One typed conversion event. `product` is optional — omit it for the
// order-level row emitted when no estimate-seeded product matched.
export function buildConversionEvent({ estimate = {}, workOrder = null, product = null, actor = "", now = "" } = {}) {
  const parsedNow = now ? new Date(now) : null;
  const occurred_at = (parsedNow && !Number.isNaN(parsedNow.getTime()) ? parsedNow : new Date()).toISOString();
  const status = String(estimate?.status || "approved").trim().toUpperCase() || "APPROVED";
  const label = `Estimate Converted to Order - via product status (${status})`;
  const who = conversionActorParts(actor);
  const estimateId = String(estimate?.id || "").trim();
  const workOrderId = String(workOrder?.id || "").trim();
  const productId = String(product?.id || "").trim();
  return {
    schema_version: 1,
    // Stable retry-safe receipt — rebuilding the same conversion regenerates
    // the same key, so a persist path honoring creation_request_key and the
    // merge helper below never double-write history.
    creation_request_key: `estimate_conversion:${estimateId || "unknown"}:${workOrderId || "new"}:${productId || "order"}`,
    work_order_id: workOrderId,
    product_id: productId,
    product_label: firstNonBlank(product?.description, product?.client_product_name, product?.product_name),
    event_type: "conversion",
    label,
    actor_type: who.type,
    actor_label: who.label,
    from_value: firstNonBlank(estimate?.estimate_number, estimateId),
    to_value: firstNonBlank(workOrder?.title, workOrderId),
    note: label,
    occurred_at,
    details: {
      source: "estimate_conversion",
      estimate_id: estimateId,
      estimate_number: String(estimate?.estimate_number || ""),
      conversion_status: status,
      estimate_line_id: String(product?.estimate_line_id || ""),
      builder_product_id: String(product?.builder_product_id || ""),
    },
  };
}

// One conversion event per product THIS estimate seeded — matched by
// source_estimate_id or the estimate's own line/product refs, so pre-existing
// products a merged WO carries from other estimates are excluded. When no
// product matches, one order-level row still lands so every conversion is
// audible in history.
export function buildConversionEvents({ estimate = {}, workOrder = null, products = [], actor = "", now = "" } = {}) {
  const estimateId = String(estimate?.id || "").trim();
  const lineIds = new Set();
  const builderProductIds = new Set();
  for (const line of estimate?.line_items || []) {
    const lineId = String(line?.line_id || "").trim();
    const builderProductId = String(line?.builder_product_id || "").trim();
    if (lineId) lineIds.add(lineId);
    if (builderProductId) builderProductIds.add(builderProductId);
  }
  const mine = (Array.isArray(products) ? products : []).filter((product) => {
    if (!product || typeof product !== "object") return false;
    if (estimateId && String(product?.source_estimate_id || "").trim() === estimateId) return true;
    if (lineIds.has(String(product?.estimate_line_id || "").trim())) return true;
    if (builderProductIds.has(String(product?.builder_product_id || "").trim())) return true;
    return false;
  });
  if (!mine.length) return [buildConversionEvent({ estimate, workOrder, actor, now })];
  return mine.map((product) => buildConversionEvent({ estimate, workOrder, product, actor, now }));
}

// Append-only merge keyed on creation_request_key — rebuilding the same
// conversion never duplicates a history row already on the job.
export function mergeConversionEvents(existing = [], incoming = []) {
  const merged = [...(Array.isArray(existing) ? existing : [])];
  const keys = new Set(merged.map((evt) => String(evt?.creation_request_key || "")).filter(Boolean));
  for (const evt of Array.isArray(incoming) ? incoming : []) {
    if (!evt || typeof evt !== "object") continue;
    const key = String(evt?.creation_request_key || "");
    if (key && keys.has(key)) continue;
    if (key) keys.add(key);
    merged.push(evt);
  }
  return merged;
}

// L-10: converted WO estimate_amount falls back quoteTotal → estimate.quote_total
// → accepted line-item sum (same math as the conversion credit check), so a WO
// never lands at $0 just because the caller omitted pricing.quoteTotal.
export function estimateConvertedAmount(estimate = {}, pricing = {}) {
  const priced = num(pricing?.quoteTotal, NaN);
  if (Number.isFinite(priced)) return priced;
  const quoted = num(estimate?.quote_total, NaN);
  if (Number.isFinite(quoted) && quoted > 0) return quoted;
  return (estimate?.line_items || []).reduce(
    (sum, l) => sum + acceptedCustomerUnitPrice(l) * Math.max(1, Number(l?.customer_quantity) || 1),
    0,
  );
}

export function buildConvertedWorkOrderFields({ estimate = {}, pricing = {}, existing = null, products = [], generatedDescription = "", conversionDate = "", verifiedCustomerId = "", actor = "", now = "" } = {}) {
  return {
    title: firstNonBlank(estimate.project_name, existing?.title),
    client_name: firstNonBlank(estimate.client_name, existing?.client_name),
    // Conversion must not revive a stale estimate.customer_id. The caller passes
    // only a Customer ID verified against the live Customer entity.
    customer_id: verifiedCustomerId || "",
    estimate_id: estimate.id || existing?.estimate_id || "",
    // Upstream chain links: the Opportunity workspace and invoice creation
    // aggregate Work Orders by opportunity_id/estimating_request_id — an
    // existing WO keeps its original links when estimates merge into it.
    opportunity_id: firstNonBlank(existing?.opportunity_id, estimate.opportunity_id),
    estimating_request_id: firstNonBlank(existing?.estimating_request_id, estimate.estimating_request_id),
    // Preserve richer sales/production notes already entered on the pipeline lead.
    description: firstNonBlank(existing?.description, generatedDescription),
    current_stage: convertedWorkOrderStage(existing?.current_stage),
    sales_status: "won",
    install_location: firstNonBlank(estimate.site_address, existing?.install_location),
    contact_name: firstNonBlank(estimate.contact_name, estimate.order_contact, existing?.contact_name),
    contact_email: firstNonBlank(estimate.contact_email, existing?.contact_email),
    contact_phone: firstNonBlank(estimate.contact_phone, estimate.office_phone, existing?.contact_phone),
    representative: firstNonBlank(estimate.order_contact, existing?.representative),
    sales_rep: firstNonBlank(estimate.salesperson, existing?.sales_rep),
    estimator: firstNonBlank(estimate.salesperson, existing?.estimator),
    estimate_amount: estimateConvertedAmount(estimate, pricing),
    date_order_created: firstNonBlank(existing?.date_order_created, conversionDate),
    corbridge_invoice_number: firstNonBlank(estimate.estimate_number, existing?.corbridge_invoice_number),
    project_install_date: firstNonBlank(estimate.target_install_date, existing?.project_install_date),
    in_pipeline: true,
    // B-14: order due = max product due date (engine rollup). push_forward_only
    // over the existing date means a merge can push the job later but never
    // pulls it earlier; no product dates echoes the existing date unchanged.
    due_date: (typeof computeOrderDueDate === "function"
      ? computeOrderDueDate({
          products,
          existing_due_date: existing?.due_date || "",
          hard_due_date: existing?.hard_due_date === true,
          push_forward_only: true,
          label: "estimate_conversion",
        }).due_date
      : existing?.due_date) || "",
    products,
    // D-06: conversion history events ride the WO payload — ProductActivity-
    // shaped rows a backend/portal write path can persist as the audit trail.
    conversion_events: mergeConversionEvents(
      existing?.conversion_events,
      buildConversionEvents({ estimate, workOrder: existing, products, actor, now }),
    ),
  };
}

// Apply an operational-status patch to a single product inside WorkOrder.products
// through the CAS-backed array mutation helper. Returns the saved WorkOrder.
export async function transitionProductOperationalStatus({ workOrderId, productId, patch = {}, actor = "", overrideHardDue = false, label = "Product status" } = {}) {
  const targetId = String(productId || "").trim();
  if (!targetId) throw new Error(`${label}: this product has no id. Reopen the Work Order to repair it.`);
  return mutateWorkOrderArrayField({
    workOrderId,
    field: "products",
    label,
    mutate: (products) => {
      const index = products.findIndex((product) => String(product?.id || "") === targetId);
      if (index < 0) throw new Error(`${label}: this product is no longer on the Work Order. Reload and try again.`);
      const next = applyProductOperationalPatch(products[index], patch, { actor, overrideHardDue });
      if (next === products[index]) return products;
      const nextProducts = [...products];
      nextProducts[index] = next;
      return nextProducts;
    },
  });
}

// CoreBridge due-date rule mirrored: when a product reaches proof approval its
// due date is recalculated from part lead times, a hard due date is never
// moved, and the recalculation only pushes the date forward — all enforced by
// the shared engine in base44/shared/dueDateEngine.ts. This wrapper keeps the
// legacy name/signature and returns the "YYYY-MM-DD" date string the
// operational patch consumes.
//
// Lead-day precedence: an explicit positive `leadTimeDays` (ProofPanel's
// "Lead days" input) becomes a numeric tier override applied per part — each
// part keeps its own min-days floor. When the product carries no parts at all
// the explicit days form a synthesized single-part lead so the manual override
// still lands on unlinked products. With no override the engine's per-part
// min/std/add resolution decides; no parts and no override leaves the existing
// due date unchanged. An explicit `tier` ("standard"|"minimum"|"additional"|
// number) outranks `leadTimeDays`. `parts` defaults to the product's embedded
// part_list/builder_parts/parts when the caller didn't load BuilderPart rows.
export function recalculateProductDueDateOnProofApproval({ product = {}, leadTimeDays = 0, parts, tier, fromDate = new Date() } = {}) {
  const explicit = num(leadTimeDays, 0);
  const hasOverride = explicit > 0;
  const embedded = parts !== undefined
    ? parts
    : product?.parts ?? product?.part_list ?? product?.builder_parts;
  const hasParts = Array.isArray(embedded) && embedded.length > 0;
  const result = recalcOnProofApproval({
    product,
    approval_date: fromDate,
    parts: hasParts ? embedded : (hasOverride ? [{ product_lead_days: explicit }] : []),
    tier: tier !== undefined ? tier : (hasOverride && hasParts ? explicit : "standard"),
  });
  return result.due_date || product?.product_due_date || "";
}

// Sync an operational-status patch back to the linked BuilderProduct so the
// estimator-side record stays truthful. CAS on updated_date; a sync failure
// returns synced:false rather than throwing so the WorkOrder transition is
// never rolled back by a builder-record write issue.
export async function syncBuilderProductOperationalStatus({ builderProductId, fields = null, patch = {}, expectedUpdatedDate = "" } = {}) {
  let apply;
  if (fields && typeof fields === "object") {
    apply = {};
    for (const field of PRODUCT_OPERATIONAL_FIELDS) {
      if (fields[field] !== undefined) apply[field] = fields[field];
    }
  } else {
    apply = buildProductOperationalPatch(patch);
  }
  const id = String(builderProductId || "").trim();
  if (!id || !Object.keys(apply).length) return { synced: false, reason: "nothing_to_apply" };
  const entity = staffEntities?.BuilderProduct;
  if (!entity?.updateMany) return { synced: false, reason: "unavailable" };
  const live = await entity.get(id).catch(() => null);
  if (!live?.id) return { synced: false, reason: "not_found" };
  if (expectedUpdatedDate && String(live.updated_date || "") !== String(expectedUpdatedDate)) {
    return { synced: false, reason: "stale" };
  }
  const result = await entity.updateMany({ id, updated_date: live.updated_date }, { $set: apply }).catch(() => null);
  if (!result || (typeof result.updated === "number" && result.updated < 1)) return { synced: false, reason: "write_failed" };
  return { synced: true };
}

// Transition a work-order product and best-effort sync the same patch to the
// linked BuilderProduct in one call.
export async function transitionProductAndBuilderStatus({ workOrderId, product, patch = {}, actor = "", overrideHardDue = false, label = "Product status", workOrder = null } = {}) {
  // Deposit gate (warn-only, never a hard block): a product moving INTO a
  // production status on a job whose deposit is required but not yet invoiced
  // asks once â€” "Deposit required $X â€” proceed anyway?" Callers holding the
  // Work Order pass it via `workOrder`; otherwise the live record is fetched.
  // The extra read only happens for production-bound moves, so ordinary
  // status edits never pay for it, and re-picking the held status no-ops.
  // The effective target is the explicit status, or the auto-advance to
  // proof_approved that applyProductOperationalPatch performs when a proof is
  // approved while the product awaits approval (the proof-approval path
  // releases the product to production, so it is gated the same way).
  let targetStatus = norm(patch?.operationalStatus);
  if (!targetStatus && norm(patch?.proofStatus) === "approved" && norm(product?.operational_status) === "awaiting_proof_approval") {
    targetStatus = "proof_approved";
  }
  if (targetStatus && DEPOSIT_GATED_STATUSES.has(targetStatus) && targetStatus !== norm(product?.operational_status)) {
    const woSnapshot = workOrder && typeof workOrder === "object"
      ? workOrder
      : await staffEntities.WorkOrder.get(String(workOrderId || "").trim()).catch(() => null);
    if (
      depositGateApplies(woSnapshot, product, targetStatus)
      && typeof window !== "undefined" && typeof window.confirm === "function"
      && !window.confirm(depositGateMessage(woSnapshot))
    ) {
      throw Object.assign(new Error("Deposit required â€” the move into production was not applied."), { depositCancelled: true });
    }
  }
  const saved = await transitionProductOperationalStatus({ workOrderId, productId: product?.id, patch, actor, overrideHardDue, label });
  const savedProducts = Array.isArray(saved?.products) ? saved.products : [];
  const savedProduct = savedProducts.find((row) => String(row?.id || "") === String(product?.id || "")) || null;
  let sync = { synced: false, reason: "no_builder_link" };
  if (product?.builder_product_id) {
    sync = await syncBuilderProductOperationalStatus({
      builderProductId: product.builder_product_id,
      fields: savedProduct || {},
    }).catch(() => ({ synced: false, reason: "error" }));
  }
  // Unified alerts: one product_transition event per actual status change —
  // emitting here in the shared helper covers every caller (product queues,
  // proof panel, job workspace). Fire-and-forget; a notify failure never
  // blocks the transition.
  const previousStatus = String(product?.operational_status || "none").trim() || "none";
  const nextStatus = String(savedProduct?.operational_status || previousStatus).trim() || previousStatus;
  if (saved?.id && savedProduct && previousStatus !== nextStatus) {
    try {
      void NotificationTriggers.productTransition(saved, {
        productId: savedProduct.id || product?.id,
        productDescription: savedProduct.description || product?.description,
        previousStatus,
        newStatus: nextStatus,
        changedBy: actor,
      });
    } catch { /* notify is best-effort */ }
  }
  return { workOrder: saved, product: savedProduct, builderSynced: sync.synced === true };
}

// Cost engine for the Concrete | Masonry | Poles estimator.
//
// All math is ported from SignEstimate Pro and must stay identical to it:
//  - per-item concrete / rebar / forming / finishing / pouring / excavation → legacyFoundationCalc.js
//  - project concrete delivery (trucks, fees, stops)                        → legacyFoundationCalc.js
//  - masonry walls (outer + internal fill wall)                            → wallCalculator.js
//  - poles + pole painting                                                  → poleCalculator.js
//  - wall caps (full stock charged per cut piece)                           → wallCapCalculator.js
//
// Rollup (verbatim from SignEstimate Pro `totals`):
//   grand = itemsTotal(+concrete delivery) + wallTotal + polesTotal + equipmentTotal + wallCapTotal
// Poles, walls, caps and fill are PROJECT-level — they are never charged on a foundation item.

import { calcItemCost as legacyCalcItemCost, calcConcreteDelivery } from "./legacyFoundationCalc";
import { calcWalls } from "./wallCalculator";
import { calcPoles } from "./poleCalculator";
import { calcWallCaps } from "./wallCapCalculator";
import { foundationAssemblyCatalogIssues, foundationItemCatalogIssues, hasFoundationCostSnapshot } from "./foundationCatalogIntegrity";
import { resolveFoundationEquipment } from "./foundationEquipmentBindings";
import { foundationItemInputIssues, foundationProjectInputIssues } from "./foundationInputValidation";

const num = (v, d = 0) => (Number.isFinite(Number(v)) ? Number(v) : d);

const REBAR_LB_PER_FT = { "#3": 0.376, "#4": 0.668, "#5": 1.043, "#6": 1.502, "#7": 2.044, "#8": 2.67 };

const ITEM_SNAPSHOT_FIELDS = [
  "concrete_volume_cy", "excavation_volume_cy", "concrete_bags", "rebar_feet", "rebar_weight_lbs",
  "concrete_cost", "concrete_rate", "rebar_cost", "rebar_rate", "excavation_cost", "excavation_hours",
  "forming_cost", "forming_qty", "pouring_cost", "finishing_cost", "finishing_hours", "item_total_cost",
];

export function calcItem(item, project, inventory, settings = {}, savedItem = item) {
  const inputIssues = foundationItemInputIssues(item);
  if (inputIssues.length || foundationItemCatalogIssues(item, inventory).length) {
    return {
      quantity: inputIssues.length ? item.quantity : Math.max(1, num(item.quantity, 1)),
      ...Object.fromEntries(ITEM_SNAPSHOT_FIELDS.map(key => [
        key, hasFoundationCostSnapshot(savedItem?.[key]) ? savedItem[key] : undefined,
      ])),
    };
  }
  // Items without their own excavation method fall back to the project default.
  const legacy = legacyCalcItemCost(
    { ...item, excavation_method: item.excavation_method || project?.excavation_method },
    inventory,
    settings
  );
  const isPillar = item.foundation_type === "pillar";
  const rebarSize = (isPillar ? item.pillar_rebar_size : item.rebar_size) || "#4";

  return {
    quantity: Math.max(1, num(item.quantity, 1)),
    concrete_volume_cy: legacy.volumeCY,
    excavation_volume_cy: legacy.volumeCY * 1.25,
    concrete_bags: legacy.concreteBags,
    rebar_feet: legacy.rebarFt,
    rebar_weight_lbs: legacy.rebarFt * (REBAR_LB_PER_FT[rebarSize] || 0.668),
    concrete_cost: legacy.concreteCost,
    concrete_rate: legacy.concreteRate,
    rebar_cost: legacy.rebarCost,
    rebar_rate: legacy.rebarRate,
    excavation_cost: legacy.excavationCost,
    excavation_hours: legacy.excavationHours,
    forming_cost: legacy.formingCost,
    forming_qty: legacy.formingQty,
    pouring_cost: legacy.pouringCost,
    finishing_cost: legacy.finishingCost,
    finishing_hours: legacy.finishingHours,
    item_total_cost: legacy.total,
  };
}

// Equipment rental — ported from SignEstimate Pro `equipmentTotal`.
export function calcEquipmentPricing(selected, inventory = []) {
  return (selected || []).map((storedEntry, index) => {
    const entry = storedEntry || {};
    const bindings = resolveFoundationEquipment(entry, inventory, index);
    const eq = bindings.equipment;
    const rentalPeriod = entry.rental_period || "day";
    const durationOverride =
      entry.custom_qty !== undefined && entry.custom_qty !== null ? entry.custom_qty : entry.rental_duration || 1;
    const context = { ...bindings, rentalPeriod, duration: durationOverride };
    if (bindings.issues.length) {
      return {
        ...context, pricedEntry: { ...entry }, baseCost: null, deliveryCost: null,
        totalCost: entry.equipment_cost,
        attachmentRows: bindings.attachmentRows.map(row => ({ ...row, cost: null })),
        subAttachmentRows: bindings.subAttachmentRows.map(row => ({ ...row, cost: null })),
      };
    }

    const getRentalCost = (item, rateOverride) => {
      if (rateOverride !== undefined && rateOverride !== null) return rateOverride * durationOverride;
      if (rentalPeriod === "day") return num(item.cost_per_day) * durationOverride;
      if (rentalPeriod === "week") return num(item.cost_per_week) * durationOverride;
      if (rentalPeriod === "month") return num(item.cost_per_month) * durationOverride;
      return 0;
    };

    const baseCost = getRentalCost(eq, entry.custom_rate);
    let entryTotal = baseCost;
    const deliveryCharge =
      entry.custom_delivery_charge !== undefined && entry.custom_delivery_charge !== null
        ? entry.custom_delivery_charge
        : num(eq.pickup_delivery_cost);
    if (entry.include_delivery) entryTotal += deliveryCharge;

    const pricedLines = rows => rows.map(row => {
      // Zero-count legacy keys may point at removed records and are not rented.
      if (!row.inventory) return { ...row, cost: 0 };
      const cost = getRentalCost(row.inventory) * row.quantity;
      entryTotal += cost;
      return { ...row, cost };
    });
    const attachmentRows = pricedLines(bindings.attachmentRows);
    const subAttachmentRows = pricedLines(bindings.subAttachmentRows);
    return {
      ...context, pricedEntry: { ...entry, equipment_cost: entryTotal },
      baseCost, deliveryCost: entry.include_delivery ? deliveryCharge : 0,
      attachmentRows, subAttachmentRows, totalCost: entryTotal,
    };
  });
}

export function calcEquipment(selected, inventory = []) {
  return calcEquipmentPricing(selected, inventory).map(row => row.pricedEntry);
}

export function equipmentCostTotal(pricedEntries = []) {
  return pricedEntries.reduce((sum, entry) => sum + num(entry.equipment_cost), 0);
}

export function captureConcreteDeliverySnapshot(delivery) {
  return {
    version: 1, concrete_total: delivery.concreteTotal, rounded_yards: delivery.roundedYards,
    rate_per_yard: delivery.ratePerYard, additional_stops_cost: delivery.additionalStopsCost,
    trucks: delivery.trucksList.map(truck => ({
      yards: truck.yards, rounded_yards: truck.roundedYards, cost: truck.cost,
      small_order_fee: truck.smallOrderFee, fuel_fee: truck.fuelFee,
    })),
  };
}

function savedConcreteDelivery(project) {
  const snapshot = project?.concrete_delivery_snapshot?.version === 1 ? project.concrete_delivery_snapshot : null;
  const value = (record, key) => hasFoundationCostSnapshot(record?.[key]) ? record[key] : undefined;
  return {
    pricingUnavailable: true,
    concreteTotal: value(snapshot, "concrete_total"), roundedYards: value(snapshot, "rounded_yards"),
    ratePerYard: value(snapshot, "rate_per_yard"), additionalStopsCost: value(snapshot, "additional_stops_cost"),
    trucksList: (Array.isArray(snapshot?.trucks) ? snapshot.trucks : []).map(truck => ({
      yards: value(truck, "yards"), roundedYards: value(truck, "rounded_yards"), cost: value(truck, "cost"),
      smallOrderFee: value(truck, "small_order_fee"), fuelFee: value(truck, "fuel_fee"),
    })),
    availableMixes: [], availableAdmixes: [],
  };
}

export function calcProject(project, inventory, settings = {}, options = {}) {
  const explicitSnapshot = Object.prototype.hasOwnProperty.call(options, "savedProject");
  const savedProject = !explicitSnapshot ? project
    : project.id !== undefined && project.id !== null && project.id !== "" && options.savedProject?.id === project.id
      ? options.savedProject : null;
  const sourceItems = project.items || [];
  const savedItems = new Map();
  const currentIds = new Map();
  for (const item of savedProject?.items || []) {
    if (item.component_id) savedItems.set(item.component_id, savedItems.has(item.component_id) ? null : item);
  }
  for (const item of sourceItems) currentIds.set(item.component_id, (currentIds.get(item.component_id) || 0) + 1);
  const catalogIssues = foundationAssemblyCatalogIssues(project, inventory);
  const inputIssues = foundationProjectInputIssues(project);
  const itemPricing = sourceItems.map((item, index) => {
    const issues = [
      ...catalogIssues.filter(issue => issue.kind === "foundation" && issue.index === index),
      ...inputIssues.filter(issue => issue.index === index),
    ];
    return { available: issues.length === 0, issues };
  });
  const items = sourceItems.map((item) => {
    const savedItem = !explicitSnapshot ? item
      : item.component_id && currentIds.get(item.component_id) === 1 ? savedItems.get(item.component_id) || null : null;
    return { ...item, ...calcItem(item, project, inventory, settings, savedItem) };
  });
  const equipment = calcEquipment(project.selected_equipment, inventory);
  // An incomplete item has saved quantities, so its coupled order must not be repriced.
  const delivery = itemPricing.some(item => !item.available) ? savedConcreteDelivery(savedProject) : calcConcreteDelivery(
    { ...project, settings },
    (project.items || []).map((i) => ({
      ...i,
      excavation_method: i.excavation_method || project.excavation_method,
    })),
    inventory
  );
  const walls = calcWalls(project, inventory, settings);
  const poles = calcPoles(project.poles, inventory, settings);
  const wallCaps = calcWallCaps(project.wall_caps, inventory);

  const sum = (key) => items.some((item, index) => !itemPricing[index].available && !hasFoundationCostSnapshot(item[key]))
    ? null : items.reduce((s, i) => s + num(i[key]), 0);
  const addKnown = (a, b) => hasFoundationCostSnapshot(a) && hasFoundationCostSnapshot(b) ? a + b : null;
  const category = (key, value) => value !== null ? value
    : hasFoundationCostSnapshot(savedProject?.[key]) ? savedProject[key] : null;

  const itemsTotal = addKnown(sum("item_total_cost"), delivery.concreteTotal);
  const wallTotal = walls.reduce((s, w) => s + num(w.calculatedCosts?.totalCost), 0);
  const polesTotal = poles.reduce((s, p) => s + num(p.total_cost), 0);
  const equipmentTotal = equipmentCostTotal(equipment);

  const totals = {
    // Bagged concrete is priced per item; ready-mix is priced per delivered truck.
    total_concrete_cost: category("total_concrete_cost", addKnown(sum("concrete_cost"), delivery.concreteTotal)),
    concrete_delivery_cost: delivery.concreteTotal,
    concrete_delivered_yards: delivery.roundedYards,
    concrete_rate_per_yard: delivery.ratePerYard,
    concrete_trucks: delivery.trucksList,
    additional_stops_cost: delivery.additionalStopsCost,
    total_rebar_cost: category("total_rebar_cost", sum("rebar_cost")),
    total_excavation_cost: category("total_excavation_cost", sum("excavation_cost")),
    total_forming_materials_cost: category("total_forming_materials_cost", sum("forming_cost")),
    total_labor_cost: category("total_labor_cost", addKnown(sum("pouring_cost"), sum("finishing_cost"))),
    total_pole_cost: poles.reduce((s, p) => s + num(p.pole_cost), 0),
    total_pole_painting_cost: poles.reduce((s, p) => s + num(p.pole_painting_cost), 0),
    total_brick_cost: walls.reduce((s, w) => s + num(w.calculatedCosts?.materialCost), 0),
    total_fill_cost: walls.reduce((s, w) => s + num(w.calculatedCosts?.internalMaterialCost), 0),
    total_equipment_cost: equipmentTotal,
    total_wall_cost: wallTotal,
    total_wall_cap_cost: wallCaps.total,
    wall_caps_by_material: wallCaps.byInventory,
    total_concrete_volume_cy: sum("concrete_volume_cy"),
    total_excavation_volume_cy: sum("excavation_volume_cy"),
    total_labor_hours: addKnown(sum("finishing_hours"), sum("excavation_hours")),
  };

  totals.grand_total = itemsTotal === null ? null : itemsTotal + wallTotal + polesTotal + equipmentTotal + wallCaps.total;

  return {
    items, equipment, walls, poles, wallCaps: wallCaps.caps, totals, delivery, itemPricing, catalogIssues, inputIssues,
  };
}

export const money = (n) =>
  `$${num(n).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

import { base44 } from "@/api/base44Client";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { requiresBuilderReattach } from "@/components/estimator/parts/partState";
import { calculateVinylProject } from "@/components/vinylEstimator/vinylNestingCalculator";
import { calcBrickStoneProject } from "@/components/estimator/brick/brickCalc";
import { calcServiceItem, calcProjectTotals } from "@/components/signMaintenance/maintenanceCalculator";
import { acceptedCustomerUnitPrice, liveCustomerUnitPrice } from "@/components/estimator/customerPricing";
import { assertEstimateProductMutationAllowed } from "@/components/estimator/estimateMutationGuard";
import { builderMutationHash, markBuilderMutationPending, pendingBuilderMutation, resumeBuilderMutation } from "./builderMutationRecovery";
import { expectedBuilderEntityFields, replaceBuilderEntityFieldsIfUnchanged } from "./builderEntityPersistence";
import { createBuilderPartWithRecovery } from "./builderPartPersistence";
import { staffEntities } from "@/components/staff/staffEntities";

const num = (value, fallback = 0) =>
  Number.isFinite(Number(value)) ? Number(value) : fallback;
const nowIso = () => new Date().toISOString();
const norm = (value) => String(value || "").trim().toLowerCase().replace(/\s+/g, " ");

// These Builders can recompute their complete current Product economics directly
// from the saved Builder configuration + current catalogs during estimate refresh.
// Other catalog-backed Builders must be reopened/saved before Update Price when a
// Master Inventory price changes after the last Builder calculation.
const DIRECT_LIVE_REPRICE_MODULES = new Set(["brick_stone", "maintenance"]);
const PENDING_REMOVAL_KEY = "__builder_pending_removal";

const CATALOG_NAME_FIELDS = {
  FoundationInventory: ["material_name"],
  LaborServiceInventory: ["service_name", "vendor_name"],
  ChannelLetterInstallInventory: ["item_name"],
  ChannelLetterInstallEquipment: ["equipment_name"],
  DimensionalLetterMaterial: ["material_name"],
  VinylInventory: ["vinyl_name"],
  VinylMachine: ["machine_name"],
  Inventory: ["material_type", "product_type", "size"],
  BrickStoneInventory: ["material_name"],
  MaintenanceInventory: ["item_name"],
  MaintenanceEquipment: ["equipment_name"],
};

function rowName(entity, row) {
  if (!row) return "";
  const fields = CATALOG_NAME_FIELDS[entity] || ["name"];
  if (entity === "Inventory") {
    return fields.map((field) => row[field]).filter(Boolean).join(" ");
  }
  return fields.map((field) => row[field]).find(Boolean) || "";
}

function stableObject(value) {
  if (Array.isArray(value)) return value.map(stableObject);
  if (!value || typeof value !== "object") return value;
  return Object.fromEntries(
    Object.keys(value)
      .sort()
      .filter((key) => !["created_by", "created_by_id"].includes(key))
      .map((key) => [key, stableObject(value[key])])
  );
}

function same(a, b) {
  return JSON.stringify(stableObject(a ?? null)) === JSON.stringify(stableObject(b ?? null));
}

function patchDiffers(record, patch) {
  return Object.entries(patch || {}).some(([key, value]) => !same(record?.[key], value));
}

export function pricingSnapshot(row) {
  if (!row || typeof row !== "object") return {};
  const out = {};
  Object.entries(row).forEach(([key, value]) => {
    if (["id", "created_date", "updated_date", "created_by", "created_by_id", "price_history"].includes(key)) return;
    if (
      /(cost|price|rate|fee|charge|markup|surcharge)/i.test(key) ||
      [
        "pricing_mode",
        "pole_pricing_mode",
        "unit",
        "unit_type",
        "quantity_tiers",
        "minimum_order_yards",
        "minimum_order_quantity",
        "waste_factor_percent",
        "yield_factor",
      ].includes(key)
    ) {
      out[key] = stableObject(value);
    }
  });
  return out;
}

function genericUnitCost(row) {
  if (!row) return 0;
  const preferred = [
    "cost_per_unit",
    "default_rate",
    "cost_per_letter",
    "cost_per_cabinet",
    "cost_per_foot",
    "cost_per_sqft",
    "cost_per_linear_foot",
    "cost_per_roll",
    "cost_per_sheet",
    "cost_per_hour",
    "cost_per_day",
    "cost_flat",
    "pole_stock_price",
    "cap_stock_price",
  ];
  for (const key of preferred) {
    if (Number.isFinite(Number(row[key])) && Number(row[key]) !== 0) return Number(row[key]);
  }
  return 0;
}

function independentPartUnitCost(part, row) {
  if (!row) return num(part?.current_unit_cost, num(part?.frozen_unit_cost));
  const entity = part?.inventory_entity || "";
  const mode = part?.pricing_basis_snapshot?.pricing_mode || row.pricing_mode || row.pole_pricing_mode || row.unit_type || "";
  if (entity === "DimensionalLetterMaterial") return num(row.cost_per_sheet);
  if (entity === "VinylInventory") {
    if (mode === "per_sqft") return num(row.cost_per_sqft);
    if (mode === "per_linear_foot") return num(row.cost_per_linear_foot);
    return num(row.cost_per_roll);
  }
  if (entity === "LaborServiceInventory") return num(row.default_rate);
  if (entity === "ChannelLetterInstallInventory") {
    if (mode === "per_raceway_foot") return num(row.cost_per_foot);
    if (mode === "per_project_flat") return num(row.cost_flat);
    if (mode === "per_letter_by_size") {
      const size = part?.pricing_basis_snapshot?.letter_size || "medium";
      return num(row[`cost_${size}`], num(row.cost_medium || row.cost_per_letter));
    }
    return num(row.cost_per_letter);
  }
  if (entity === "ChannelLetterInstallEquipment") {
    if (mode === "delivery_pickup") return num(row.delivery_pickup_cost);
    if (mode === "idle_running") return num(row.idle_running_cost_per_hour);
    if (mode === "per_hour") return num(row.cost_per_hour);
    if (mode === "per_week") return num(row.cost_per_week);
    if (mode === "per_month") return num(row.cost_per_month);
    if (["owned_flat", "per_project_flat"].includes(mode)) return num(row.cost_flat);
    return num(row.cost_per_day);
  }
  if (entity === "MaintenanceInventory") {
    const size = part?.pricing_basis_snapshot?.size || "medium";
    if (mode === "per_letter_flat") return num(row.cost_per_letter);
    if (mode === "per_letter_by_size" || mode === "per_cabinet_by_size") return num(row[`cost_${size}`]);
    if (mode === "per_cabinet_flat") return num(row.cost_per_cabinet);
    if (mode === "per_linear_foot") return num(row.cost_per_foot);
    if (mode === "per_sqft") return num(row.cost_per_sqft);
    return num(row.cost_flat);
  }
  if (entity === "MaintenanceEquipment") {
    if (mode === "delivery_pickup") return num(row.delivery_pickup_cost);
    if (mode === "idle_running") return num(row.idle_running_cost_per_hour);
    if (mode === "per_hour") return num(row.cost_per_hour);
    if (mode === "per_week") return num(row.cost_per_week);
    if (mode === "per_month") return num(row.cost_per_month);
    if (["owned_flat", "per_project_flat"].includes(mode)) return num(row.cost_flat);
    return num(row.cost_per_day);
  }
  if (entity === "FoundationInventory") {
    if (row.material_type === "pole" && mode === "stock_price") return num(row.pole_stock_price);
    if (row.material_type === "wall_cap") return num(row.cap_stock_price || row.cost_per_unit);
    if (["excavation_equipment", "attachment", "sub_attachment"].includes(row.material_type)) {
      if (mode === "pickup_delivery") return num(row.pickup_delivery_cost);
      if (mode === "per_week") return num(row.cost_per_week);
      if (mode === "per_month") return num(row.cost_per_month);
      if (mode === "per_hour") return num(row.cost_per_hour);
      return num(row.cost_per_day || row.cost_per_unit);
    }
    return num(row.cost_per_unit);
  }
  return num(row.cost_per_unit ?? row.default_rate ?? row.cost_flat ?? row.cost_per_sheet, genericUnitCost(row));
}

async function loadCatalog(entity, sort = null, { strict = false } = {}) {
  try {
    return await loadAllEntityRows({
      entity: staffEntities[entity],
      sort: sort || "created_date",
      label: `${entity} catalog`,
    });
  } catch (error) {
    if (strict) throw new Error(`${entity} catalog could not be verified: ${error?.message || "read failed"}`);
    return [];
  }
}

export async function loadBuilderCatalogs(moduleKey, { strict = false } = {}) {
  const specs = {
    foundation: [
      ["FoundationInventory", "material_name"],
      ["LaborServiceInventory", "service_name"],
    ],
    channel_letters: [
      ["ChannelLetterInstallInventory", "sort_order"],
      ["ChannelLetterInstallEquipment", "sort_order"],
      ["DimensionalLetterMaterial", "sort_order"],
    ],
    vinyl: [
      ["VinylInventory", "vinyl_name"],
      ["VinylMachine", "sort_order"],
      ["LaborServiceInventory", "service_name"],
      ["ChannelLetterInstallEquipment", "sort_order"],
    ],
    metal: [["Inventory", "material_type"]],
    brick_stone: [
      ["FoundationInventory", "material_name"],
      ["BrickStoneInventory", "material_name"],
    ],
    maintenance: [
      ["MaintenanceInventory", "sort_order"],
      ["SignLightingInventory", "sort_order"],
      ["SignHardwareInventory", "sort_order"],
      ["SignPartsSuppliesInventory", "sort_order"],
      ["DimensionalLetterMaterial", "sort_order"],
      ["VinylInventory", "sort_order"],
      ["ChannelLetterInstallInventory", "sort_order"],
      ["FoundationInventory", "material_name"],
      ["ChannelLetterInstallEquipment", "sort_order"],
      // Legacy compatibility only. New Maintenance selections use the shared
      // Master Inventory equipment catalog above.
      ["MaintenanceEquipment", "sort_order"],
      ["MaintenanceActionRate", null],
      ["Settings", null],
    ],
  };

  const requested = specs[moduleKey] || [];
  const loaded = await Promise.all(
    requested.map(async ([entity, sort]) => [entity, await loadCatalog(entity, sort, { strict })])
  );
  const catalogs = {};
  loaded.forEach(([entity, rows]) => {
    const filtered = entity === "LaborServiceInventory" && moduleKey === "foundation"
      ? rows.filter((row) => row.service_category === "concrete_service")
      : rows;
    catalogs[entity] = {
      rows: filtered,
      byId: new Map(filtered.map((row) => [row.id, row])),
    };
  });
  return catalogs;
}

export async function loadVerifiedBuilderPartSyncInputs({ builderProduct = null, moduleKey = "" } = {}) {
  const [catalogs, existingParts] = await Promise.all([
    loadBuilderCatalogs(moduleKey || builderProduct?.module_key || "", { strict: true }),
    builderProduct?.id
      ? loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProduct.id }, sort: "sort_order", label: "Builder Parts" })
      : Promise.resolve([]),
  ]);
  const inventoryRowsOverride = new Map();
  for (const part of existingParts || []) {
    if (part.builder_sync_state !== "manual_addon" || !part.inventory_entity || !part.inventory_item_id || part.manual_cost_override) continue;
    let row;
    try {
      row = await staffEntities[part.inventory_entity].get(part.inventory_item_id);
    } catch (error) {
      throw new Error(`${part.inventory_entity} inventory could not be verified for Part “${part.part_name || "Part"}”: ${error?.message || "read failed"}`);
    }
    inventoryRowsOverride.set(`${part.inventory_entity}:${part.inventory_item_id}`, row || null);
  }
  return { catalogs, existingParts: existingParts || [], inventoryRowsOverride };
}

function findRow(catalogs, entity, id) {
  if (!id) return null;
  if (entity && catalogs[entity]?.byId.has(id)) return catalogs[entity].byId.get(id);
  for (const catalog of Object.values(catalogs)) {
    if (catalog.byId.has(id)) return catalog.byId.get(id);
  }
  return null;
}

function findEntity(catalogs, id, preferred = "") {
  if (!id) return preferred;
  if (preferred && catalogs[preferred]?.byId.has(id)) return preferred;
  return Object.entries(catalogs).find(([, catalog]) => catalog.byId.has(id))?.[0] || preferred;
}

function findNameCandidate(catalogs, entity, name) {
  const target = norm(name);
  if (!target || !catalogs[entity]) return null;
  return catalogs[entity].rows.find((row) => norm(rowName(entity, row)) === target) || null;
}

function makePart({
  key,
  name,
  type = "material",
  subtype = "",
  sourcePath = "",
  entity = "",
  inventoryId = "",
  quantity = 1,
  unit = "",
  unitCost = 0,
  extendedCost = 0,
  builderData = {},
  calculation = {},
  pricingBasis = {},
}) {
  return {
    part_key: key,
    part_name: name || type || "Part",
    part_type: type,
    part_subtype: subtype,
    source_path: sourcePath,
    inventory_entity: entity,
    inventory_item_id: inventoryId || "",
    quantity: num(quantity, 1),
    unit,
    unit_cost: num(unitCost),
    extended_cost: num(extendedCost),
    builder_data: builderData || {},
    calculation_snapshot: calculation || {},
    pricing_basis_snapshot: pricingBasis || {},
  };
}

function extractChannel(project) {
  const parts = [];
  const hasNumber = (value) => value !== null && value !== undefined && Number.isFinite(Number(value));
  const itemLabel = (item, fallback) => item?.description?.trim() || fallback;

  // Installation materials are already persisted at their exact used quantity,
  // unit cost, and total by SignEstimate Pro's installCalculator.
  (project.items || []).forEach((item, itemIndex) => {
    (item.materials || []).forEach((mat, matIndex) => {
      const id = mat.inventory_item_id || mat.inventory_id || "";
      parts.push(makePart({
        key: `channel:item:${itemIndex}:material:${matIndex}`,
        name: mat.item_name || "Install material",
        type: "material",
        subtype: mat.pricing_mode || "install_material",
        sourcePath: mat.inventory_item_id
          ? `items[${itemIndex}].materials[${matIndex}].inventory_item_id`
          : `items[${itemIndex}].materials[${matIndex}].inventory_id`,
        entity: "ChannelLetterInstallInventory",
        inventoryId: id,
        quantity: mat.quantity,
        unit: mat.pricing_mode || "",
        unitCost: mat.unit_cost,
        extendedCost: mat.total_cost,
        builderData: { parent_item: item.description, installation_type: item.installation_type, letter_size: item.letter_size, qty_letters: item.qty_letters },
        calculation: mat,
        pricingBasis: { pricing_mode: mat.pricing_mode, letter_size: item.letter_size, installation_type: item.installation_type },
      }));
    });
  });

  // Git rule: personnel pricing REPLACES flat install labor when a crew is
  // assigned. Never emit both as billable Parts.
  const personnelRowsTotal = (project.personnel || []).reduce(
    (sum, person) => sum + num(person.total_cost, num(person.hourly_rate) * num(person.hours)),
    0
  );
  const personnelTotal = hasNumber(project.total_personnel_cost)
    ? num(project.total_personnel_cost)
    : personnelRowsTotal;
  const installLaborInSubtotal = hasNumber(project.labor_cost_in_subtotal)
    ? num(project.labor_cost_in_subtotal)
    : personnelTotal > 0.005
      ? 0
      : num(project.labor_cost, (project.items || []).reduce((sum, item) => sum + num(item.labor_cost), 0));

  if (Math.abs(installLaborInSubtotal) > 0.005) {
    let representedLabor = 0;
    (project.items || []).forEach((item, index) => {
      const cost = num(item.labor_cost);
      if (Math.abs(cost) <= 0.005) return;
      representedLabor += cost;
      parts.push(manualCostPart({
        key: `channel:item:${index}:labor`,
        name: `${itemLabel(item, `Install Item ${index + 1}`)} — Installation Labor`,
        type: "labor",
        subtype: "installation_labor",
        sourcePath: `items[${index}].labor_cost`,
        cost,
        quantity: item.labor_hours || 1,
        unit: item.labor_hours ? "hour" : "job",
        builderData: item,
        calculation: { labor_hours: item.labor_hours, labor_cost: item.labor_cost, installation_type: item.installation_type },
      }));
    });
    const laborResidual = installLaborInSubtotal - representedLabor;
    if (Math.abs(laborResidual) > 0.005) {
      parts.push(manualCostPart({
        key: "channel:install-labor:reconciliation",
        name: "Installation Labor — Saved Cost Adjustment",
        type: "labor",
        subtype: "installation_labor_adjustment",
        sourcePath: "labor_cost_in_subtotal",
        cost: laborResidual,
        calculation: { authoritative_total: installLaborInSubtotal, represented_total: representedLabor },
      }));
    }
  }

  // Equipment is persisted with all source pricing inputs. Split rental/use,
  // delivery/pickup, and idle running so every economic line is auditable.
  (project.selected_equipment || []).forEach((eq, index) => {
    const duration = Math.max(num(eq.duration, 1), 0);
    const baseCost = num(eq.unit_cost) * duration;
    const owned = eq.ownership === "owned" || eq.pricing_mode === "owned_flat";
    const deliveryCost = !owned && eq.include_delivery ? num(eq.delivery_pickup_cost) : 0;
    const idleCost = hasNumber(eq.idle_cost)
      ? num(eq.idle_cost)
      : num(eq.idle_hours) * num(eq.idle_running_cost_per_hour);
    const total = num(eq.total_cost, baseCost + deliveryCost + idleCost);
    let represented = 0;

    if (Math.abs(baseCost) > 0.005 || eq.equipment_id) {
      parts.push(makePart({
        key: `channel:equipment:${index}:base`,
        name: eq.equipment_name || "Install equipment",
        type: "equipment",
        subtype: eq.equipment_type || eq.pricing_mode || "equipment",
        sourcePath: `selected_equipment[${index}].equipment_id`,
        entity: "ChannelLetterInstallEquipment",
        inventoryId: eq.equipment_id,
        quantity: duration || 1,
        unit: eq.pricing_mode || "unit",
        unitCost: eq.unit_cost,
        extendedCost: baseCost,
        builderData: eq,
        calculation: { duration, unit_cost: eq.unit_cost, base_cost: baseCost },
        pricingBasis: { pricing_mode: eq.pricing_mode },
      }));
      represented += baseCost;
    }

    if (Math.abs(deliveryCost) > 0.005) {
      parts.push(makePart({
        key: `channel:equipment:${index}:delivery`,
        name: `${eq.equipment_name || "Install Equipment"} — Delivery / Pickup`,
        type: "service",
        subtype: "equipment_delivery",
        sourcePath: `selected_equipment[${index}].include_delivery`,
        entity: "ChannelLetterInstallEquipment",
        inventoryId: eq.equipment_id,
        quantity: 1,
        unit: "delivery",
        unitCost: deliveryCost,
        extendedCost: deliveryCost,
        builderData: eq,
        calculation: { include_delivery: eq.include_delivery, delivery_pickup_cost: deliveryCost },
        pricingBasis: { pricing_mode: "delivery_pickup" },
      }));
      represented += deliveryCost;
    }

    if (Math.abs(idleCost) > 0.005) {
      parts.push(makePart({
        key: `channel:equipment:${index}:idle`,
        name: `${eq.equipment_name || "Install Equipment"} — Idle Running`,
        type: "equipment",
        subtype: "idle_running",
        sourcePath: `selected_equipment[${index}].idle_hours`,
        entity: "ChannelLetterInstallEquipment",
        inventoryId: eq.equipment_id,
        quantity: eq.idle_hours || 1,
        unit: "hour",
        unitCost: eq.idle_running_cost_per_hour,
        extendedCost: idleCost,
        builderData: eq,
        calculation: { idle_hours: eq.idle_hours, idle_running_cost_per_hour: eq.idle_running_cost_per_hour, idle_cost: idleCost },
        pricingBasis: { pricing_mode: "idle_running" },
      }));
      represented += idleCost;
    }

    const residual = total - represented;
    if (Math.abs(residual) > 0.005) {
      parts.push(manualCostPart({
        key: `channel:equipment:${index}:saved-adjustment`,
        name: `${eq.equipment_name || "Install Equipment"} — Saved Cost Adjustment`,
        type: "equipment",
        subtype: "equipment_adjustment",
        sourcePath: `selected_equipment[${index}].total_cost`,
        cost: residual,
        builderData: eq,
        calculation: { authoritative_total: total, represented_total: represented },
      }));
    }
  });

  if (personnelTotal > 0.005 || (project.personnel || []).some((person) => num(person.total_cost) > 0.005)) {
    let representedPersonnel = 0;
    (project.personnel || []).forEach((person, index) => {
      const cost = num(person.total_cost, num(person.hourly_rate) * num(person.hours));
      if (Math.abs(cost) <= 0.005) return;
      representedPersonnel += cost;
      parts.push(manualCostPart({
        key: `channel:personnel:${index}`,
        name: person.name?.trim() || person.role || `Installer ${index + 1}`,
        type: "labor",
        subtype: person.role || "personnel",
        sourcePath: `personnel[${index}]`,
        cost,
        quantity: person.hours || 1,
        unit: person.hours ? "hour" : "job",
        builderData: person,
        calculation: person,
      }));
    });
    const residual = personnelTotal - representedPersonnel;
    if (Math.abs(residual) > 0.005) {
      parts.push(manualCostPart({
        key: "channel:personnel:reconciliation",
        name: "Crew Labor — Saved Cost Adjustment",
        type: "labor",
        subtype: "personnel_adjustment",
        sourcePath: "total_personnel_cost",
        cost: residual,
        calculation: { authoritative_total: personnelTotal, represented_total: representedPersonnel },
      }));
    }
  }

  const pushFabBreakdown = ({ purchase, index, fab, total, prefix, label, materialSourcePath }) => {
    if (!fab) return 0;
    const qty = Math.max(num(purchase.qty, 1), 0);
    const materialCost = num(fab.unit_material_cost) * qty;
    const cutCost = num(fab.unit_cut_cost) * qty;
    const paintCost = num(fab.unit_paint_cost) * qty;
    let represented = 0;

    if (Math.abs(materialCost) > 0.005 || fab.material_id) {
      const materialRate = num(fab.material_cost_per_sqin);
      const materialSqinPerUnit = materialRate > 0
        ? num(fab.unit_material_cost) / materialRate
        : num(purchase.size_value) * 144;
      const materialQty = materialSqinPerUnit > 0 ? materialSqinPerUnit * qty : qty || 1;
      parts.push(makePart({
        key: `${prefix}:material`,
        name: `${label} — ${fab.material_name || "Material"}`,
        type: "material",
        subtype: "dimensional_material",
        sourcePath: materialSourcePath,
        entity: "DimensionalLetterMaterial",
        inventoryId: fab.material_id || "",
        quantity: materialQty,
        unit: materialSqinPerUnit > 0 ? "sqin" : "unit",
        unitCost: materialSqinPerUnit > 0 ? materialRate : num(fab.unit_material_cost),
        extendedCost: materialCost,
        builderData: purchase,
        calculation: fab,
        pricingBasis: {
          pricing_mode: "sheet_yield",
          material_cost_per_sqin: fab.material_cost_per_sqin,
          sheet_yield_factor: fab.sheet_yield_factor,
          material_thickness_inches: fab.material_thickness_inches,
        },
      }));
      represented += materialCost;
    }

    if (Math.abs(cutCost) > 0.005) {
      parts.push(manualCostPart({
        key: `${prefix}:cutting`,
        name: `${label} — ${fab.cutting_method === "laser" ? "Laser" : "CNC"} Cutting`,
        type: "fabrication",
        subtype: fab.cutting_method === "laser" ? "laser_cutting" : "cnc_cutting",
        sourcePath: `${prefix.includes("backer") ? `letter_purchases[${index}].backer_fab_config` : `letter_purchases[${index}].fab_config`}.unit_cut_cost`,
        cost: cutCost,
        quantity: qty || 1,
        unit: "unit",
        builderData: purchase,
        calculation: fab,
      }));
      represented += cutCost;
    }

    if (Math.abs(paintCost) > 0.005) {
      parts.push(manualCostPart({
        key: `${prefix}:paint`,
        name: `${label} — Paint`,
        type: "finishing",
        subtype: "paint",
        sourcePath: `${prefix.includes("backer") ? `letter_purchases[${index}].backer_fab_config` : `letter_purchases[${index}].fab_config`}.unit_paint_cost`,
        cost: paintCost,
        quantity: qty || 1,
        unit: "unit",
        builderData: purchase,
        calculation: fab,
      }));
      represented += paintCost;
    }

    const residual = num(total) - represented;
    if (Math.abs(residual) > 0.005) {
      parts.push(manualCostPart({
        key: `${prefix}:adjustment`,
        name: `${label} — Price Override / Saved Adjustment`,
        type: "pricing",
        subtype: "fab_price_adjustment",
        sourcePath: prefix.includes("backer")
          ? `letter_purchases[${index}].backer_total`
          : `letter_purchases[${index}].letters_total`,
        cost: residual,
        builderData: purchase,
        calculation: { authoritative_total: total, represented_total: represented, unit_cost_override: purchase.unit_cost_override },
      }));
      represented += residual;
    }
    return represented;
  };

  (project.letter_purchases || []).forEach((purchase, index) => {
    const qty = Math.max(num(purchase.qty, 1), 0);
    const purchaseTotal = hasNumber(purchase.total_cost)
      ? num(purchase.total_cost)
      : num(purchase.line_total);
    const racewayTotal = num(purchase.raceway_total);
    const backerTotal = num(purchase.backer_total);
    const lettersTotal = hasNumber(purchase.letters_total)
      ? num(purchase.letters_total)
      : purchaseTotal - racewayTotal - backerTotal;
    const prefix = `channel:letters:${purchase.id || index}`;
    const label = purchase.description?.trim() || purchase.letter_type || `Letter Purchase ${index + 1}`;
    let representedPurchase = 0;

    if (purchase.letter_type === "dimensional_letters" && purchase.fab_config) {
      representedPurchase += pushFabBreakdown({
        purchase,
        index,
        fab: purchase.fab_config,
        total: lettersTotal,
        prefix: `${prefix}:fab`,
        label,
        materialSourcePath: `letter_purchases[${index}].fab_config.material_id`,
      });
    } else if (Math.abs(lettersTotal) > 0.005) {
      const size = Math.max(num(purchase.size_value), 0);
      const effectiveQty = size > 0 ? size * Math.max(qty, 1) : Math.max(qty, 1);
      const unit = purchase.letter_type === "raceway"
        ? "ft"
        : purchase.letter_type === "capsule_logo_pillbox"
          ? "sqft"
          : purchase.letter_type?.startsWith("channel_")
            ? "letter-inch"
            : "unit";
      parts.push(manualCostPart({
        key: `${prefix}:letters`,
        name: label,
        type: "material",
        subtype: purchase.letter_type || "letter_purchase",
        sourcePath: `letter_purchases[${index}].letters_total`,
        cost: lettersTotal,
        quantity: effectiveQty,
        unit,
        builderData: purchase,
        calculation: { unit_cost: purchase.unit_cost, size_value: purchase.size_value, qty: purchase.qty, letters_total: lettersTotal },
      }));
      representedPurchase += lettersTotal;
    }

    if (Math.abs(racewayTotal) > 0.005) {
      const racewayQty = Math.max(num(purchase.raceway_qty, 1), 1);
      const racewayLength = Math.max(num(purchase.raceway_length_feet), 0);
      const effectiveQty = racewayLength > 0 ? racewayLength * racewayQty : racewayQty;
      parts.push(manualCostPart({
        key: `${prefix}:raceway`,
        name: `${label} — Raceway`,
        type: "material",
        subtype: "raceway_purchase",
        sourcePath: `letter_purchases[${index}].raceway_total`,
        cost: racewayTotal,
        quantity: effectiveQty,
        unit: racewayLength > 0 ? "ft" : "unit",
        builderData: purchase,
        calculation: { raceway_length_feet: purchase.raceway_length_feet, raceway_qty: purchase.raceway_qty, raceway_unit_cost: purchase.raceway_unit_cost, raceway_total: racewayTotal },
      }));
      representedPurchase += racewayTotal;
    }

    if (Math.abs(backerTotal) > 0.005) {
      if (purchase.backer_fab_config) {
        representedPurchase += pushFabBreakdown({
          purchase,
          index,
          fab: purchase.backer_fab_config,
          total: backerTotal,
          prefix: `${prefix}:backer`,
          label: `${label} — Backer`,
          materialSourcePath: `letter_purchases[${index}].backer_fab_config.material_id`,
        });
      } else {
        parts.push(manualCostPart({
          key: `${prefix}:backer`,
          name: `${label} — Backer`,
          type: "fabrication",
          subtype: "backer",
          sourcePath: `letter_purchases[${index}].backer_total`,
          cost: backerTotal,
          quantity: qty || 1,
          unit: "unit",
          builderData: purchase,
          calculation: { backer_total: backerTotal },
        }));
        representedPurchase += backerTotal;
      }
    }

    const purchaseResidual = purchaseTotal - representedPurchase;
    if (Math.abs(purchaseResidual) > 0.005) {
      parts.push(manualCostPart({
        key: `${prefix}:reconciliation`,
        name: `${label} — Saved Cost Adjustment`,
        type: "pricing",
        subtype: "letter_purchase_adjustment",
        sourcePath: `letter_purchases[${index}].total_cost`,
        cost: purchaseResidual,
        builderData: purchase,
        calculation: { authoritative_total: purchaseTotal, represented_total: representedPurchase },
      }));
    }
  });

  const purchases = project.letter_purchases || [];
  const onlyDimensional = purchases.length > 0 && purchases.every((purchase) => purchase.letter_type === "dimensional_letters");
  const letterFees = [
    ["delivery", "Letter Delivery / Freight", onlyDimensional ? 0 : project.letters_delivery_fee],
    ["design", "Letter Design", project.letters_design_fee],
    ["install-supplies", "Letter Install Supplies", project.letters_install_supplies_fee],
    ["permitting", "Letter Permitting", project.letters_permitting_fee],
    ["other", "Other Letter Cost", project.letters_other_fee],
  ];
  letterFees.forEach(([key, name, cost]) => {
    if (Math.abs(num(cost)) <= 0.005) return;
    parts.push(manualCostPart({
      key: `channel:letter-fee:${key}`,
      name,
      type: key === "permitting" ? "permit" : "service",
      subtype: `letter_${key}`,
      sourcePath: `letters_${key.replaceAll("-", "_")}_fee`,
      cost,
    }));
  });

  const letterMarkup = num(project.total_letters_cost) - num(project.letters_subtotal);
  if (Math.abs(letterMarkup) > 0.005) {
    parts.push(manualCostPart({
      key: "channel:letters-markup",
      name: "Letter Purchase Markup",
      type: "pricing",
      subtype: "markup",
      sourcePath: "letters_markup_percent",
      cost: letterMarkup,
      calculation: { markup_percent: project.letters_markup_percent, markup_amount: letterMarkup },
    }));
  }

  if (Math.abs(num(project.total_supplies_cost)) > 0.005) {
    parts.push(manualCostPart({
      key: "channel:install-supplies",
      name: "Installation Consumables / Supplies",
      type: "consumable",
      subtype: "installation_supplies",
      sourcePath: "total_supplies_cost",
      cost: project.total_supplies_cost,
      calculation: { supplies_percent: project.supplies_percent_of_materials, extra_supplies_cost: project.extra_supplies_cost },
    }));
  }

  if (Math.abs(num(project.total_travel_cost)) > 0.005) {
    parts.push(manualCostPart({
      key: "channel:travel",
      name: "Travel / Fuel / Travel Labor",
      type: "service",
      subtype: "travel",
      sourcePath: "total_travel_cost",
      cost: project.total_travel_cost,
      quantity: project.travel_miles_round_trip || 1,
      unit: project.travel_miles_round_trip ? "round_trip_mile" : "job",
      calculation: { miles: project.travel_miles_round_trip, accepted_total: project.total_travel_cost },
    }));
  }

  if (Math.abs(num(project.markup_amount)) > 0.005) {
    parts.push(manualCostPart({
      key: "channel:project-markup",
      name: "Builder Markup",
      type: "pricing",
      subtype: "markup",
      sourcePath: "markup_amount",
      cost: project.markup_amount,
      calculation: { markup_percent: project.markup_percent, markup_amount: project.markup_amount },
    }));
  }

  // Final source-total reconciliation is intentionally narrow. It only appears
  // for older/special saved rows whose authoritative total contains a line that
  // the current detailed payload cannot identify.
  const authoritativeTotal = num(project.total_cost);
  const representedTotal = parts.reduce((sum, part) => sum + num(part.extended_cost), 0);
  const finalResidual = authoritativeTotal - representedTotal;
  if (Math.abs(finalResidual) > 0.005) {
    parts.push(manualCostPart({
      key: "channel:saved-total-reconciliation",
      name: "Channel / Dimensional — Saved Total Adjustment",
      type: "pricing",
      subtype: "saved_total_adjustment",
      sourcePath: "total_cost",
      cost: finalResidual,
      calculation: { authoritative_total: authoritativeTotal, represented_total: representedTotal },
    }));
  }

  return parts;
}
function extractVinylLegacy(project) {
  const parts = [];
  (project.items || []).forEach((item, index) => {
    if (item.vinyl_id) {
      parts.push(makePart({
        key: `vinyl:item:${index}:vinyl`,
        name: item.description ? `${item.description} — Vinyl` : "Vinyl",
        type: "material",
        subtype: "vinyl",
        sourcePath: `items[${index}].vinyl_id`,
        entity: "VinylInventory",
        inventoryId: item.vinyl_id,
        quantity: item.vinyl_sqft || item.quantity || 1,
        unit: "sqft",
        unitCost: item.vinyl_sqft ? num(item.vinyl_cost) / num(item.vinyl_sqft, 1) : 0,
        extendedCost: item.vinyl_cost,
        builderData: item,
        calculation: { sqft: item.vinyl_sqft, cost: item.vinyl_cost },
      }));
    }
    if (item.laminate_id) {
      parts.push(makePart({
        key: `vinyl:item:${index}:laminate`,
        name: item.description ? `${item.description} — Laminate` : "Laminate",
        type: "material",
        subtype: "laminate",
        sourcePath: `items[${index}].laminate_id`,
        entity: "VinylInventory",
        inventoryId: item.laminate_id,
        quantity: item.laminate_sqft || item.quantity || 1,
        unit: "sqft",
        unitCost: item.laminate_sqft ? num(item.laminate_cost) / num(item.laminate_sqft, 1) : 0,
        extendedCost: item.laminate_cost,
        builderData: item,
        calculation: { sqft: item.laminate_sqft, cost: item.laminate_cost },
      }));
    }
  });

  [
    ["printer_id", "Printer"],
    ["cutter_id", "Cutter"],
    ["laminator_id", "Laminator"],
  ].forEach(([field, label]) => {
    if (!project[field]) return;
    parts.push(makePart({
      key: `vinyl:machine:${field}`,
      name: label,
      type: "equipment",
      subtype: field.replace("_id", ""),
      sourcePath: field,
      entity: "VinylMachine",
      inventoryId: project[field],
      quantity: 1,
      builderData: { machine_id: project[field] },
    }));
  });

  (project.items || []).forEach((item, index) => {
    if (num(item.print_cost) > 0.005) {
      parts.push(manualCostPart({
        key: `vinyl:item:${index}:print`,
        name: item.description ? `${item.description} — Printing / Ink` : "Printing / Ink",
        type: "consumable",
        subtype: "printing",
        sourcePath: `items[${index}].print_cost`,
        cost: item.print_cost,
        quantity: item.print_sqft || 1,
        unit: item.print_sqft ? "sqft" : "job",
        builderData: item,
        calculation: { print_sqft: item.print_sqft, print_cost: item.print_cost, rate: project.print_cost_per_sqft },
      }));
    }
    if (num(item.labor_cost) > 0.005) {
      parts.push(manualCostPart({
        key: `vinyl:item:${index}:labor`,
        name: item.description ? `${item.description} — Production Labor` : "Vinyl Production Labor",
        type: "labor",
        subtype: "production_labor",
        sourcePath: `items[${index}].labor_cost`,
        cost: item.labor_cost,
        quantity: item.labor_hours || 1,
        unit: item.labor_hours ? "hour" : "job",
        builderData: item,
        calculation: { labor_hours: item.labor_hours, labor_cost: item.labor_cost, rate: project.labor_rate_per_hour },
      }));
    }
  });

  if (num(project.total_supplies_cost) > 0.005) {
    parts.push(manualCostPart({
      key: "vinyl:supplies",
      name: "Vinyl Production Supplies",
      type: "consumable",
      subtype: "production_supplies",
      sourcePath: "total_supplies_cost",
      cost: project.total_supplies_cost,
      calculation: { supplies_percent: project.supplies_percent_of_materials },
    }));
  }
  // Legacy simplified projects save total_supplies_cost inclusive of extra_supplies_cost,
  // so do not materialize extra supplies a second time here.
  if (num(project.markup_amount) > 0.005) {
    parts.push(manualCostPart({
      key: "vinyl:markup",
      name: "Builder Markup",
      type: "pricing",
      subtype: "markup",
      sourcePath: "markup_amount",
      cost: project.markup_amount,
      calculation: { markup_percent: project.markup_percent, markup_amount: project.markup_amount },
    }));
  }
  return parts;
}

function extractVinyl(project, catalogs = {}, options = {}) {
  const workflows = Array.isArray(project.workflows) ? project.workflows : [];
  if (!workflows.length) return extractVinylLegacy(project);

  const parts = [];
  let workflowMaterialTotal = 0;
  let workflowMachineTotal = 0;
  let workflowLaborTotal = 0;

  const addLinkedCost = ({
    key, name, type = "material", subtype = "", sourcePath = "", entity = "", inventoryId = "",
    quantity = 1, unit = "job", cost = 0, builderData = {}, calculation = {}, pricingBasis = {}, includeZero = false,
  }) => {
    const extended = num(cost);
    if (!includeZero && Math.abs(extended) <= 0.005) return;
    const qty = Math.max(num(quantity, 1), 0.000001);
    parts.push(makePart({
      key,
      name,
      type,
      subtype,
      sourcePath,
      entity,
      inventoryId,
      quantity: qty,
      unit,
      unitCost: extended / qty,
      extendedCost: extended,
      builderData,
      calculation,
      pricingBasis,
    }));
  };

  const laborInventoryFor = (row = {}) => {
    const savedId = row.inventory_id || row.labor_service_id || "";
    if (savedId) {
      const saved = findRow(catalogs, "LaborServiceInventory", savedId);
      if (saved) return saved;
    }
    return findNameCandidate(catalogs, "LaborServiceInventory", row.role || row.name || "");
  };

  workflows.forEach((workflow, workflowIndex) => {
    const prefix = `vinyl:workflow:${workflowIndex}`;
    const workflowName = workflow.name || `Workflow ${workflowIndex + 1}`;
    const printer = findRow(catalogs, "VinylMachine", workflow.printer_id);
    const cutter = findRow(catalogs, "VinylMachine", workflow.cutter_id);
    const laminator = findRow(catalogs, "VinylMachine", workflow.laminator_id);
    const vinyl = findRow(catalogs, "VinylInventory", workflow.vinyl_id);
    const laminate = findRow(catalogs, "VinylInventory", workflow.laminate_id);
    const transferTape = findRow(catalogs, "VinylInventory", workflow.transfer_tape_id);
    const operatorRate = printer?.operator_hourly_rate ?? cutter?.operator_hourly_rate ?? laminator?.operator_hourly_rate ?? 45;

    // The UI keeps the exact source calculation in workflow._calc while editing,
    // but SignEstimate Pro intentionally strips it from the VinylProject entity.
    // Prefer that frozen calculation when it is present in a Builder save snapshot;
    // otherwise re-run the authoritative Git calculator from the saved workflow.
    const calc = workflow._calc && Number.isFinite(Number(workflow._calc.totalCost))
      ? workflow._calc
      : calculateVinylProject({
          items: workflow.items || [],
          printer,
          cutter,
          laminator,
          vinyl,
          laminate,
          transferTape,
          operatorHourlyRate: operatorRate,
          applyPrint: !!workflow.apply_print,
          applyCut: !!workflow.apply_cut,
          applyLaminate: !!workflow.apply_laminate,
          applyTransferTape: !!workflow.apply_transfer_tape,
          overrideGutterH: workflow.gutter_h_override === "" || workflow.gutter_h_override == null ? undefined : num(workflow.gutter_h_override),
          overrideGutterV: workflow.gutter_v_override === "" || workflow.gutter_v_override == null ? undefined : num(workflow.gutter_v_override),
          printQuality: workflow.print_quality || printer?.default_print_quality || "high_quality",
          weedingDifficulty: workflow.weeding_difficulty || "moderate",
          weedingMinutesPerPartOverride: workflow.weeding_minutes_per_part_override,
          installMinutesPerPart: workflow.install_minutes_per_part,
          personnel: workflow.personnel || [],
          spoilageBufferPercent: num(workflow.spoilage_buffer_percent),
          setupFeeFloor: num(workflow.setup_fee_floor),
        });

    workflowMaterialTotal += num(calc.materialCost);
    workflowMachineTotal += num(calc.machineCost);
    workflowLaborTotal += num(calc.laborCost);

    if (workflow.vinyl_id) {
      addLinkedCost({
        key: `${prefix}:vinyl`,
        name: `${workflowName} — Vinyl`,
        type: "material",
        subtype: "vinyl",
        sourcePath: `workflows[${workflowIndex}].vinyl_id`,
        entity: "VinylInventory",
        inventoryId: workflow.vinyl_id,
        quantity: calc.totalRollSqFtPulled || 1,
        unit: "sqft",
        cost: calc.vinylCost,
        includeZero: true,
        builderData: workflow,
        calculation: { total_roll_sqft_pulled: calc.totalRollSqFtPulled, used_sqft: calc.usedSqFt, wasted_sqft: calc.wastedSqFt, vinyl_cost: calc.vinylCost },
      });
    }

    if (workflow.apply_laminate && workflow.laminate_id) {
      addLinkedCost({
        key: `${prefix}:laminate`,
        name: `${workflowName} — Laminate`,
        type: "material",
        subtype: "laminate",
        sourcePath: `workflows[${workflowIndex}].laminate_id`,
        entity: "VinylInventory",
        inventoryId: workflow.laminate_id,
        quantity: calc.laminateSqFt || 1,
        unit: "sqft",
        cost: calc.laminateCost,
        includeZero: true,
        builderData: workflow,
        calculation: { laminate_sqft: calc.laminateSqFt, laminate_cost: calc.laminateCost },
      });
    }

    if (workflow.apply_transfer_tape && workflow.transfer_tape_id) {
      addLinkedCost({
        key: `${prefix}:transfer-tape`,
        name: `${workflowName} — Transfer Tape`,
        type: "material",
        subtype: "transfer_tape",
        sourcePath: `workflows[${workflowIndex}].transfer_tape_id`,
        entity: "VinylInventory",
        inventoryId: workflow.transfer_tape_id,
        quantity: calc.transferTapeSqFt || 1,
        unit: "sqft",
        cost: calc.transferTapeCost,
        includeZero: true,
        builderData: workflow,
        calculation: { transfer_tape_sqft: calc.transferTapeSqFt, transfer_tape_cost: calc.transferTapeCost },
      });
    }

    if (workflow.apply_print && workflow.printer_id) {
      addLinkedCost({
        key: `${prefix}:ink`,
        name: `${workflowName} — Ink`,
        type: "consumable",
        subtype: "ink",
        sourcePath: `workflows[${workflowIndex}].printer_id`,
        entity: "VinylMachine",
        inventoryId: workflow.printer_id,
        quantity: calc.usedSqFt || 1,
        unit: "sqft",
        cost: calc.inkCost,
        builderData: workflow,
        calculation: { used_sqft: calc.usedSqFt, ink_rate_per_sqin: calc.inkRatePerSqIn, print_quality: calc.printQuality, ink_cost: calc.inkCost },
      });
      addLinkedCost({
        key: `${prefix}:printer-machine`,
        name: `${workflowName} — Printer Time`,
        type: "equipment",
        subtype: "printer",
        sourcePath: `workflows[${workflowIndex}].printer_id`,
        entity: "VinylMachine",
        inventoryId: workflow.printer_id,
        quantity: num(calc.printMinutes) / 60 || 1,
        unit: num(calc.printMinutes) > 0 ? "hour" : "job",
        cost: calc.printMachineCost,
        includeZero: true,
        builderData: workflow,
        calculation: { print_minutes: calc.printMinutes, print_machine_cost: calc.printMachineCost },
      });
    }

    if (workflow.apply_cut && workflow.cutter_id) {
      addLinkedCost({
        key: `${prefix}:blade`,
        name: `${workflowName} — Blade Wear`,
        type: "consumable",
        subtype: "blade_wear",
        sourcePath: `workflows[${workflowIndex}].cutter_id`,
        entity: "VinylMachine",
        inventoryId: workflow.cutter_id,
        quantity: num(calc.cutMinutes) || 1,
        unit: num(calc.cutMinutes) > 0 ? "minute" : "job",
        cost: calc.bladeCost,
        builderData: workflow,
        calculation: { cut_minutes: calc.cutMinutes, cut_distance_inches: calc.cutDistanceIn, blade_cost: calc.bladeCost },
      });
      addLinkedCost({
        key: `${prefix}:cutter-machine`,
        name: `${workflowName} — Cutter Time`,
        type: "equipment",
        subtype: "cutter",
        sourcePath: `workflows[${workflowIndex}].cutter_id`,
        entity: "VinylMachine",
        inventoryId: workflow.cutter_id,
        quantity: num(calc.cutMinutes) / 60 || 1,
        unit: num(calc.cutMinutes) > 0 ? "hour" : "job",
        cost: calc.cutMachineCost,
        includeZero: true,
        builderData: workflow,
        calculation: { cut_minutes: calc.cutMinutes, cut_machine_cost: calc.cutMachineCost },
      });
    }

    if (workflow.apply_laminate && workflow.laminator_id) {
      addLinkedCost({
        key: `${prefix}:laminator-machine`,
        name: `${workflowName} — Laminator Time`,
        type: "equipment",
        subtype: "laminator",
        sourcePath: `workflows[${workflowIndex}].laminator_id`,
        entity: "VinylMachine",
        inventoryId: workflow.laminator_id,
        quantity: num(calc.laminateMinutes) / 60 || 1,
        unit: num(calc.laminateMinutes) > 0 ? "hour" : "job",
        cost: calc.laminateMachineCost,
        includeZero: true,
        builderData: workflow,
        calculation: { laminate_minutes: calc.laminateMinutes, laminate_machine_cost: calc.laminateMachineCost },
      });
    }

    let workflowPersonnelTotal = 0;
    (workflow.personnel || []).forEach((person, personIndex) => {
      const personCost = num(person.total_cost, num(person.hourly_rate) * num(person.hours));
      if (Math.abs(personCost) <= 0.005) return;
      workflowPersonnelTotal += personCost;
      const inventoryRow = laborInventoryFor(person);
      addLinkedCost({
        key: `${prefix}:personnel:${personIndex}`,
        name: `${workflowName} — ${person.role || person.name || "Production Labor"}`,
        type: "labor",
        subtype: "workflow_personnel",
        sourcePath: `workflows[${workflowIndex}].personnel[${personIndex}].inventory_id`,
        entity: inventoryRow ? "LaborServiceInventory" : "",
        inventoryId: person.inventory_id || inventoryRow?.id || "",
        quantity: person.hours || 1,
        unit: person.hours ? "hour" : "job",
        cost: personCost,
        builderData: person,
        calculation: { role: person.role, hourly_rate: person.hourly_rate, hours: person.hours, total_cost: personCost },
      });
    });

    const laborResidual = num(calc.laborCost) - workflowPersonnelTotal;
    if (laborResidual > 0.005) {
      parts.push(manualCostPart({
        key: `${prefix}:labor`,
        name: `${workflowName} — Production Labor`,
        type: "labor",
        subtype: "production_labor",
        sourcePath: `workflows[${workflowIndex}]`,
        cost: laborResidual,
        quantity: calc.laborHours || 1,
        unit: calc.laborHours ? "hour" : "job",
        builderData: workflow,
        calculation: { labor_hours: calc.laborHours, labor_cost: calc.laborCost, residual_cost: laborResidual },
      }));
    }

    if (num(calc.setupFeeApplied) > 0.005) {
      // Git calculates this workflow floor but rollupVinylProject does not add it
      // to the project subtotal. Preserve the metric as a non-billable BOM line
      // instead of changing the authoritative source price.
      parts.push(manualCostPart({
        key: `${prefix}:setup-floor`,
        name: `${workflowName} — Setup Fee Floor (Not Billed by Source)`,
        type: "service",
        subtype: "setup_fee_floor_source_metric",
        sourcePath: `workflows[${workflowIndex}].setup_fee_floor`,
        cost: 0,
        builderData: workflow,
        calculation: { setup_fee_floor: workflow.setup_fee_floor, pre_floor_total: calc.preFloorTotal, setup_fee_applied: calc.setupFeeApplied, source_rollup_billed: false },
      }));
    }
  });

  const baseSupplies = workflowMaterialTotal * (num(project.supplies_percent_of_materials) / 100);
  if (baseSupplies > 0.005) {
    parts.push(manualCostPart({
      key: "vinyl:base-supplies",
      name: "Vinyl Production Supplies",
      type: "consumable",
      subtype: "production_supplies",
      sourcePath: "supplies_percent_of_materials",
      cost: baseSupplies,
      calculation: { supplies_percent: project.supplies_percent_of_materials, workflow_material_total: workflowMaterialTotal, base_supplies_cost: baseSupplies },
    }));
  }

  if (num(project.extra_supplies_cost) > 0.005) {
    parts.push(manualCostPart({
      key: "vinyl:extra-supplies",
      name: "Additional Vinyl Supplies",
      type: "consumable",
      subtype: "extra_supplies",
      sourcePath: "extra_supplies_cost",
      cost: project.extra_supplies_cost,
    }));
  }

  let equipmentTotal = 0;
  (project.selected_equipment || []).forEach((entry, index) => {
    const cost = num(entry.total_cost);
    equipmentTotal += cost;
    const inventoryId = entry.equipment_id || "";
    addLinkedCost({
      key: `vinyl:equipment:${index}`,
      name: entry.equipment_name || rowName("ChannelLetterInstallEquipment", findRow(catalogs, "ChannelLetterInstallEquipment", inventoryId)) || `Installation Equipment ${index + 1}`,
      type: "equipment",
      subtype: entry.equipment_type || "installation_equipment",
      sourcePath: `selected_equipment[${index}].equipment_id`,
      entity: "ChannelLetterInstallEquipment",
      inventoryId,
      quantity: entry.duration || 1,
      unit: entry.pricing_mode === "per_hour" ? "hour" : entry.pricing_mode === "per_week" ? "week" : entry.pricing_mode === "per_month" ? "month" : entry.pricing_mode === "per_day" ? "day" : "job",
      cost,
      includeZero: !!inventoryId,
      builderData: entry,
      calculation: entry,
    });
  });

  let projectPersonnelTotal = 0;
  (project.personnel || []).forEach((person, index) => {
    const cost = num(person.total_cost, num(person.hourly_rate) * num(person.hours));
    if (Math.abs(cost) <= 0.005) return;
    projectPersonnelTotal += cost;
    const inventoryRow = laborInventoryFor(person);
    addLinkedCost({
      key: `vinyl:installation-personnel:${index}`,
      name: person.name ? `${person.name} — ${person.role || "Installation Labor"}` : (person.role || "Installation Labor"),
      type: "labor",
      subtype: "installation_personnel",
      sourcePath: `personnel[${index}].inventory_id`,
      entity: inventoryRow ? "LaborServiceInventory" : "",
      inventoryId: person.inventory_id || inventoryRow?.id || "",
      quantity: person.hours || 1,
      unit: person.hours ? "hour" : "job",
      cost,
      builderData: person,
      calculation: { role: person.role, hourly_rate: person.hourly_rate, hours: person.hours, total_cost: cost },
    });
  });

  const travelTotal = num(project.total_travel_cost);
  if (travelTotal > 0.005) {
    parts.push(manualCostPart({
      key: "vinyl:travel",
      name: "Travel / Fuel",
      type: "service",
      subtype: "travel",
      sourcePath: "total_travel_cost",
      cost: travelTotal,
      quantity: project.travel_miles_round_trip || 1,
      unit: project.travel_miles_round_trip ? "mile" : "job",
      calculation: { miles: project.travel_miles_round_trip, total_travel_cost: travelTotal },
    }));
  }

  const suppliesTotal = baseSupplies + num(project.extra_supplies_cost);
  // Match SignEstimate Pro exactly: setupFeeApplied is a workflow metric, but
  // rollupVinylProject does not add it to the project subtotal.
  const subtotal = workflowMaterialTotal + workflowMachineTotal + workflowLaborTotal + equipmentTotal + projectPersonnelTotal + travelTotal + suppliesTotal;
  const markup = subtotal * (num(project.markup_percent) / 100);
  if (markup > 0.005) {
    parts.push(manualCostPart({
      key: "vinyl:markup",
      name: "Builder Markup",
      type: "pricing",
      subtype: "markup",
      sourcePath: "markup_percent",
      cost: markup,
      calculation: { markup_percent: project.markup_percent, subtotal, markup_amount: markup },
    }));
  }

  // Existing migrated Vinyl products are legacy-frozen. Their saved project
  // total remains authoritative even when old workflow payloads are too sparse
  // to recreate every historical cost line. Add only the unexplained balance;
  // normal/current Builder checks still recalculate from live inventory so price
  // changes remain detectable.
  if (options.legacyMode && project.total_cost !== null && project.total_cost !== undefined) {
    const authoritativeTotal = num(project.total_cost);
    const representedTotal = parts.reduce((sum, part) => sum + num(part.extended_cost), 0);
    const residual = authoritativeTotal - representedTotal;
    if (Math.abs(residual) > 0.005) {
      parts.push(manualCostPart({
        key: "vinyl:saved-total-reconciliation",
        name: "Vinyl — Saved Total Adjustment",
        type: "pricing",
        subtype: "saved_total_adjustment",
        sourcePath: "total_cost",
        cost: residual,
        calculation: { authoritative_total: authoritativeTotal, represented_total: representedTotal },
      }));
    }
  }

  return parts;
}

function extractMetal(project) {
  const parts = [];
  const represented = {
    material: 0,
    supplies: 0,
    fabrication: 0,
    welding: 0,
    finishing: 0,
  };

  (project.items || []).forEach((item, index) => {
    const itemQty = Math.max(num(item.quantity, 1), 0.000001);
    const lengthPerUnit = num(item.material_length_ft);
    const materialExtended = num(item.material_cost) * itemQty;
    represented.material += materialExtended;

    if (Math.abs(materialExtended) > 0.005 || item.inventory_item_id) {
      const linkedUsageQty = lengthPerUnit > 0 ? lengthPerUnit * itemQty : itemQty;
      const frozenMaterialUnitCost = lengthPerUnit > 0
        ? num(item.material_cost) / Math.max(lengthPerUnit, 0.000001)
        : num(item.material_cost);
      parts.push(makePart({
        key: `metal:item:${index}:material`,
        name: item.description ? `${item.description} — Metal Material` : (item.item_type || "Metal Material"),
        type: "material",
        subtype: item.item_type || "metal",
        sourcePath: `items[${index}].inventory_item_id`,
        entity: item.inventory_item_id ? "Inventory" : "",
        inventoryId: item.inventory_item_id || "",
        quantity: linkedUsageQty,
        unit: lengthPerUnit > 0 ? "source_unit" : "item",
        unitCost: frozenMaterialUnitCost,
        extendedCost: materialExtended,
        builderData: item,
        calculation: {
          item_quantity: itemQty,
          material_length_per_unit: lengthPerUnit,
          material_cost_per_item: item.material_cost,
          total_material_cost: materialExtended,
        },
        pricingBasis: {
          pricing_mode: "legacy_cost_per_unit",
          material_length_ft_per_item: lengthPerUnit,
          item_quantity: itemQty,
        },
      }));
    }

    const suppliesExtended = num(item.supplies_cost) * itemQty;
    represented.supplies += suppliesExtended;
    if (Math.abs(suppliesExtended) > 0.005) {
      parts.push(manualCostPart({
        key: `metal:item:${index}:supplies`,
        name: item.description ? `${item.description} — Fabrication Consumables` : "Fabrication Consumables",
        type: "consumable",
        subtype: "supplies",
        sourcePath: `items[${index}].supplies_cost`,
        cost: suppliesExtended,
        quantity: itemQty,
        unit: "item",
        builderData: item,
        calculation: { item_quantity: itemQty, supplies_cost_per_item: item.supplies_cost, total_supplies_cost: suppliesExtended },
      }));
    }

    [
      ["fabrication", "Fabrication Labor", item.fabrication_cost, item.fabrication_hours],
      ["welding", "Welding Labor", item.welding_cost, item.welding_hours],
      ["finishing", "Finishing Labor", item.finishing_cost, item.finishing_hours],
    ].forEach(([key, label, perItemCost, hoursPerItem]) => {
      const extended = num(perItemCost) * itemQty;
      represented[key] += extended;
      if (Math.abs(extended) <= 0.005) return;
      const totalHours = num(hoursPerItem) * itemQty;
      parts.push(manualCostPart({
        key: `metal:item:${index}:${key}`,
        name: item.description ? `${item.description} — ${label}` : label,
        type: "labor",
        subtype: key,
        sourcePath: `items[${index}].${key}_cost`,
        cost: extended,
        quantity: totalHours || itemQty,
        unit: totalHours ? "hour" : "item",
        builderData: item,
        calculation: {
          item_quantity: itemQty,
          hours_per_item: hoursPerItem,
          cost_per_item: perItemCost,
          total_cost: extended,
        },
      }));
    });
  });

  // Saved Git-era category totals are authoritative. Materialize only a balance
  // when a historical/imported record cannot be fully reconstructed from its
  // item-level snapshots. CCS-only supplies percentages/markup are intentionally
  // excluded from source-faithful Metal pricing.
  const authoritative = {
    material: project.total_material_cost == null ? represented.material : num(project.total_material_cost),
    supplies: project.total_supplies_cost == null ? represented.supplies : num(project.total_supplies_cost),
    fabrication: project.total_fabrication_cost == null ? represented.fabrication : num(project.total_fabrication_cost),
    welding: project.total_welding_cost == null ? represented.welding : num(project.total_welding_cost),
    finishing: project.total_finishing_cost == null ? represented.finishing : num(project.total_finishing_cost),
  };
  const labels = {
    material: ["Metal Material Adjustment", "material"],
    supplies: ["Metal Supplies Adjustment", "consumable"],
    fabrication: ["Fabrication Labor Adjustment", "labor"],
    welding: ["Welding Labor Adjustment", "labor"],
    finishing: ["Finishing Labor Adjustment", "labor"],
  };
  Object.keys(authoritative).forEach((key) => {
    const adjustment = authoritative[key] - represented[key];
    if (Math.abs(adjustment) <= 0.005) return;
    parts.push(manualCostPart({
      key: `metal:${key}-adjustment`,
      name: labels[key][0],
      type: labels[key][1],
      subtype: `${key}_adjustment`,
      sourcePath: `total_${key}_cost`,
      cost: adjustment,
      calculation: {
        authoritative_total: authoritative[key],
        represented_total: represented[key],
        adjustment,
      },
    }));
  });

  return parts;
}

function brickMaterialForCalc(row) {
  if (!row) return null;
  if (row.material_type === "wall_material") {
    return {
      ...row,
      length: row.wall_unit_length_inches,
      width: row.wall_unit_width_inches,
      height: row.wall_unit_height_inches,
    };
  }
  if (row.material_type === "brick_stone") {
    return {
      ...row,
      length: row.brick_length_inches,
      width: row.brick_width_inches,
      height: row.brick_height_inches,
    };
  }
  return row;
}

function extractBrick(project, catalogs = {}, options = {}) {
  const parts = [];
  const selectedId = project.selected_material_id || "";
  const foundationRow = selectedId ? catalogs.FoundationInventory?.byId.get(selectedId) : null;
  const legacyRow = selectedId ? catalogs.BrickStoneInventory?.byId.get(selectedId) : null;
  const liveRow = foundationRow || legacyRow || null;
  const entity = foundationRow ? "FoundationInventory" : legacyRow ? "BrickStoneInventory" : "FoundationInventory";

  // Current Builder checks recalculate from the current Master Inventory row so
  // material price/geometry changes are visible without mutating the frozen cost.
  // Legacy-frozen rows remain based on their saved project breakdown.
  const liveCalc = !options.legacyMode && liveRow
    ? calcBrickStoneProject(project, brickMaterialForCalc(liveRow))
    : null;
  const calculatedBricks = liveCalc ? liveCalc.calculated_bricks : num(project.calculated_bricks);
  const materialCost = liveCalc ? liveCalc.material_cost : num(project.material_cost);
  const mortarBags = liveCalc ? liveCalc.mortar_bags_needed : num(project.mortar_bags_needed);
  const mortarCost = liveCalc ? liveCalc.mortar_cost : num(project.mortar_cost);
  const laborHours = liveCalc ? liveCalc.labor_hours : num(project.labor_hours);
  const laborCost = liveCalc ? liveCalc.labor_cost : num(project.labor_cost);
  const markupAmount = liveCalc ? liveCalc.markup_amount : num(project.markup_amount);

  if (selectedId) {
    const qty = Math.max(calculatedBricks, 1);
    parts.push(makePart({
      key: "brick:primary-material",
      name: project.material_name || liveRow?.material_name || "Brick / Stone Material",
      type: "material",
      subtype: liveRow?.wall_material_subtype || liveRow?.material_type || "brick_stone",
      sourcePath: "selected_material_id",
      entity,
      inventoryId: selectedId,
      quantity: qty,
      unit: "unit",
      unitCost: qty ? materialCost / qty : 0,
      extendedCost: materialCost,
      builderData: {
        material_dimensions: project.material_dimensions,
        bricks_along_length: project.bricks_along_length,
        bricks_along_width: project.bricks_along_width,
        courses_high: project.courses_high,
        layers: project.layers,
      },
      calculation: {
        calculated_bricks: calculatedBricks,
        material_cost: materialCost,
        material_inventory_entity: entity,
      },
      pricingBasis: { pricing_mode: "per_unit" },
    }));
  }
  if (Math.abs(mortarCost) > 0.005) {
    parts.push(manualCostPart({
      key: "brick:mortar",
      name: "Mortar",
      type: "consumable",
      subtype: "mortar",
      sourcePath: "mortar_cost",
      cost: mortarCost,
      quantity: mortarBags || 1,
      unit: mortarBags ? "bag" : "job",
      calculation: { mortar_bags_needed: mortarBags, mortar_bag_cost: project.mortar_bag_cost },
    }));
  }
  if (Math.abs(laborCost) > 0.005) {
    parts.push(manualCostPart({
      key: "brick:labor",
      name: "Masonry Labor",
      type: "labor",
      subtype: "masonry_labor",
      sourcePath: "labor_cost",
      cost: laborCost,
      quantity: laborHours || 1,
      unit: laborHours ? "hour" : "job",
      calculation: { labor_hours: laborHours, labor_rate_per_hour: project.labor_rate_per_hour },
    }));
  }
  if (Math.abs(markupAmount) > 0.005) {
    parts.push(manualCostPart({
      key: "brick:markup",
      name: "Builder Markup",
      type: "pricing",
      subtype: "markup",
      sourcePath: "markup_amount",
      cost: markupAmount,
      calculation: { markup_percent: project.markup_percent, markup_amount: markupAmount },
    }));
  }

  if (options.legacyMode && project.total_cost !== null && project.total_cost !== undefined) {
    const represented = parts.reduce((sum, part) => sum + num(part.extended_cost), 0);
    const residual = num(project.total_cost) - represented;
    if (Math.abs(residual) > 0.005) {
      parts.push(manualCostPart({
        key: "brick:saved-total-reconciliation",
        name: "Brick & Stone — Saved Total Adjustment",
        type: "pricing",
        subtype: "saved_total_adjustment",
        sourcePath: "total_cost",
        cost: residual,
        calculation: { authoritative_total: project.total_cost, represented_total: represented, adjustment: residual },
      }));
    }
  }
  return parts;
}

function maintenanceEquipmentSource(entry, catalogs) {
  const id = entry?.equipment_id || entry?.inventory_item_id || "";
  if (!id) return { entity: "", row: null };
  const requested = entry?.inventory_entity || "";
  if (requested && catalogs[requested]?.byId?.has(id)) {
    return { entity: requested, row: catalogs[requested].byId.get(id) };
  }
  // New/current Maintenance equipment comes from the shared Master Inventory.
  const shared = catalogs.ChannelLetterInstallEquipment?.byId?.get(id);
  if (shared) return { entity: "ChannelLetterInstallEquipment", row: shared };
  // Historical compatibility for any old project that referenced the legacy table.
  const legacy = catalogs.MaintenanceEquipment?.byId?.get(id);
  if (legacy) return { entity: "MaintenanceEquipment", row: legacy };
  return { entity: requested, row: null };
}

function recalcMaintenanceEquipmentRow(entry, catalogs) {
  const { entity, row } = maintenanceEquipmentSource(entry, catalogs);
  if (!row) return entry;
  const pricingMode = entry.pricing_mode || row.pricing_mode || "per_day";
  const duration = Math.max(num(entry.duration, 1), 0);
  const unitCost = independentPartUnitCost({
    inventory_entity: entity,
    pricing_basis_snapshot: { pricing_mode: pricingMode },
  }, row);
  const owned = row.ownership === "owned" || ["owned_flat", "per_project_flat"].includes(pricingMode);
  const delivery = !owned && entry.include_delivery ? num(row.delivery_pickup_cost) : 0;
  const idleRate = num(row.idle_running_cost_per_hour);
  const idleHours = num(entry.idle_hours);
  const idleCost = idleRate * idleHours;
  return {
    ...entry,
    inventory_entity: entity,
    equipment_name: row.equipment_name || entry.equipment_name,
    equipment_type: row.equipment_type || entry.equipment_type,
    pricing_mode: pricingMode,
    ownership: row.ownership || entry.ownership,
    unit_cost: unitCost,
    delivery_pickup_cost: num(row.delivery_pickup_cost),
    idle_running_cost_per_hour: idleRate,
    idle_cost: idleCost,
    total_cost: unitCost * duration + delivery + idleCost,
  };
}

function liveMaintenanceProject(project, catalogs) {
  const settings = {};
  (catalogs.Settings?.rows || []).forEach((row) => {
    if (row.setting_name) settings[row.setting_name] = row.setting_value;
  });
  const rates = catalogs.MaintenanceActionRate?.rows || [];
  const inventory = (catalogs.MaintenanceInventory?.rows || []).map((rule) => {
    if (!rule.inventory_entity || !rule.inventory_item_id) return rule;
    const masterRow = catalogs[rule.inventory_entity]?.byId?.get(rule.inventory_item_id) || null;
    const pricingMode = masterRow?.pricing_mode || masterRow?.pole_pricing_mode || masterRow?.unit_type || (rule.inventory_entity === "DimensionalLetterMaterial" ? "per_sheet" : "per_unit");
    return {
      ...rule,
      _master_missing: !masterRow,
      _master_unit_cost: masterRow ? independentPartUnitCost({ inventory_entity: rule.inventory_entity, pricing_basis_snapshot: { pricing_mode: pricingMode } }, masterRow) : undefined,
      _master_pricing_mode: pricingMode,
      _display_name: masterRow ? rowName(rule.inventory_entity, masterRow) : (rule.inventory_item_name || rule.item_name),
    };
  });
  const items = (project.items || []).map((item) => calcServiceItem(item, settings, rates, inventory));
  const selectedEquipment = (project.selected_equipment || []).map((entry) => recalcMaintenanceEquipmentRow(entry, catalogs));
  const current = { ...project, items, selected_equipment: selectedEquipment };
  return { ...current, ...calcProjectTotals(current) };
}

function extractMaintenance(project, catalogs = {}, options = {}) {
  if (!options.legacyMode && (catalogs.Settings?.rows || []).length) {
    project = liveMaintenanceProject(project, catalogs);
  }
  const parts = [];
  const represented = { labor: 0, materials: 0, equipment: 0, personnel: 0, supplies: 0, travel: 0, markup: 0 };

  (project.items || []).forEach((item, itemIndex) => {
    let itemMaterialParts = 0;
    (item.materials || []).forEach((mat, matIndex) => {
      const ruleId = mat.maintenance_rule_id || (!mat.inventory_entity ? (mat.inventory_item_id || mat.inventory_id || "") : "");
      const rule = ruleId ? catalogs.MaintenanceInventory?.byId.get(ruleId) : null;
      const linkedEntity = mat.inventory_entity || rule?.inventory_entity || "";
      const linkedId = linkedEntity ? (mat.inventory_item_id || rule?.inventory_item_id || "") : "";
      const inventoryEntity = linkedEntity || (ruleId ? "MaintenanceInventory" : "");
      const inventoryId = linkedEntity ? linkedId : ruleId;
      const row = linkedEntity ? catalogs[linkedEntity]?.byId?.get(linkedId) : rule;
      const quantity = num(mat.quantity, 0);
      const unitCost = num(mat.unit_cost);
      const extendedCost = mat.total_cost == null ? quantity * unitCost : num(mat.total_cost);
      itemMaterialParts += extendedCost;
      represented.materials += extendedCost;
      if (Math.abs(extendedCost) <= 0.005 && !inventoryId) return;
      parts.push(makePart({
        key: `maintenance:item:${itemIndex}:material:${matIndex}`,
        name: mat.item_name || (linkedEntity && row ? rowName(linkedEntity, row) : rule?.item_name) || "Maintenance Material",
        type: "material",
        subtype: mat.pricing_mode || row?.pricing_mode || rule?.pricing_mode || "maintenance_material",
        sourcePath: linkedEntity
          ? `items[${itemIndex}].materials[${matIndex}].inventory_item_id`
          : ruleId
            ? `items[${itemIndex}].materials[${matIndex}].maintenance_rule_id`
            : `items[${itemIndex}].materials[${matIndex}]`,
        entity: inventoryId ? inventoryEntity : "",
        inventoryId,
        quantity: quantity || 1,
        unit: mat.unit || row?.unit || rule?.unit || mat.pricing_mode || row?.pricing_mode || rule?.pricing_mode || "unit",
        unitCost,
        extendedCost,
        builderData: { sign: item.description, sign_type: item.sign_type, size: item.size, actions: item.actions || [], maintenance_rule_id: ruleId, maintenance_rule: rule || null, material: mat },
        calculation: { ...mat, maintenance_rule_id: ruleId, saved_total_cost: extendedCost },
        pricingBasis: { pricing_mode: mat.pricing_mode || row?.pricing_mode || row?.pole_pricing_mode || row?.unit_type || rule?.pricing_mode || "", size: item.size, sign_type: item.sign_type, actions: item.actions || [], usage_basis: mat.usage_basis || rule?.usage_basis || "", usage_multiplier: mat.usage_multiplier ?? rule?.usage_multiplier },
      }));
    });

    const authoritativeItemMaterials = item.materials_cost == null ? itemMaterialParts : num(item.materials_cost);
    const itemMaterialAdjustment = authoritativeItemMaterials - itemMaterialParts;
    if (Math.abs(itemMaterialAdjustment) > 0.005) {
      const isRepaint = !!item.repaint_calc;
      parts.push(manualCostPart({
        key: `maintenance:item:${itemIndex}:material-adjustment`,
        name: isRepaint ? `${item.description || "Monument"} — Repaint Paint Material` : `${item.description || `Service Item ${itemIndex + 1}`} — Material Adjustment`,
        type: "material",
        subtype: isRepaint ? "monument_repaint_paint" : "material_adjustment",
        sourcePath: `items[${itemIndex}].materials_cost`,
        cost: itemMaterialAdjustment,
        builderData: item,
        calculation: { authoritative_item_materials: authoritativeItemMaterials, inventory_materials: itemMaterialParts, repaint_calc: item.repaint_calc, adjustment: itemMaterialAdjustment },
      }));
      represented.materials += itemMaterialAdjustment;
    }

    const laborCost = num(item.labor_cost);
    represented.labor += laborCost;
    if (Math.abs(laborCost) > 0.005) {
      parts.push(manualCostPart({
        key: `maintenance:item:${itemIndex}:labor`,
        name: `${item.description || `Service Item ${itemIndex + 1}`} — Maintenance Labor`,
        type: "labor",
        subtype: "maintenance_labor",
        sourcePath: `items[${itemIndex}].labor_cost`,
        cost: laborCost,
        quantity: item.labor_hours || 1,
        unit: item.labor_hours ? "hour" : "job",
        builderData: { sign_type: item.sign_type, size: item.size, qty: item.qty, actions: item.actions || [], repaint_calc: item.repaint_calc },
        calculation: { labor_hours: item.labor_hours, labor_cost: laborCost, actions: item.actions || [] },
      }));
    }
  });

  (project.selected_equipment || []).forEach((eq, index) => {
    const id = eq.equipment_id || eq.inventory_item_id || "";
    const equipmentSource = maintenanceEquipmentSource(eq, catalogs);
    const equipmentEntity = equipmentSource.entity || eq.inventory_entity || (id ? "MaintenanceEquipment" : "");
    const duration = num(eq.duration, 1);
    const baseCost = num(eq.unit_cost) * duration;
    const deliveryCost = eq.include_delivery ? num(eq.delivery_pickup_cost) : 0;
    const idleCost = eq.idle_cost == null ? num(eq.idle_running_cost_per_hour) * num(eq.idle_hours) : num(eq.idle_cost);
    const reconstructed = baseCost + deliveryCost + idleCost;
    const authoritativeEquipment = eq.total_cost == null ? reconstructed : num(eq.total_cost);

    if (Math.abs(baseCost) > 0.005 || id) {
      parts.push(makePart({
        key: `maintenance:equipment:${index}:base`,
        name: eq.equipment_name || "Maintenance Equipment",
        type: "equipment",
        subtype: eq.equipment_type || "maintenance_equipment",
        sourcePath: `selected_equipment[${index}].equipment_id`,
        entity: id ? equipmentEntity : "",
        inventoryId: id,
        quantity: duration || 1,
        unit: eq.pricing_mode || "unit",
        unitCost: eq.unit_cost,
        extendedCost: baseCost,
        builderData: eq,
        calculation: { duration, unit_cost: eq.unit_cost, base_cost: baseCost },
        pricingBasis: { pricing_mode: eq.pricing_mode || "" },
      }));
    }
    if (Math.abs(deliveryCost) > 0.005) {
      parts.push(makePart({
        key: `maintenance:equipment:${index}:delivery`,
        name: `${eq.equipment_name || "Equipment"} — Delivery / Pickup`,
        type: "service",
        subtype: "equipment_delivery",
        sourcePath: `selected_equipment[${index}].delivery_pickup_cost`,
        entity: id ? equipmentEntity : "",
        inventoryId: id,
        quantity: 1,
        unit: "delivery",
        unitCost: deliveryCost,
        extendedCost: deliveryCost,
        builderData: eq,
        calculation: { include_delivery: eq.include_delivery, delivery_pickup_cost: deliveryCost },
        pricingBasis: { pricing_mode: "delivery_pickup" },
      }));
    }
    if (Math.abs(idleCost) > 0.005) {
      const idleHours = num(eq.idle_hours, 1);
      parts.push(makePart({
        key: `maintenance:equipment:${index}:idle`,
        name: `${eq.equipment_name || "Equipment"} — Idle Running`,
        type: "equipment",
        subtype: "idle_running",
        sourcePath: `selected_equipment[${index}].idle_running_cost_per_hour`,
        entity: id ? equipmentEntity : "",
        inventoryId: id,
        quantity: idleHours || 1,
        unit: "hour",
        unitCost: idleHours ? idleCost / idleHours : idleCost,
        extendedCost: idleCost,
        builderData: eq,
        calculation: { idle_hours: eq.idle_hours, idle_running_cost_per_hour: eq.idle_running_cost_per_hour, idle_cost: idleCost },
        pricingBasis: { pricing_mode: "idle_running" },
      }));
    }
    const equipmentAdjustment = authoritativeEquipment - reconstructed;
    if (Math.abs(equipmentAdjustment) > 0.005) {
      parts.push(manualCostPart({
        key: `maintenance:equipment:${index}:adjustment`,
        name: `${eq.equipment_name || "Equipment"} — Saved Cost Adjustment`,
        type: "equipment",
        subtype: "equipment_adjustment",
        sourcePath: `selected_equipment[${index}].total_cost`,
        cost: equipmentAdjustment,
        builderData: eq,
        calculation: { authoritative_total: authoritativeEquipment, reconstructed_total: reconstructed, adjustment: equipmentAdjustment },
      }));
    }
    represented.equipment += authoritativeEquipment;
  });

  (project.personnel || []).forEach((person, index) => {
    const cost = person.total_cost == null ? num(person.hourly_rate) * num(person.hours) : num(person.total_cost);
    represented.personnel += cost;
    if (Math.abs(cost) <= 0.005) return;
    parts.push(manualCostPart({
      key: `maintenance:personnel:${index}`,
      name: `${person.name || person.role || `Crew Member ${index + 1}`} — Personnel`,
      type: "labor",
      subtype: (person.role || "personnel").toLowerCase().replace(/\s+/g, "_"),
      sourcePath: `personnel[${index}].total_cost`,
      cost,
      quantity: person.hours || 1,
      unit: person.hours ? "hour" : "job",
      builderData: person,
      calculation: { hourly_rate: person.hourly_rate, hours: person.hours, total_cost: cost },
    }));
  });

  const totalSupplies = num(project.total_supplies_cost);
  represented.supplies = totalSupplies;
  if (Math.abs(totalSupplies) > 0.005) {
    parts.push(manualCostPart({
      key: "maintenance:supplies",
      name: "Maintenance Consumables / Supplies",
      type: "consumable",
      subtype: "maintenance_supplies",
      sourcePath: "total_supplies_cost",
      cost: totalSupplies,
      calculation: { supplies_percent_of_materials: project.supplies_percent_of_materials, extra_supplies_cost: project.extra_supplies_cost, total_materials_cost: project.total_materials_cost, total_supplies_cost: totalSupplies },
    }));
  }

  const totalTravel = num(project.total_travel_cost);
  represented.travel = totalTravel;
  if (Math.abs(totalTravel) > 0.005) {
    parts.push(manualCostPart({
      key: "maintenance:travel",
      name: "Travel / Mileage",
      type: "service",
      subtype: "travel",
      sourcePath: "total_travel_cost",
      cost: totalTravel,
      quantity: project.travel_miles_round_trip || 1,
      unit: project.travel_miles_round_trip ? "mile" : "job",
      calculation: { miles: project.travel_miles_round_trip, total_travel_cost: totalTravel, site_address: project.site_address },
    }));
  }

  const totalMarkup = num(project.markup_amount);
  represented.markup = totalMarkup;
  if (Math.abs(totalMarkup) > 0.005) {
    parts.push(manualCostPart({
      key: "maintenance:markup",
      name: "Builder Markup",
      type: "pricing",
      subtype: "markup",
      sourcePath: "markup_amount",
      cost: totalMarkup,
      calculation: { markup_percent: project.markup_percent, subtotal: project.subtotal, markup_amount: totalMarkup },
    }));
  }

  const authoritativeCategories = {
    labor: project.labor_cost == null ? represented.labor : num(project.labor_cost),
    materials: project.total_materials_cost == null ? represented.materials : num(project.total_materials_cost),
    equipment: project.total_equipment_cost == null ? represented.equipment : num(project.total_equipment_cost),
    personnel: project.total_personnel_cost == null ? represented.personnel : num(project.total_personnel_cost),
  };
  const categoryMeta = { labor: ["Labor", "labor"], materials: ["Materials", "material"], equipment: ["Equipment", "equipment"], personnel: ["Personnel", "labor"] };
  Object.keys(authoritativeCategories).forEach((key) => {
    const adjustment = authoritativeCategories[key] - represented[key];
    if (Math.abs(adjustment) <= 0.005) return;
    parts.push(manualCostPart({
      key: `maintenance:${key}-adjustment`,
      name: `Maintenance ${categoryMeta[key][0]} Adjustment`,
      type: categoryMeta[key][1],
      subtype: `${key}_adjustment`,
      sourcePath: key === "labor" ? "labor_cost" : `total_${key}_cost`,
      cost: adjustment,
      calculation: { authoritative_total: authoritativeCategories[key], represented_total: represented[key], adjustment },
    }));
    represented[key] = authoritativeCategories[key];
  });

  const reconstructedTotal = Object.values(represented).reduce((sum, value) => sum + num(value), 0);
  if (project.total_cost != null) {
    const finalAdjustment = num(project.total_cost) - reconstructedTotal;
    if (Math.abs(finalAdjustment) > 0.005) {
      parts.push(manualCostPart({
        key: "maintenance:project-total-adjustment",
        name: "Maintenance Saved Total Adjustment",
        type: "pricing",
        subtype: "project_total_adjustment",
        sourcePath: "total_cost",
        cost: finalAdjustment,
        calculation: { authoritative_total: project.total_cost, reconstructed_total: reconstructedTotal, adjustment: finalAdjustment },
      }));
    }
  }
  return parts;
}

function manualCostPart({ key, name, type = "labor", subtype = "", sourcePath = "", cost = 0, quantity = 1, unit = "job", builderData = {}, calculation = {} }) {
  const extended = num(cost);
  const qty = Math.max(num(quantity, 1), 0.000001);
  return makePart({
    key,
    name,
    type,
    subtype,
    sourcePath,
    quantity: qty,
    unit,
    unitCost: extended / qty,
    extendedCost: extended,
    builderData,
    calculation,
  });
}

function foundationEquipmentBreakdown(entry, catalogs) {
  const equipmentRow = catalogs.FoundationInventory?.byId.get(entry.equipment_id);
  if (!equipmentRow) return { baseRental: num(entry.equipment_cost), delivery: 0, attachmentCosts: [], subAttachmentCosts: [], total: num(entry.equipment_cost) };
  const rentalPeriod = entry.rental_period || "day";
  const duration = entry.custom_qty !== undefined && entry.custom_qty !== null
    ? num(entry.custom_qty, 1)
    : num(entry.rental_duration, 1);
  const rateFor = (row, override = undefined) => {
    if (override !== undefined && override !== null) return num(override) * duration;
    if (rentalPeriod === "day") return num(row?.cost_per_day) * duration;
    if (rentalPeriod === "week") return num(row?.cost_per_week) * duration;
    if (rentalPeriod === "month") return num(row?.cost_per_month) * duration;
    return 0;
  };

  const attachmentQty = new Map();
  if (entry.attachments?.length) {
    entry.attachments.forEach((attachment) => {
      const id = attachment.id || attachment.inventory_id || "";
      if (id) attachmentQty.set(id, num(attachment.qty, 1));
    });
  } else if (entry.attachment_counts) {
    Object.entries(entry.attachment_counts).forEach(([id, qty]) => attachmentQty.set(id, num(qty, 0)));
  } else if (entry.attachment_ids?.length) {
    entry.attachment_ids.forEach((id) => attachmentQty.set(id, 1));
  }

  const attachmentCosts = [...attachmentQty.entries()].map(([id, quantity]) => {
    const row = catalogs.FoundationInventory?.byId.get(id);
    return { id, row, quantity, cost: rateFor(row) * quantity, attachment: { id, qty: quantity } };
  }).filter((entry) => entry.quantity > 0);

  const subAttachmentCosts = Object.entries(entry.sub_attachment_counts || {}).map(([id, qty]) => {
    const quantity = num(qty, 0);
    const row = catalogs.FoundationInventory?.byId.get(id);
    return { id, row, quantity, cost: rateFor(row) * quantity, attachment: { id, qty: quantity } };
  }).filter((entry) => entry.quantity > 0);

  const baseRental = rateFor(equipmentRow, entry.custom_rate);
  const delivery = entry.include_delivery
    ? (entry.custom_delivery_charge !== undefined && entry.custom_delivery_charge !== null
        ? num(entry.custom_delivery_charge)
        : num(equipmentRow.pickup_delivery_cost))
    : 0;
  const total = baseRental + delivery +
    attachmentCosts.reduce((sum, item) => sum + item.cost, 0) +
    subAttachmentCosts.reduce((sum, item) => sum + item.cost, 0);
  return { baseRental, delivery, attachmentCosts, subAttachmentCosts, total };
}

function extractFoundation(project, catalogs) {
  const parts = [];
  (project.items || []).forEach((item, index) => {
    const concreteId = item.selected_concrete_id || project.selected_concrete_id || "";
    if (concreteId) {
      const entity = findEntity(catalogs, concreteId, "FoundationInventory");
      const concreteRow = findRow(catalogs, entity, concreteId);
      // Ready-mix concrete is charged at the project delivery/truck level below.
      // Bagged concrete is charged directly on the foundation item.
      if (concreteRow?.material_type === "bagged_concrete" || num(item.concrete_cost) > 0) {
        const qty = item.concrete_bags || item.concrete_volume_cy || item.quantity || 1;
        parts.push(makePart({
          key: `foundation:item:${index}:concrete`,
          name: item.description ? `${item.description} — Concrete` : "Concrete",
          type: "material",
          subtype: concreteRow?.material_type || "concrete",
          sourcePath: `items[${index}].selected_concrete_id`,
          entity,
          inventoryId: concreteId,
          quantity: qty,
          unit: concreteRow?.material_type === "bagged_concrete" ? "bag" : "cy",
          unitCost: item.concrete_rate ?? item.custom_concrete_cost_per_cy,
          extendedCost: item.concrete_cost,
          builderData: item,
          calculation: { concrete_bags: item.concrete_bags, concrete_volume_cy: item.concrete_volume_cy, concrete_cost: item.concrete_cost },
          pricingBasis: { project_concrete_type: project.project_concrete_type, admixtures: project.project_concrete_admixtures },
        }));
      }
    }

    if (item.include_rebar) {
      const size = item.foundation_type === "pillar" ? (item.pillar_rebar_size || "#4") : (item.rebar_size || "#4");
      const rebarRow = catalogs.FoundationInventory?.rows.find(
        (row) => row.material_type === "rebar" && row.rebar_size === size
      );
      const rebarRate = num(item.rebar_rate, num(item.custom_rebar_cost_per_ft, genericUnitCost(rebarRow)));
      const rebarFeet = num(item.rebar_feet);
      const totalRebarCost = num(item.rebar_cost);
      const rebarMaterialCost = rebarFeet > 0 && rebarRate > 0
        ? Math.min(totalRebarCost, rebarFeet * rebarRate)
        : totalRebarCost;
      const rebarLaborCost = Math.max(0, totalRebarCost - rebarMaterialCost);
      parts.push(makePart({
        key: `foundation:item:${index}:rebar`,
        name: `${size} Rebar`,
        type: "material",
        subtype: "rebar",
        sourcePath: `items[${index}].${item.foundation_type === "pillar" ? "pillar_rebar_size" : "rebar_size"}`,
        entity: "FoundationInventory",
        inventoryId: rebarRow?.id || "",
        quantity: rebarFeet || 1,
        unit: "ft",
        unitCost: rebarRate,
        extendedCost: rebarMaterialCost,
        builderData: item,
        calculation: { rebar_cost: totalRebarCost, rebar_material_cost: rebarMaterialCost, rebar_labor_cost: rebarLaborCost, rebar_feet: rebarFeet },
      }));
      if (rebarLaborCost > 0.005) {
        parts.push(manualCostPart({
          key: `foundation:item:${index}:rebar-labor`,
          name: item.description ? `${item.description} — Rebar Labor` : "Rebar Labor",
          type: "labor",
          subtype: "rebar_labor",
          sourcePath: `items[${index}].rebar_cost`,
          cost: rebarLaborCost,
          builderData: item,
          calculation: { total_rebar_cost: totalRebarCost, material_cost: rebarMaterialCost, labor_cost: rebarLaborCost },
        }));
      }
    }

    if (item.include_forming) {
      const formingRow = item.selected_forming_id
        ? catalogs.FoundationInventory?.byId.get(item.selected_forming_id)
        : null;
      const formingQty = num(item.forming_qty, 1);
      const formingRate = num(item.forming_rate, num(item.custom_forming_rate, genericUnitCost(formingRow)));
      const totalFormingCost = num(item.forming_cost);
      const formingMaterialCost = item.selected_forming_id
        ? Math.min(totalFormingCost, formingQty * formingRate)
        : 0;
      const formingLaborCost = Math.max(0, totalFormingCost - formingMaterialCost);
      if (item.selected_forming_id) {
        parts.push(makePart({
          key: `foundation:item:${index}:forming`,
          name: item.description ? `${item.description} — Forming Material` : "Forming Material",
          type: "material",
          subtype: "forming",
          sourcePath: `items[${index}].selected_forming_id`,
          entity: "FoundationInventory",
          inventoryId: item.selected_forming_id,
          quantity: formingQty,
          unit: "piece",
          unitCost: formingRate,
          extendedCost: formingMaterialCost,
          builderData: item,
          calculation: { forming_cost: totalFormingCost, material_cost: formingMaterialCost, forming_qty: formingQty },
        }));
      }
      if (formingLaborCost > 0.005) {
        parts.push(manualCostPart({
          key: `foundation:item:${index}:forming-labor`,
          name: item.description ? `${item.description} — Forming Labor / Allowance` : "Forming Labor / Allowance",
          type: "labor",
          subtype: "forming_labor",
          sourcePath: `items[${index}].forming_cost`,
          cost: formingLaborCost,
          builderData: item,
          calculation: { total_forming_cost: totalFormingCost, material_cost: formingMaterialCost, labor_allowance_cost: formingLaborCost },
        }));
      }
    }

    if (num(item.excavation_cost) > 0.005) {
      parts.push(manualCostPart({
        key: `foundation:item:${index}:excavation`,
        name: item.description ? `${item.description} — Excavation` : "Excavation Labor",
        type: "labor",
        subtype: item.excavation_method || "excavation",
        sourcePath: `items[${index}].excavation_cost`,
        cost: item.excavation_cost,
        quantity: item.excavation_hours || 1,
        unit: item.excavation_hours ? "hour" : "job",
        builderData: item,
        calculation: { hours: item.excavation_hours, rate: item.excavation_rate, cost: item.excavation_cost },
      }));
    }
    if (num(item.pouring_cost) > 0.005) {
      parts.push(manualCostPart({
        key: `foundation:item:${index}:pouring`,
        name: item.description ? `${item.description} — Concrete Pour Labor` : "Concrete Pour Labor",
        type: "labor",
        subtype: "concrete_pouring",
        sourcePath: `items[${index}].pouring_cost`,
        cost: item.pouring_cost,
        quantity: item.concrete_volume_cy || 1,
        unit: "cy",
        builderData: item,
        calculation: { concrete_volume_cy: item.concrete_volume_cy, cost: item.pouring_cost },
      }));
    }
    if (num(item.finishing_cost) > 0.005) {
      parts.push(manualCostPart({
        key: `foundation:item:${index}:finishing`,
        name: item.description ? `${item.description} — Concrete Finishing` : "Concrete Finishing Labor",
        type: "labor",
        subtype: "concrete_finishing",
        sourcePath: `items[${index}].finishing_cost`,
        cost: item.finishing_cost,
        quantity: item.finishing_hours || 1,
        unit: item.finishing_hours ? "hour" : "job",
        builderData: item,
        calculation: { hours: item.finishing_hours, rate: item.finishing_rate, cost: item.finishing_cost },
      }));
    }
  });

  const delivery = project.builder_calculation?.delivery || {};
  const itemConcreteCost = (project.items || []).reduce((sum, item) => sum + num(item.concrete_cost), 0);
  const fallbackDeliveryCost = Math.max(0, num(project.total_concrete_cost) - itemConcreteCost);
  const deliveryCost = num(delivery.concreteTotal, fallbackDeliveryCost);
  if (deliveryCost > 0.005) {
    const concreteServiceItem = (project.items || []).find((item) => {
      const id = item.selected_concrete_id || project.selected_concrete_id || "";
      const row = findRow(catalogs, findEntity(catalogs, id, "LaborServiceInventory"), id);
      return row?.material_type === "concrete_service" || row?.service_category === "concrete_service";
    });
    const concreteId = concreteServiceItem?.selected_concrete_id || project.selected_concrete_id || "";
    const entity = findEntity(catalogs, concreteId, "LaborServiceInventory");
    const hasDetailedDelivery = Array.isArray(delivery.trucksList) && delivery.trucksList.length > 0;

    if (hasDetailedDelivery) {
      const roundedYards = num(delivery.roundedYards, 0);
      const selectedMix = (delivery.availableMixes || []).find((mix) => mix.id === project.project_concrete_type)
        || (delivery.availableMixes || []).find((mix) => mix.id === "4000_ae");
      const mixPrice = num(selectedMix?.price, num(delivery.ratePerYard));
      const mixCost = roundedYards * mixPrice;
      let representedDelivery = 0;

      if (mixCost > 0.005) {
        parts.push(makePart({
          key: "foundation:concrete-delivery:mix",
          name: `Ready-Mix Concrete — ${selectedMix?.name || project.project_concrete_type || "Mix"}`,
          type: "material",
          subtype: "ready_mix_concrete",
          sourcePath: "builder_calculation.delivery.availableMixes",
          entity,
          inventoryId: concreteId,
          quantity: roundedYards,
          unit: "cy",
          unitCost: mixPrice,
          extendedCost: mixCost,
          builderData: { project_concrete_type: project.project_concrete_type },
          calculation: { rounded_yards: roundedYards, mix_price: mixPrice, mix_cost: mixCost },
          pricingBasis: { pricing_mode: "concrete_mix", mix: project.project_concrete_type },
        }));
        representedDelivery += mixCost;
      }

      (project.project_concrete_admixtures || []).forEach((admixId) => {
        const admix = (delivery.availableAdmixes || []).find((candidate) => candidate.id === admixId);
        const rate = num(admix?.price);
        const cost = roundedYards * rate;
        if (cost <= 0.005) return;
        parts.push(makePart({
          key: `foundation:concrete-delivery:admix:${admixId}`,
          name: `Concrete Admixture — ${admix?.name || admixId}`,
          type: "material",
          subtype: "concrete_admixture",
          sourcePath: "project_concrete_admixtures",
          entity,
          inventoryId: concreteId,
          quantity: roundedYards,
          unit: "cy",
          unitCost: rate,
          extendedCost: cost,
          builderData: { admixture_id: admixId },
          calculation: { rounded_yards: roundedYards, rate, cost },
          pricingBasis: { pricing_mode: "concrete_admixture", admixture: admixId },
        }));
        representedDelivery += cost;
      });

      (delivery.trucksList || []).forEach((truck, truckIndex) => {
        const smallLoadFee = num(truck.smallOrderFee);
        if (smallLoadFee > 0.005) {
          parts.push(makePart({
            key: `foundation:concrete-delivery:truck:${truckIndex}:small-load`,
            name: `Concrete Truck ${truckIndex + 1} — Small Load Fee`,
            type: "service",
            subtype: "concrete_small_load_fee",
            sourcePath: `builder_calculation.delivery.trucksList[${truckIndex}].smallOrderFee`,
            entity,
            inventoryId: concreteId,
            quantity: 1,
            unit: "truck",
            unitCost: smallLoadFee,
            extendedCost: smallLoadFee,
            builderData: truck,
            calculation: truck,
            pricingBasis: { pricing_mode: "small_load_fee", rounded_yards: truck.roundedYards },
          }));
          representedDelivery += smallLoadFee;
        }

        const fuelFee = num(truck.fuelFee);
        if (fuelFee > 0.005) {
          parts.push(makePart({
            key: `foundation:concrete-delivery:truck:${truckIndex}:fuel`,
            name: `Concrete Truck ${truckIndex + 1} — Fuel Surcharge`,
            type: "service",
            subtype: "concrete_fuel_surcharge",
            sourcePath: `builder_calculation.delivery.trucksList[${truckIndex}].fuelFee`,
            entity,
            inventoryId: concreteId,
            quantity: 1,
            unit: "truck",
            unitCost: fuelFee,
            extendedCost: fuelFee,
            builderData: truck,
            calculation: truck,
            pricingBasis: { pricing_mode: "fuel_surcharge" },
          }));
          representedDelivery += fuelFee;
        }
      });

      const additionalStopsCost = num(delivery.additionalStopsCost);
      if (additionalStopsCost > 0.005) {
        const stopCount = Math.max(1, Math.round(additionalStopsCost / 100));
        parts.push(manualCostPart({
          key: "foundation:concrete-delivery:additional-stops",
          name: "Additional Sign Locations / Concrete Stops",
          type: "service",
          subtype: "additional_concrete_stop",
          sourcePath: "builder_calculation.delivery.additionalStopsCost",
          cost: additionalStopsCost,
          quantity: stopCount,
          unit: "stop",
          builderData: { stop_count: stopCount },
          calculation: { additional_stops_cost: additionalStopsCost, stop_count: stopCount },
        }));
        representedDelivery += additionalStopsCost;
      }

      const deliveryResidual = deliveryCost - representedDelivery;
      if (Math.abs(deliveryResidual) > 0.005) {
        parts.push(manualCostPart({
          key: "foundation:concrete-delivery:reconciliation",
          name: "Ready-Mix Delivery Reconciliation",
          type: "service",
          subtype: "delivery_reconciliation",
          sourcePath: "builder_calculation.delivery.concreteTotal",
          cost: deliveryResidual,
          builderData: { project_concrete_type: project.project_concrete_type, admixtures: project.project_concrete_admixtures || [] },
          calculation: { authoritative_total: deliveryCost, represented_total: representedDelivery },
        }));
      }
    } else {
      // Older saved projects may only have the authoritative aggregate concrete
      // total. Preserve that frozen number instead of fabricating truck detail.
      parts.push(makePart({
        key: "foundation:concrete-delivery",
        name: "Ready-Mix Concrete Delivery",
        type: "material",
        subtype: "ready_mix_concrete",
        sourcePath: "total_concrete_cost",
        entity,
        inventoryId: concreteId,
        quantity: delivery.roundedYards || 1,
        unit: "cy",
        unitCost: delivery.ratePerYard,
        extendedCost: deliveryCost,
        builderData: { project_concrete_type: project.project_concrete_type, admixtures: project.project_concrete_admixtures || [] },
        calculation: delivery,
        pricingBasis: { pricing_mode: "legacy_delivery_aggregate", mix: project.project_concrete_type, admixtures: project.project_concrete_admixtures || [] },
      }));
    }
  }

  (project.walls || []).forEach((wall, index) => {
    if (wall.materialId) {
      parts.push(makePart({
        key: `foundation:wall:${index}:outer`,
        name: wall.name ? `${wall.name} — Outer wall` : "Wall material",
        type: "material",
        subtype: "wall_material",
        sourcePath: `walls[${index}].materialId`,
        entity: "FoundationInventory",
        inventoryId: wall.materialId,
        quantity: wall.calculatedCosts?.totalBricks || 1,
        unit: "unit",
        extendedCost: wall.calculatedCosts?.materialCost,
        builderData: wall,
        calculation: wall.calculatedCosts || {},
      }));
    }
    if (wall.internalMaterialId) {
      parts.push(makePart({
        key: `foundation:wall:${index}:internal`,
        name: wall.name ? `${wall.name} — Internal wall` : "Internal wall material",
        type: "material",
        subtype: "wall_fill",
        sourcePath: `walls[${index}].internalMaterialId`,
        entity: "FoundationInventory",
        inventoryId: wall.internalMaterialId,
        quantity: wall.calculatedCosts?.internalTotalBricks || 1,
        unit: "unit",
        extendedCost: wall.calculatedCosts?.internalMaterialCost,
        builderData: wall,
        calculation: wall.calculatedCosts || {},
      }));
    }
    if (num(wall.calculatedCosts?.mortarCost) > 0.005) {
      parts.push(manualCostPart({
        key: `foundation:wall:${index}:mortar`,
        name: wall.name ? `${wall.name} — Mortar` : "Wall Mortar",
        type: "consumable",
        subtype: "mortar",
        sourcePath: `walls[${index}].calculatedCosts.mortarCost`,
        cost: wall.calculatedCosts.mortarCost,
        builderData: wall,
        calculation: wall.calculatedCosts,
      }));
    }
    if (num(wall.calculatedCosts?.laborCost) > 0.005) {
      parts.push(manualCostPart({
        key: `foundation:wall:${index}:labor`,
        name: wall.name ? `${wall.name} — Masonry Labor` : "Masonry Labor",
        type: "labor",
        subtype: "masonry_labor",
        sourcePath: `walls[${index}].calculatedCosts.laborCost`,
        cost: wall.calculatedCosts.laborCost,
        quantity: wall.calculatedCosts.laborHours || 1,
        unit: wall.calculatedCosts.laborHours ? "hour" : "job",
        builderData: wall,
        calculation: wall.calculatedCosts,
      }));
    }
    if (num(wall.calculatedCosts?.internalMortarCost) > 0.005) {
      parts.push(manualCostPart({
        key: `foundation:wall:${index}:internal-mortar`,
        name: wall.name ? `${wall.name} — Internal Mortar` : "Internal Wall Mortar",
        type: "consumable",
        subtype: "mortar",
        sourcePath: `walls[${index}].calculatedCosts.internalMortarCost`,
        cost: wall.calculatedCosts.internalMortarCost,
        builderData: wall,
        calculation: wall.calculatedCosts,
      }));
    }
    if (num(wall.calculatedCosts?.internalLaborCost) > 0.005) {
      parts.push(manualCostPart({
        key: `foundation:wall:${index}:internal-labor`,
        name: wall.name ? `${wall.name} — Internal Masonry Labor` : "Internal Masonry Labor",
        type: "labor",
        subtype: "masonry_labor",
        sourcePath: `walls[${index}].calculatedCosts.internalLaborCost`,
        cost: wall.calculatedCosts.internalLaborCost,
        quantity: wall.calculatedCosts.internalLaborHours || 1,
        unit: wall.calculatedCosts.internalLaborHours ? "hour" : "job",
        builderData: wall,
        calculation: wall.calculatedCosts,
      }));
    }
  });

  (project.poles || []).forEach((pole, index) => {
    if (!pole.pole_id) return;
    const row = catalogs.FoundationInventory?.byId.get(pole.pole_id);
    const totalPoleInches = num(pole.height_inches) + num(pole.y_offset_inches);
    const poleQtyFt = totalPoleInches / 12 || 1;
    const isStock = row?.pole_pricing_mode === "stock_price";
    const stockLengthFt = num(row?.pole_stock_length_ft, 20);
    const stockPieces = isStock ? Math.max(1, Math.ceil(totalPoleInches / Math.max(stockLengthFt * 12, 1))) : null;
    const partQty = isStock ? stockPieces : poleQtyFt;
    const partUnitCost = isStock
      ? num(pole.custom_cost_per_unit, num(row?.pole_stock_price))
      : num(pole.custom_cost_per_unit, num(row?.cost_per_unit));
    parts.push(makePart({
      key: `foundation:pole:${index}`,
      name: pole.pole_name || row?.material_name || "Sign Pole",
      type: "material",
      subtype: "pole",
      sourcePath: `poles[${index}].pole_id`,
      entity: "FoundationInventory",
      inventoryId: pole.pole_id,
      quantity: partQty,
      unit: isStock ? "stock_piece" : "ft",
      unitCost: partUnitCost,
      extendedCost: pole.pole_cost,
      builderData: pole,
      calculation: { ...pole, stock_pieces: stockPieces, total_pole_inches: totalPoleInches },
      pricingBasis: { pricing_mode: isStock ? "stock_price" : "per_foot", stock_length_ft: stockLengthFt },
    }));
    if (num(pole.pole_painting_cost) > 0.005) {
      parts.push(manualCostPart({
        key: `foundation:pole:${index}:painting`,
        name: `${pole.pole_name || row?.material_name || "Sign Pole"} — Painting`,
        type: "labor",
        subtype: "pole_painting",
        sourcePath: `poles[${index}].pole_painting_cost`,
        cost: pole.pole_painting_cost,
        quantity: poleQtyFt,
        unit: "ft",
        builderData: pole,
        calculation: pole,
      }));
    }
  });

  (project.wall_caps || []).forEach((cap, index) => {
    if (!cap.cap_inventory_id) return;
    parts.push(makePart({
      key: `foundation:cap:${cap.id || index}`,
      name: "Wall cap",
      type: "material",
      subtype: "wall_cap",
      sourcePath: `wall_caps[${index}].cap_inventory_id`,
      entity: "FoundationInventory",
      inventoryId: cap.cap_inventory_id,
      quantity: 1,
      unit: "stock_piece",
      unitCost: cap.cost,
      extendedCost: cap.cost,
      builderData: cap,
      calculation: cap,
    }));
  });

  (project.selected_equipment || []).forEach((eq, index) => {
    const breakdown = foundationEquipmentBreakdown(eq, catalogs);
    const equipmentRow = eq.equipment_id ? catalogs.FoundationInventory?.byId.get(eq.equipment_id) : null;
    const qty = eq.custom_qty ?? eq.rental_duration ?? 1;
    if (eq.equipment_id) {
      parts.push(makePart({
        key: `foundation:equipment:${index}`,
        name: equipmentRow?.material_name || "Foundation Equipment",
        type: "equipment",
        subtype: "excavation_equipment",
        sourcePath: `selected_equipment[${index}].equipment_id`,
        entity: "FoundationInventory",
        inventoryId: eq.equipment_id,
        quantity: qty,
        unit: eq.rental_period || "day",
        unitCost: num(breakdown.baseRental) / Math.max(num(qty, 1), 1),
        extendedCost: breakdown.baseRental,
        builderData: eq,
        calculation: { ...eq, equipment_total_with_attachments: eq.equipment_cost, base_equipment_cost: breakdown.baseRental },
        pricingBasis: { pricing_mode: `per_${eq.rental_period || "day"}` },
      }));
    }
    if (eq.equipment_id && Math.abs(num(breakdown.delivery)) > 0.005) {
      parts.push(makePart({
        key: `foundation:equipment:${index}:delivery`,
        name: `${equipmentRow?.material_name || "Foundation Equipment"} — Delivery / Pickup`,
        type: "service",
        subtype: "equipment_delivery",
        sourcePath: `selected_equipment[${index}].include_delivery`,
        entity: "FoundationInventory",
        inventoryId: eq.equipment_id,
        quantity: 1,
        unit: "delivery",
        unitCost: breakdown.delivery,
        extendedCost: breakdown.delivery,
        builderData: eq,
        calculation: { include_delivery: eq.include_delivery, delivery_cost: breakdown.delivery },
        pricingBasis: { pricing_mode: "pickup_delivery" },
      }));
    }
    breakdown.attachmentCosts.forEach((entry) => {
      if (!entry.id) return;
      parts.push(makePart({
        key: `foundation:equipment:${index}:attachment:${entry.id}`,
        name: entry.row?.material_name || "Equipment Attachment",
        type: "equipment",
        subtype: entry.row?.material_type || "attachment",
        sourcePath: `selected_equipment[${index}].attachment_counts.${entry.id}`,
        entity: "FoundationInventory",
        inventoryId: entry.id,
        quantity: entry.quantity * Math.max(num(qty, 1), 1),
        unit: eq.rental_period || "day",
        unitCost: (entry.quantity * Math.max(num(qty, 1), 1)) ? entry.cost / (entry.quantity * Math.max(num(qty, 1), 1)) : entry.cost,
        extendedCost: entry.cost,
        builderData: entry.attachment,
        calculation: { rental_period: eq.rental_period, rental_duration: eq.rental_duration, attachment_quantity: entry.quantity, total_cost: entry.cost },
        pricingBasis: { pricing_mode: `per_${eq.rental_period || "day"}` },
      }));
    });
    breakdown.subAttachmentCosts.forEach((entry) => {
      if (!entry.id) return;
      parts.push(makePart({
        key: `foundation:equipment:${index}:sub-attachment:${entry.id}`,
        name: entry.row?.material_name || "Equipment Sub-Attachment",
        type: "equipment",
        subtype: entry.row?.material_type || "sub_attachment",
        sourcePath: `selected_equipment[${index}].sub_attachment_counts.${entry.id}`,
        entity: "FoundationInventory",
        inventoryId: entry.id,
        quantity: entry.quantity * Math.max(num(qty, 1), 1),
        unit: eq.rental_period || "day",
        unitCost: (entry.quantity * Math.max(num(qty, 1), 1)) ? entry.cost / (entry.quantity * Math.max(num(qty, 1), 1)) : entry.cost,
        extendedCost: entry.cost,
        builderData: entry.attachment,
        calculation: { rental_period: eq.rental_period, rental_duration: eq.rental_duration, attachment_quantity: entry.quantity, total_cost: entry.cost },
        pricingBasis: { pricing_mode: `per_${eq.rental_period || "day"}` },
      }));
    });
    const representedEquipment = num(breakdown.total);
    if (eq.equipment_cost != null && Math.abs(num(eq.equipment_cost) - representedEquipment) > 0.005) {
      parts.push(manualCostPart({
        key: `foundation:equipment:${index}:saved-adjustment`,
        name: `${equipmentRow?.material_name || "Foundation Equipment"} — Saved Cost Adjustment`,
        type: "equipment",
        subtype: "equipment_adjustment",
        sourcePath: `selected_equipment[${index}].equipment_cost`,
        cost: num(eq.equipment_cost) - representedEquipment,
        builderData: eq,
        calculation: { authoritative_total: eq.equipment_cost, reconstructed_total: representedEquipment },
      }));
    }
  });

  (project.signage_cabinets || []).forEach((cabinet, index) => {
    parts.push(makePart({
      key: `foundation:cabinet:${cabinet.id || index}`,
      name: cabinet.description || "Signage Cabinet",
      type: "fabrication",
      subtype: "signage_cabinet",
      sourcePath: `signage_cabinets[${index}]`,
      quantity: cabinet.quantity || 1,
      unit: "each",
      unitCost: cabinet.unit_cost,
      extendedCost: num(cabinet.unit_cost) * num(cabinet.quantity, 1),
      builderData: cabinet,
      calculation: cabinet,
    }));
  });
  if (num(project.builder_calculation?.landscape_cost) > 0.005) {
    parts.push(manualCostPart({
      key: "foundation:landscape",
      name: "Landscape Materials",
      type: "material",
      subtype: "landscape",
      sourcePath: "builder_calculation.landscape_cost",
      cost: project.builder_calculation.landscape_cost,
      builderData: project.landscape || {},
      calculation: { total_cost: project.builder_calculation.landscape_cost },
    }));
  }
  return parts;
}

function extractPainting(project) {
  const parts = [];
  let itemMaskTotal = 0;
  let itemPaintTotal = 0;
  let itemLaborTotal = 0;

  (project.items || []).forEach((item, index) => {
    const label = item.description || (item.item_type === "lettering" ? "Painted Lettering" : item.item_type === "complex_shapes" ? "Painted Complex Shape" : "Painted Panel");
    const quantity = item.item_type === "lettering" ? 1 : (item.quantity || 1);
    const maskCost = num(item.supplies_cost);
    const paintCost = num(item.paint_cost);
    const laborCost = num(item.labor_cost);
    itemMaskTotal += maskCost;
    itemPaintTotal += paintCost;
    itemLaborTotal += laborCost;

    if (Math.abs(maskCost) > 0.005) {
      parts.push(manualCostPart({
        key: `painting:item:${index}:mask`,
        name: `${label} — Paint Mask`,
        type: "consumable",
        subtype: "paint_mask",
        sourcePath: `items[${index}].supplies_cost`,
        cost: maskCost,
        quantity,
        unit: quantity > 1 ? "each" : "job",
        builderData: item,
        calculation: { paint_mask_sqft: item.paint_mask_sqft, paint_colors: item.paint_colors, supplies_cost: maskCost },
      }));
    }
    if (Math.abs(paintCost) > 0.005) {
      parts.push(manualCostPart({
        key: `painting:item:${index}:paint`,
        name: `${label} — Paint & Supplies`,
        type: "material",
        subtype: "liquid_paint_supplies",
        sourcePath: `items[${index}].paint_cost`,
        cost: paintCost,
        quantity,
        unit: quantity > 1 ? "each" : "job",
        builderData: item,
        calculation: { paintable_sqft: item.paintable_sqft, paint_gallons: item.paint_gallons, paint_colors: item.paint_colors, paint_cost: paintCost },
      }));
    }
    if (Math.abs(laborCost) > 0.005) {
      parts.push(manualCostPart({
        key: `painting:item:${index}:labor`,
        name: `${label} — Painting Labor`,
        type: "labor",
        subtype: "painting_labor",
        sourcePath: `items[${index}].labor_cost`,
        cost: laborCost,
        quantity: item.labor_hours || 1,
        unit: item.labor_hours ? "hour" : "job",
        builderData: item,
        calculation: { labor_hours: item.labor_hours, labor_cost: laborCost },
      }));
    }
  });

  const authoritativeMaterialTotal = num(project.total_paint_mask_cost) + num(project.total_liquid_paint_and_supplies_cost);
  const materialAdjustment = authoritativeMaterialTotal - itemMaskTotal - itemPaintTotal;
  if (Math.abs(materialAdjustment) > 0.005) {
    parts.push(manualCostPart({
      key: "painting:material-adjustment",
      name: materialAdjustment > 0 ? "Painting Minimum / Fixed Materials" : "Painting Materials Adjustment",
      type: "material",
      subtype: "paint_material_adjustment",
      sourcePath: "total_liquid_paint_and_supplies_cost",
      cost: materialAdjustment,
      calculation: {
        authoritative_material_total: authoritativeMaterialTotal,
        item_mask_total: itemMaskTotal,
        item_paint_total: itemPaintTotal,
        adjustment: materialAdjustment,
      },
    }));
  }

  const authoritativeLaborTotal = num(project.total_labor_cost);
  const laborAdjustment = authoritativeLaborTotal - itemLaborTotal;
  if (Math.abs(laborAdjustment) > 0.005) {
    parts.push(manualCostPart({
      key: "painting:fixed-labor-adjustment",
      name: laborAdjustment > 0 ? "Painting Setup / Mixing / Minimum Labor" : "Painting Labor Adjustment",
      type: "labor",
      subtype: "painting_fixed_labor",
      sourcePath: "total_labor_cost",
      cost: laborAdjustment,
      calculation: {
        authoritative_labor_total: authoritativeLaborTotal,
        item_labor_total: itemLaborTotal,
        adjustment: laborAdjustment,
      },
    }));
  }
  return parts;
}

function extractCNC(project) {
  const parts = [];
  (project.items || []).forEach((item, index) => {
    if (num(item.machine_cost) > 0.005) {
      parts.push(manualCostPart({
        key: `cnc:item:${index}:machine`,
        name: item.description ? `${item.description} — CNC Machine Time` : "CNC Machine Time",
        type: "equipment",
        subtype: "cnc_machine_time",
        sourcePath: `items[${index}].machine_cost`,
        cost: item.machine_cost,
        quantity: item.machine_time_hours || 1,
        unit: item.machine_time_hours ? "hour" : "job",
        builderData: item,
        calculation: { machine_time_hours: item.machine_time_hours, machine_cost: item.machine_cost, rate: project.machine_rate_per_hour },
      }));
    }
    if (num(item.labor_cost) > 0.005) {
      parts.push(manualCostPart({
        key: `cnc:item:${index}:labor`,
        name: item.description ? `${item.description} — CNC Setup / Handling Labor` : "CNC Setup / Handling Labor",
        type: "labor",
        subtype: "cnc_setup_labor",
        sourcePath: `items[${index}].labor_cost`,
        cost: item.labor_cost,
        quantity: item.setup_time_hours || 1,
        unit: item.setup_time_hours ? "hour" : "job",
        builderData: item,
        calculation: { setup_time_hours: item.setup_time_hours, labor_cost: item.labor_cost, rate: project.labor_rate, hold_down: item.hold_down },
      }));
    }
  });
  const dynamicItemLabor = (project.items || []).reduce((sum, item) => sum + num(item.labor_cost), 0);
  const fixedSetupCost = num(
    project.builder_calculation?.totals?.fixed_setup_cost,
    num(project.fixed_setup_hours) * num(project.labor_rate)
  );
  if (fixedSetupCost > 0.005) {
    parts.push(manualCostPart({
      key: "cnc:fixed-setup",
      name: "CNC Fixed Setup Labor",
      type: "labor",
      subtype: "fixed_setup",
      sourcePath: "fixed_setup_hours",
      cost: fixedSetupCost,
      quantity: project.fixed_setup_hours || 1,
      unit: project.fixed_setup_hours ? "hour" : "job",
      calculation: { fixed_setup_hours: project.fixed_setup_hours, labor_rate: project.labor_rate, cost: fixedSetupCost },
    }));
  }

  // SignEstimate Pro applies min_cnc_labor_hours to the dynamic item setup labor.
  // The saved total_labor_cost is authoritative, so materialize only the balance
  // not already represented by item labor + fixed setup. This survives normal
  // reopen/sync without needing transient builder_calculation data.
  const authoritativeLaborTotal = num(
    project.total_labor_cost,
    num(project.builder_calculation?.totals?.total_labor_cost, dynamicItemLabor + fixedSetupCost)
  );
  const minimumLaborAdjustment = authoritativeLaborTotal - dynamicItemLabor - fixedSetupCost;
  if (Math.abs(minimumLaborAdjustment) > 0.005) {
    parts.push(manualCostPart({
      key: "cnc:minimum-dynamic-labor-adjustment",
      name: minimumLaborAdjustment > 0 ? "CNC Minimum Dynamic Labor" : "CNC Labor Adjustment",
      type: "labor",
      subtype: "minimum_dynamic_labor",
      sourcePath: "total_labor_cost",
      cost: minimumLaborAdjustment,
      quantity: 1,
      unit: "job",
      calculation: {
        total_labor_cost: authoritativeLaborTotal,
        item_labor_cost: dynamicItemLabor,
        fixed_setup_cost: fixedSetupCost,
        minimum_dynamic_labor_adjustment: minimumLaborAdjustment,
      },
    }));
  }
  return parts;
}

function extractLaser(project) {
  const parts = [];
  let itemMachineTotal = 0;
  let itemLaborTotal = 0;
  (project.items || []).forEach((item, index) => {
    itemMachineTotal += num(item.machine_cost);
    itemLaborTotal += num(item.labor_cost);
    if (num(item.machine_cost) > 0.005) {
      parts.push(manualCostPart({
        key: `laser:item:${index}:machine`,
        name: item.description ? `${item.description} — Laser Machine Time` : "Laser Machine Time",
        type: "equipment",
        subtype: "laser_machine_time",
        sourcePath: `items[${index}].machine_cost`,
        cost: item.machine_cost,
        quantity: item.machine_time_hours || 1,
        unit: item.machine_time_hours ? "hour" : "job",
        builderData: item,
        calculation: { engrave_hours: item.engrave_hours, cut_hours: item.cut_hours, machine_time_hours: item.machine_time_hours, machine_cost: item.machine_cost },
      }));
    }
    if (num(item.labor_cost) > 0.005) {
      parts.push(manualCostPart({
        key: `laser:item:${index}:labor`,
        name: item.description ? `${item.description} — Laser Handling Labor` : "Laser Handling Labor",
        type: "labor",
        subtype: "laser_handling_labor",
        sourcePath: `items[${index}].labor_cost`,
        cost: item.labor_cost,
        quantity: item.handling_time_hours || 1,
        unit: item.handling_time_hours ? "hour" : "job",
        builderData: item,
        calculation: { handling_time_hours: item.handling_time_hours, labor_cost: item.labor_cost },
      }));
    }
  });
  const fixedSetupCost = num(
    project.builder_calculation?.totals?.fixed_setup_cost,
    num(project.fixed_setup_hours) * num(project.labor_rate)
  );
  if (fixedSetupCost > 0.005) {
    parts.push(manualCostPart({
      key: "laser:fixed-setup",
      name: "Laser Fixed Setup Labor",
      type: "labor",
      subtype: "fixed_setup",
      sourcePath: "fixed_setup_hours",
      cost: fixedSetupCost,
      quantity: project.fixed_setup_hours || 1,
      unit: project.fixed_setup_hours ? "hour" : "job",
      calculation: { fixed_setup_hours: project.fixed_setup_hours, labor_rate: project.labor_rate, cost: fixedSetupCost },
    }));
  }

  const authoritativeMachineTotal = num(
    project.total_machine_cost,
    num(project.builder_calculation?.totals?.total_machine_cost, itemMachineTotal)
  );
  const machineAdjustment = authoritativeMachineTotal - itemMachineTotal;
  if (Math.abs(machineAdjustment) > 0.005) {
    parts.push(manualCostPart({
      key: "laser:machine-adjustment",
      name: "Laser Machine Cost Adjustment",
      type: "equipment",
      subtype: "machine_adjustment",
      sourcePath: "total_machine_cost",
      cost: machineAdjustment,
      calculation: { total_machine_cost: authoritativeMachineTotal, item_machine_cost: itemMachineTotal, adjustment: machineAdjustment },
    }));
  }

  const authoritativeLaborTotal = num(
    project.total_labor_cost,
    num(project.builder_calculation?.totals?.total_labor_cost, itemLaborTotal + fixedSetupCost)
  );
  const laborAdjustment = authoritativeLaborTotal - itemLaborTotal - fixedSetupCost;
  if (Math.abs(laborAdjustment) > 0.005) {
    parts.push(manualCostPart({
      key: "laser:labor-adjustment",
      name: "Laser Labor Adjustment",
      type: "labor",
      subtype: "labor_adjustment",
      sourcePath: "total_labor_cost",
      cost: laborAdjustment,
      calculation: { total_labor_cost: authoritativeLaborTotal, item_labor_cost: itemLaborTotal, fixed_setup_cost: fixedSetupCost, adjustment: laborAdjustment },
    }));
  }

  const authoritativeSupplies = num(
    project.total_supplies_cost,
    num(project.fixed_material_setup_cost, project.builder_calculation?.totals?.total_supplies_cost)
  );
  if (Math.abs(authoritativeSupplies) > 0.005) {
    parts.push(manualCostPart({
      key: "laser:fixed-material-setup",
      name: "Laser Material Setup / Consumables",
      type: "consumable",
      subtype: "material_setup",
      sourcePath: "total_supplies_cost",
      cost: authoritativeSupplies,
      calculation: { fixed_material_setup_cost: project.fixed_material_setup_cost, total_supplies_cost: authoritativeSupplies },
    }));
  }
  return parts;
}

function extractManualItems(project, moduleKey) {
  return (project.items || []).map((item, index) => makePart({
    key: `${moduleKey}:item:${index}`,
    name: item.description || `${moduleKey.toUpperCase()} item ${index + 1}`,
    type: "fabrication",
    subtype: item.item_type || moduleKey,
    sourcePath: `items[${index}]`,
    quantity: item.quantity || 1,
    unit: "item",
    unitCost: item.quantity ? num(item.item_total_cost) / num(item.quantity, 1) : 0,
    extendedCost: item.item_total_cost,
    builderData: item,
    calculation: item,
  }));
}

// Extraction memo (#413): keyed on the project object identity + module/
// options + catalogs identity. The same project re-rendered through sync
// paths skips re-extraction; any payload or catalog change recomputes.
const _extractCache = new WeakMap();

export function extractBuilderParts(moduleKey, project, catalogs = {}, options = {}) {
  if (!project) return [];
  if (typeof project !== "object") return _extractBuilderPartsComputed(moduleKey, project, catalogs, options);
  const key = `${moduleKey}|${options?.legacyMode ? 1 : 0}`;
  let byKey = _extractCache.get(project);
  const hit = byKey?.get(key);
  if (hit && hit.catalogs === catalogs) return hit.out;
  const out = _extractBuilderPartsComputed(moduleKey, project, catalogs, options);
  if (!byKey) { byKey = new Map(); _extractCache.set(project, byKey); }
  byKey.set(key, { catalogs, out });
  return out;
}

function _extractBuilderPartsComputed(moduleKey, project, catalogs = {}, options = {}) {
  switch (moduleKey) {
    case "foundation": return extractFoundation(project, catalogs);
    case "channel_letters": return extractChannel(project, catalogs);
    case "vinyl": return extractVinyl(project, catalogs, options);
    case "metal": return extractMetal(project);
    case "brick_stone": return extractBrick(project, catalogs, options);
    case "maintenance": return extractMaintenance(project, catalogs, options);
    case "painting": return extractPainting(project);
    case "cnc": return extractCNC(project);
    case "laser": return extractLaser(project);
    default: return extractManualItems(project, moduleKey || "legacy");
  }
}

function effectiveCurrentUnitCost(descriptor, row) {
  if (Number.isFinite(Number(descriptor.unit_cost)) && Number(descriptor.unit_cost) !== 0) {
    return Number(descriptor.unit_cost);
  }
  return genericUnitCost(row);
}

export async function syncBuilderParts({ builderProduct, sourceProject, acceptPrices = false, legacyMode = false, builderRecalculated = false, catalogsOverride = null, strictCatalogs = false, existingPartsOverride = null, inventoryRowsOverride = null, skipUnchangedWrites = false, planOnly = false, planTimestamp = "" }) {
  if (!builderProduct?.id || !sourceProject) {
    return {
      partCount: 0,
      detachedCount: 0,
      changedCount: 0,
      newPartCount: 0,
      removedPartCount: 0,
      writesPerformed: 0,
      recalcRequired: false,
      recalcReason: "",
      usesDirectLiveReprice: false,
      currentPartsTotal: 0,
      frozenPartsTotal: 0,
      currentMarkupTotal: 0,
      frozenMarkupTotal: 0,
      manualAddonFrozenTotal: 0,
      manualAddonCurrentTotal: 0,
      parts: [],
      partWritePlan: [],
    };
  }

  const catalogs = catalogsOverride || await loadBuilderCatalogs(builderProduct.module_key, { strict: strictCatalogs });
  const descriptors = extractBuilderParts(builderProduct.module_key, sourceProject, catalogs, { legacyMode });
  const existing = existingPartsOverride || await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProduct.id }, sort: "sort_order", label: "Builder Parts" });
  const byKey = new Map((existing || []).map((part) => [part.part_key, part]));
  const seen = new Set();
  const synced = [];
  let detachedCount = 0;
  let changedCount = 0;
  let newPartCount = 0;
  let removedPartCount = 0;
  let writesPerformed = 0;
  let recalcRequired = false;
  const recalcPartNames = [];
  const partWritePlan = [];
  const syncNow = () => planTimestamp || nowIso();
  const directLiveReprice = DIRECT_LIVE_REPRICE_MODULES.has(builderProduct.module_key);

  const writePartUpdate = async (old, patch) => {
    const step = {
      operation: "update",
      part_id: old.id,
      part_key: old.part_key,
      expected_updated_date: old.updated_date || "",
      patch,
    };
    partWritePlan.push(step);
    if (planOnly) return { ...old, ...patch };
    const saved = await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderPart,
      id: old.id,
      expectedUpdatedAt: old.updated_date || "",
      expectedFields: expectedBuilderEntityFields(old, patch),
      nextFields: patch,
      guardFields: { builder_product_id: old.builder_product_id },
      label: `Builder Part “${old.part_name || "Part"}” synchronization`,
    });
    writesPerformed += 1;
    return saved;
  };

  const writePartCreate = async (data) => {
    const step = {
      operation: "create",
      part_key: data.part_key,
      data,
    };
    partWritePlan.push(step);
    if (planOnly) return { ...data, id: `planned:${data.part_key}`, updated_date: "" };
    const { record: created, status } = await createBuilderPartWithRecovery({
      entity: staffEntities.BuilderPart,
      data,
      label: `Builder Part “${data.part_name || data.part_key || "Part"}” synchronization`,
    });
    if (status !== "existing") writesPerformed += 1;
    return created;
  };

  // (#419) Writes keep their per-row CAS guards — updateMany can't express a
  // different expected-state/patch per row — but they now run in a bounded
  // pool so a large sync doesn't spend N serial round-trips on the wire.
  // `synced` slots are reserved at queue time so result order stays
  // deterministic and matches descriptor order.
  const WRITE_CONCURRENCY = 4;
  const writeJobs = [];
  const queueWrite = (work) => {
    const slot = synced.length;
    synced.push(null);
    writeJobs.push(async () => {
      synced[slot] = await work();
    });
  };

  for (let index = 0; index < descriptors.length; index += 1) {
    const descriptor = descriptors[index];
    seen.add(descriptor.part_key);
    const old = byKey.get(descriptor.part_key);
    const resolvedEntity = findEntity(catalogs, descriptor.inventory_item_id, descriptor.inventory_entity);

    // Intentional Builder overrides are independent frozen Parts. Preserve the
    // override instead of allowing a Builder save to regenerate its values.
    if (old?.builder_sync_state === "detached_override") {
      const currentRow = findRow(catalogs, old.inventory_entity || resolvedEntity, old.inventory_item_id || descriptor.inventory_item_id);
      const candidateId = descriptor.inventory_item_id || old.inventory_item_id || old.original_inventory_item_id || "";
      const candidateEntity = findEntity(catalogs, candidateId, old.inventory_entity || resolvedEntity);
      const candidateRow = findRow(catalogs, candidateEntity, candidateId);
      const corePatch = {
        inventory_link_state: currentRow ? "attached" : old.inventory_link_state,
        current_inventory_snapshot: currentRow || old.current_inventory_snapshot || {},
        reattach_candidate_id: candidateId,
        reattach_candidate_name: rowName(candidateEntity, candidateRow) || old.inventory_item_name || descriptor.part_name,
        price_state: "detached",
        is_active: true,
      };
      if (!skipUnchangedWrites || patchDiffers(old, corePatch)) {
        const patch = { ...corePatch, last_price_check_at: syncNow() };
        queueWrite(() => writePartUpdate(old, patch));
      } else {
        synced.push(old);
      }
      detachedCount += 1;
      continue;
    }
    const currentRow = findRow(catalogs, resolvedEntity, descriptor.inventory_item_id);
    const currentName = rowName(resolvedEntity, currentRow) || descriptor.part_name;
    const oldFrozenName = old?.inventory_item_name || rowName(old?.inventory_entity, old?.frozen_inventory_snapshot) || descriptor.part_name;
    const candidate = !currentRow && oldFrozenName
      ? findNameCandidate(catalogs, old?.inventory_entity || resolvedEntity, oldFrozenName)
      : null;
    const hasInventoryLink = !!descriptor.inventory_item_id || !!old?.inventory_item_id || !!old?.original_inventory_item_id;
    const detached = hasInventoryLink && !currentRow;
    const currentPricing = pricingSnapshot(currentRow);
    const frozenPricing = pricingSnapshot(old?.frozen_inventory_snapshot);
    const linkChanged = !!old && !!descriptor.inventory_item_id && descriptor.inventory_item_id !== (old.inventory_item_id || old.original_inventory_item_id);
    const pricingChanged = !!old && !!currentRow && !same(currentPricing, frozenPricing);
    const changed = linkChanged || pricingChanged;
    const currentUnitCost = effectiveCurrentUnitCost(descriptor, currentRow);
    const currentExtended = num(descriptor.extended_cost);
    const timestamp = syncNow();

    const lastBuilderCalculatedPricing = old?.pricing_basis_snapshot?.builder_calculated_inventory_pricing || {};
    const builderAlreadyCalculatedCurrentPricing = !!old && same(currentPricing, lastBuilderCalculatedPricing);
    if (
      pricingChanged &&
      !legacyMode &&
      builderProduct.price_state !== "unchecked" &&
      !directLiveReprice &&
      !builderRecalculated &&
      !builderAlreadyCalculatedCurrentPricing
    ) {
      // A frozen inventory snapshot that differs from the current catalog means
      // the accepted price is stale. Non-live Builders must run their calculator
      // before Update Price unless we have explicit proof that this exact catalog
      // pricing was already used by the last Builder calculation.
      recalcRequired = true;
      recalcPartNames.push(currentName || descriptor.part_name);
    }

    let linkState = "manual";
    if (hasInventoryLink) {
      if (currentRow) linkState = "attached";
      else if (candidate) linkState = "reattach_available";
      else linkState = "detached";
    }

    if (detached) detachedCount += 1;
    if (changed) changedCount += 1;

    if (!old) {
      const establishBaseline = legacyMode || builderProduct.price_state === "unchecked" || acceptPrices;
      const initialFrozenUnit = establishBaseline ? (descriptor.unit_cost || currentUnitCost) : 0;
      const initialFrozenExtended = establishBaseline ? num(descriptor.extended_cost) : 0;
      if (!establishBaseline) {
        changedCount += 1;
        newPartCount += 1;
      }
      queueWrite(() => writePartCreate({
        builder_product_id: builderProduct.id,
        part_key: descriptor.part_key,
        sort_order: index,
        part_name: descriptor.part_name,
        part_type: descriptor.part_type,
        part_subtype: descriptor.part_subtype,
        source_module_key: builderProduct.module_key,
        source_path: descriptor.source_path,
        builder_sync_state: "linked",
        inventory_entity: resolvedEntity,
        inventory_item_id: descriptor.inventory_item_id,
        original_inventory_item_id: descriptor.inventory_item_id,
        inventory_item_name: currentName,
        inventory_link_state: linkState,
        reattach_candidate_id: candidate?.id || "",
        reattach_candidate_name: candidate ? rowName(old?.inventory_entity || resolvedEntity, candidate) : "",
        frozen_inventory_snapshot: establishBaseline ? (currentRow || {}) : {},
        current_inventory_snapshot: currentRow || {},
        builder_data: descriptor.builder_data,
        calculation_snapshot: descriptor.calculation_snapshot,
        pricing_basis_snapshot: {
          ...descriptor.pricing_basis_snapshot,
          inventory_pricing: currentPricing,
          ...(builderRecalculated ? { builder_calculated_inventory_pricing: currentPricing } : {}),
        },
        quantity: descriptor.quantity,
        unit: descriptor.unit,
        frozen_unit_cost: initialFrozenUnit,
        frozen_extended_cost: initialFrozenExtended,
        current_unit_cost: currentUnitCost,
        current_extended_cost: currentExtended,
        price_state: legacyMode
          ? "legacy_frozen"
          : detached
            ? "detached"
            : establishBaseline
              ? "current"
              : "changed",
        price_delta: currentExtended - initialFrozenExtended,
        price_delta_percent: initialFrozenExtended ? ((currentExtended - initialFrozenExtended) / initialFrozenExtended) * 100 : 0,
        inventory_updated_date_snapshot: establishBaseline ? (currentRow?.updated_date || "") : "",
        last_price_check_at: timestamp,
        last_price_update_at: acceptPrices ? timestamp : "",
        manual_cost_override: !hasInventoryLink,
        manual_cost: !hasInventoryLink ? descriptor.extended_cost : undefined,
        is_active: true,
        notes: legacyMode
          ? "Backfilled from an existing Builder Product. Saved estimator costs remain authoritative; catalog snapshot is compatibility context."
          : establishBaseline
            ? ""
            : "New Builder Part added after the Product price was frozen. Frozen cost remains $0 until Update Price is explicitly accepted.",
      }));
      continue;
    }

    const shouldAccept = acceptPrices && !detached;
    const frozenUnit = shouldAccept ? currentUnitCost : num(old.frozen_unit_cost, descriptor.unit_cost || currentUnitCost);
    const frozenExtended = shouldAccept ? currentExtended : num(old.frozen_extended_cost, descriptor.extended_cost);
    const state = detached
      ? "detached"
      : legacyMode || old.price_state === "legacy_frozen"
        ? "legacy_frozen"
        : changed || Math.abs(currentExtended - frozenExtended) > 0.005
          ? "changed"
          : "current";

    const patch = {
      sort_order: index,
      part_name: descriptor.part_name,
      part_type: descriptor.part_type,
      part_subtype: descriptor.part_subtype,
      source_module_key: builderProduct.module_key,
      source_path: descriptor.source_path,
      inventory_entity: resolvedEntity || old.inventory_entity,
      inventory_item_id: descriptor.inventory_item_id,
      inventory_item_name: currentName || old.inventory_item_name,
      inventory_link_state: linkState,
      reattach_candidate_id: candidate?.id || "",
      reattach_candidate_name: candidate ? rowName(old.inventory_entity || resolvedEntity, candidate) : "",
      current_inventory_snapshot: currentRow || {},
      builder_data: descriptor.builder_data,
      calculation_snapshot: descriptor.calculation_snapshot,
      pricing_basis_snapshot: {
        ...descriptor.pricing_basis_snapshot,
        inventory_pricing: currentPricing,
        builder_calculated_inventory_pricing: builderRecalculated
          ? currentPricing
          : old.pricing_basis_snapshot?.builder_calculated_inventory_pricing || {},
      },
      quantity: descriptor.quantity,
      unit: descriptor.unit,
      current_unit_cost: currentUnitCost,
      current_extended_cost: currentExtended,
      price_state: shouldAccept ? "current" : state,
      price_delta: currentExtended - frozenExtended,
      price_delta_percent: frozenExtended ? ((currentExtended - frozenExtended) / frozenExtended) * 100 : 0,
      is_active: true,
    };

    if (shouldAccept) {
      patch.frozen_inventory_snapshot = currentRow || old.frozen_inventory_snapshot || {};
      patch.frozen_unit_cost = frozenUnit;
      patch.frozen_extended_cost = frozenExtended;
      patch.inventory_updated_date_snapshot = currentRow?.updated_date || old.inventory_updated_date_snapshot || "";
      patch.last_price_update_at = timestamp;
    }

    if (!skipUnchangedWrites || patchDiffers(old, patch)) {
      const writePatch = { ...patch, last_price_check_at: timestamp };
      queueWrite(() => writePartUpdate(old, writePatch));
    } else {
      synced.push(old);
    }
  }

  // (#419) Manual add-ons each used to pay a serial inventory row read; fetch
  // the needed rows in one bounded parallel pre-pass before the update loop.
  const addonRowKeys = new Map();
  for (const old of existing || []) {
    if (seen.has(old.part_key) || old.is_active === false) continue;
    if (old.builder_sync_state !== "manual_addon") continue;
    if (!old.inventory_entity || !old.inventory_item_id || old.manual_cost_override) continue;
    const key = `${old.inventory_entity}:${old.inventory_item_id}`;
    if (!inventoryRowsOverride?.has(key) && !addonRowKeys.has(key)) addonRowKeys.set(key, old);
  }
  const addonRows = new Map();
  const addonKeys = [...addonRowKeys.keys()];
  for (let i = 0; i < addonKeys.length; i += WRITE_CONCURRENCY) {
    await Promise.all(addonKeys.slice(i, i + WRITE_CONCURRENCY).map(async (key) => {
      const part = addonRowKeys.get(key);
      try {
        addonRows.set(key, await staffEntities[part.inventory_entity].get(part.inventory_item_id));
      } catch (error) {
        if (strictCatalogs) {
          throw new Error(`${part.inventory_entity} inventory could not be verified for Part “${part.part_name || "Part"}”: ${error?.message || "read failed"}`);
        }
      }
    }));
  }

  for (const old of existing || []) {
    if (seen.has(old.part_key) || old.is_active === false) continue;
    if (old.builder_sync_state === "detached_override") {
      detachedCount += 1;
      synced.push(old);
      continue;
    }
    if (old.builder_sync_state === "manual_addon") {
      // Intentional independent add-ons are not produced by the Builder, but
      // they still track their own Master Inventory record for current-price
      // comparison and remain part of the Product economics on every Builder save.
      // Reserve the synced slot now; a queued refresh write overwrites it.
      const syncedSlot = synced.length;
      synced.push(old);
      if (old.inventory_entity && old.inventory_item_id && !old.manual_cost_override) {
        let currentRow = null;
        const inventoryKey = `${old.inventory_entity}:${old.inventory_item_id}`;
        if (inventoryRowsOverride?.has(inventoryKey)) {
          currentRow = inventoryRowsOverride.get(inventoryKey);
        } else {
          currentRow = addonRows.get(inventoryKey) || null;
        }
        if (currentRow) {
          const currentUnit = independentPartUnitCost(old, currentRow);
          const currentExtended = currentUnit * num(old.quantity, 1);
          const changed = Math.abs(currentExtended - num(old.frozen_extended_cost)) > 0.005 ||
            !same(pricingSnapshot(currentRow), pricingSnapshot(old.frozen_inventory_snapshot));
          const patch = {
            current_inventory_snapshot: currentRow,
            current_unit_cost: currentUnit,
            current_extended_cost: currentExtended,
            inventory_link_state: "attached",
            price_state: changed ? "changed" : "current",
            price_delta: currentExtended - num(old.frozen_extended_cost),
            price_delta_percent: num(old.frozen_extended_cost) ? ((currentExtended - num(old.frozen_extended_cost)) / num(old.frozen_extended_cost)) * 100 : 0,
            is_active: true,
          };
          if (changed) changedCount += 1;
          if (!skipUnchangedWrites || patchDiffers(old, patch)) {
            const writePatch = { ...patch, last_price_check_at: syncNow() };
            writeJobs.push(async () => { synced[syncedSlot] = await writePartUpdate(old, writePatch); });
          }
        } else {
          const patch = {
            inventory_link_state: "detached",
            price_state: "detached",
            is_active: true,
          };
          // This is an independent add-on, not a broken Builder-produced Part.
          // Keep the Part visibly detached and let Update Price block until the
          // user uses Switch Part, but do not trigger the Builder reattach modal.
          if (!skipUnchangedWrites || patchDiffers(old, patch)) {
            const writePatch = { ...patch, last_price_check_at: syncNow() };
            writeJobs.push(async () => { synced[syncedSlot] = await writePartUpdate(old, writePatch); });
          }
        }
      }
      continue;
    }
    const frozenRemovedCost = num(old.frozen_extended_cost);
    if (Math.abs(frozenRemovedCost) <= 0.005) {
      writeJobs.push(() => writePartUpdate(old, {
        is_active: false,
        current_unit_cost: 0,
        current_extended_cost: 0,
        price_state: "current",
        price_delta: 0,
        price_delta_percent: 0,
        last_price_check_at: syncNow(),
        notes: `${old.notes ? `${old.notes}\n` : ""}Part removed from Builder before it carried a frozen cost; historical row retained inactive.`,
      }));
      continue;
    }

    const alreadyPendingRemoval = !!old.builder_data?.[PENDING_REMOVAL_KEY];
    const removalNote = "Part no longer exists in the current Builder. Frozen cost is retained until Update Price accepts its removal.";
    const pendingRemoval = {
      current_unit_cost: 0,
      current_extended_cost: 0,
      price_state: "changed",
      price_delta: -frozenRemovedCost,
      price_delta_percent: -100,
      builder_data: { ...(old.builder_data || {}), [PENDING_REMOVAL_KEY]: true },
      is_active: true,
      notes: alreadyPendingRemoval
        ? (old.notes || removalNote)
        : `${old.notes ? `${old.notes}\n` : ""}${removalNote}`,
    };
    if (!skipUnchangedWrites || patchDiffers(old, pendingRemoval)) {
      const writePatch = { ...pendingRemoval, last_price_check_at: syncNow() };
      queueWrite(() => writePartUpdate(old, writePatch));
    } else {
      synced.push(old);
    }
    changedCount += 1;
    removedPartCount += 1;
  }

  // (#419) Drain the write queue through a bounded pool. Jobs start in
  // descriptor order (Promise.all invokes each chunk in order), so
  // partWritePlan keeps its deterministic order; per-row CAS is unchanged.
  for (let i = 0; i < writeJobs.length; i += WRITE_CONCURRENCY) {
    await Promise.all(writeJobs.slice(i, i + WRITE_CONCURRENCY).map((run) => run()));
  }

  const activeEconomicParts = synced.filter((part) => part.is_active !== false);
  const currentPartsTotal = activeEconomicParts.reduce(
    (sum, part) => sum + num(part.current_extended_cost, num(part.frozen_extended_cost)),
    0
  );
  const frozenPartsTotal = activeEconomicParts.reduce(
    (sum, part) => sum + num(part.frozen_extended_cost),
    0
  );
  const markupParts = activeEconomicParts.filter((part) => part.part_subtype === "markup");
  const currentMarkupTotal = markupParts.reduce(
    (sum, part) => sum + num(part.current_extended_cost, num(part.frozen_extended_cost)),
    0
  );
  const frozenMarkupTotal = markupParts.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const manualAddons = activeEconomicParts.filter((part) => part.builder_sync_state === "manual_addon");
  const manualAddonFrozenTotal = manualAddons.reduce((sum, part) => sum + num(part.frozen_extended_cost), 0);
  const manualAddonCurrentTotal = manualAddons.reduce((sum, part) => sum + num(part.current_extended_cost, num(part.frozen_extended_cost)), 0);
  const uniqueRecalcNames = [...new Set(recalcPartNames.filter(Boolean))];

  return {
    partCount: activeEconomicParts.length,
    detachedCount,
    changedCount,
    newPartCount,
    removedPartCount,
    writesPerformed,
    recalcRequired,
    recalcReason: recalcRequired
      ? `Master Inventory changed after this ${builderProduct.builder_name || "Builder"} was last calculated${uniqueRecalcNames.length ? `: ${uniqueRecalcNames.slice(0, 4).join(", ")}${uniqueRecalcNames.length > 4 ? "…" : ""}` : ""}. Reopen and save the Builder before accepting Update Price.`
      : "",
    usesDirectLiveReprice: directLiveReprice && !legacyMode,
    currentPartsTotal,
    frozenPartsTotal,
    currentMarkupTotal,
    frozenMarkupTotal,
    manualAddonFrozenTotal,
    manualAddonCurrentTotal,
    parts: synced,
    partWritePlan,
  };
}

function assertUniqueBuilderPartKeys(parts, builderProductId, label = "Builder Parts") {
  if (!Array.isArray(parts)) throw new Error(`${label} could not be verified while recovering a Builder mutation.`);
  const seen = new Map();
  for (const part of parts) {
    if (String(part?.builder_product_id || "") !== String(builderProductId || "")) {
      throw new Error(`${label} contains a Part owned by a different Builder Product. Recovery stopped before continuing.`);
    }
    const key = String(part?.part_key || "").trim();
    if (!key) continue;
    if (seen.has(key)) {
      throw new Error(`${label} contains multiple Parts with key “${key}” for the same Builder Product. Recovery stopped without choosing between duplicate Parts.`);
    }
    seen.set(key, part.id || "");
  }
  return true;
}

export async function applyBuilderPartPriceAcceptancePlan(builderProductId, plan, { partsOverride = undefined } = {}) {
  const parts = partsOverride !== undefined
    ? partsOverride
    : await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts" });
  assertUniqueBuilderPartKeys(parts, builderProductId);
  const byId = new Map(parts.map((part) => [part.id, part]));
  const byKey = new Map(parts.map((part) => [part.part_key, part]));
  let writesPerformed = 0;
  let createdAny = false;

  for (const step of plan?.part_updates || []) {
    if (step.operation === "create") {
      const data = step.data || {};
      const existing = byKey.get(step.part_key || data.part_key);
      if (existing) {
        if (existing.builder_product_id !== builderProductId) {
          throw new Error("A planned Builder Part key is now owned by a different Product. Reload before continuing.");
        }
        if (patchDiffers(existing, data)) {
          throw new Error(`Part “${existing.part_name || "Part"}” appeared while the Builder mutation was pending with different data. No unrelated Part was overwritten.`);
        }
        continue;
      }
      const { record: created, status } = await createBuilderPartWithRecovery({
        entity: staffEntities.BuilderPart,
        data,
        label: `Builder Part “${data.part_name || data.part_key || "Part"}” recovery create`,
      });
      if (status !== "existing") {
        writesPerformed += 1;
        createdAny = true;
      }
      if (created?.id) byId.set(created.id, created);
      if (created?.part_key) byKey.set(created.part_key, created);
      continue;
    }

    const part = byId.get(step.part_id);
    if (!part || part.builder_product_id !== builderProductId) {
      throw new Error("A Builder Part changed ownership while a Builder mutation was pending. Reload before continuing.");
    }
    const targetPatch = step.patch || {};
    if (!patchDiffers(part, targetPatch)) continue;
    const expected = String(step.expected_updated_date || "").trim();
    const current = String(part.updated_date || "").trim();
    if (expected && current && current !== expected) {
      throw new Error(`Part “${part.part_name || "Part"}” changed while a Builder mutation was pending. No unrelated Part edit was overwritten.`);
    }
    await replaceBuilderEntityFieldsIfUnchanged({
      entity: staffEntities.BuilderPart,
      id: part.id,
      expectedUpdatedAt: part.updated_date || "",
      expectedFields: expectedBuilderEntityFields(part, targetPatch),
      nextFields: targetPatch,
      guardFields: { builder_product_id: builderProductId },
      label: `Builder Part “${part.part_name || "Part"}” recovery update`,
    });
    writesPerformed += 1;
  }

  if (createdAny) {
    const verifiedParts = await loadAllEntityRows({
      entity: staffEntities.BuilderPart,
      query: { builder_product_id: builderProductId },
      sort: "sort_order",
      label: "Builder Parts post-create verification",
    });
    assertUniqueBuilderPartKeys(verifiedParts, builderProductId, "Builder Parts post-create verification");
  }

  return { writesPerformed };
}

export async function acceptBuilderPartPrices(builderProductId, {
  builderOverride = undefined,
  partsOverride = undefined,
  apply = true,
  timestamp = nowIso(),
} = {}) {
  const [parts, builder] = await Promise.all([
    partsOverride !== undefined
      ? Promise.resolve(partsOverride)
      : loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts" }),
    builderOverride !== undefined
      ? Promise.resolve(builderOverride)
      : staffEntities.BuilderProduct.get(builderProductId),
  ]);
  if (!builder?.id || builder.id !== builderProductId) {
    throw new Error("Builder Product could not be verified before accepting Part prices.");
  }
  if (!Array.isArray(parts)) {
    throw new Error("Builder Parts could not be verified before accepting pricing.");
  }
  if (parts.some((part) => part?.builder_product_id !== builderProductId)) {
    throw new Error("Builder Part ownership changed before pricing could be accepted. Reload the estimate and try again.");
  }
  const activeParts = parts.filter((row) => row.is_active !== false);
  const detachedParts = activeParts.filter((part) =>
    part.builder_sync_state === "detached_override" ||
    ["detached", "reattach_available"].includes(part.inventory_link_state)
  );

  // All-or-nothing guard: do not mutate even one Part while any linked Part is
  // detached. The user must resolve/reattach those Parts first.
  if (detachedParts.length > 0) {
    return {
      changedParts: [],
      detachedCount: detachedParts.length,
      detachedParts: detachedParts.map((part) => ({
        part_id: part.id,
        part_key: part.part_key,
        part_name: part.part_name,
        inventory_item_name: part.inventory_item_name,
        reattach_candidate_id: part.reattach_candidate_id || "",
        reattach_candidate_name: part.reattach_candidate_name || "",
      })),
    };
  }

  const staleCatalogParts = !builder || DIRECT_LIVE_REPRICE_MODULES.has(builder.module_key) || builder.price_state === "unchecked"
    ? []
    : activeParts.filter((part) => {
        if (["manual", "manual_addon", "detached_override"].includes(part.builder_sync_state)) return false;
        const currentPricing = pricingSnapshot(part.current_inventory_snapshot);
        const frozenPricing = pricingSnapshot(part.frozen_inventory_snapshot);
        if (same(currentPricing, frozenPricing)) return false;
        const builderCalculatedPricing = part.pricing_basis_snapshot?.builder_calculated_inventory_pricing || {};
        // Frozen pricing may intentionally differ after the Builder has been
        // recalculated. That is exactly the state Update Price is meant to accept.
        // Block only when the current catalog differs from BOTH the frozen price
        // and the pricing explicitly used by the last Builder calculation.
        return !same(currentPricing, builderCalculatedPricing);
      });

  if (builder?.price_recalc_required || staleCatalogParts.length > 0) {
    return {
      changedParts: [],
      detachedCount: 0,
      detachedParts: [],
      recalcRequired: true,
      recalcParts: staleCatalogParts.map((part) => ({
        part_id: part.id,
        part_key: part.part_key,
        part_name: part.part_name,
        inventory_item_name: part.inventory_item_name,
      })),
      recalcReason: builder?.price_recalc_reason || "Master Inventory changed after this Builder was last calculated. Reopen and save the Builder before accepting Update Price.",
    };
  }

  const changedParts = [];
  const partUpdates = [];
  let activePartCount = 0;

  for (const part of activeParts) {
    const wasChanged = part.price_state === "changed" ||
      Math.abs(num(part.current_extended_cost) - num(part.frozen_extended_cost)) > 0.005 ||
      !same(pricingSnapshot(part.current_inventory_snapshot), pricingSnapshot(part.frozen_inventory_snapshot));
    const pendingRemoval = !!part.builder_data?.[PENDING_REMOVAL_KEY];
    if (wasChanged) {
      changedParts.push({
        part_id: part.id,
        part_key: part.part_key,
        part_name: part.part_name,
        previous_inventory_item_id: part.original_inventory_item_id || part.inventory_item_id,
        current_inventory_item_id: part.inventory_item_id,
        previous_unit_cost: num(part.frozen_unit_cost),
        new_unit_cost: num(part.current_unit_cost),
        previous_extended_cost: num(part.frozen_extended_cost),
        new_extended_cost: num(part.current_extended_cost),
        previous_inventory_snapshot: part.frozen_inventory_snapshot || {},
        new_inventory_snapshot: part.current_inventory_snapshot || {},
        action: pendingRemoval
          ? "remove"
          : Math.abs(num(part.frozen_extended_cost)) <= 0.005 && Math.abs(num(part.current_extended_cost)) > 0.005
            ? "add"
            : "price_update",
      });
    }
    const acceptedBuilderData = { ...(part.builder_data || {}) };
    delete acceptedBuilderData[PENDING_REMOVAL_KEY];
    partUpdates.push({
      part_id: part.id,
      expected_updated_date: part.updated_date || "",
      patch: {
        frozen_inventory_snapshot: part.current_inventory_snapshot || part.frozen_inventory_snapshot || {},
        frozen_unit_cost: num(part.current_unit_cost, num(part.frozen_unit_cost)),
        frozen_extended_cost: num(part.current_extended_cost, num(part.frozen_extended_cost)),
        inventory_updated_date_snapshot: part.current_inventory_snapshot?.updated_date || part.inventory_updated_date_snapshot || "",
        price_state: "current",
        price_delta: 0,
        price_delta_percent: 0,
        builder_data: acceptedBuilderData,
        is_active: !pendingRemoval,
        last_price_update_at: timestamp,
      },
    });
    if (!pendingRemoval) activePartCount += 1;
  }

  const acceptancePlan = {
    timestamp,
    part_updates: partUpdates,
    changed_parts: changedParts,
    active_part_count: activePartCount,
  };
  if (apply) {
    await applyBuilderPartPriceAcceptancePlan(builderProductId, acceptancePlan, { partsOverride: parts });
  }

  return {
    changedParts,
    detachedCount: 0,
    detachedParts: [],
    recalcRequired: false,
    recalcParts: [],
    recalcReason: "",
    activePartCount,
    acceptancePlan,
  };
}

export async function getDetachedBuilderParts(builderProductId) {
  if (!builderProductId) return [];
  const parts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builderProductId }, sort: "sort_order", label: "Builder Parts" });
  return (parts || [])
    .filter(requiresBuilderReattach)
    .sort((a, b) => num(a.sort_order) - num(b.sort_order))
    .map((part) => ({
      ...part,
      can_reattach: part.builder_sync_state === "detached_override" || !!part.reattach_candidate_id,
    }));
}

function assertEstimatorPartVersion(part, expectedUpdatedAt = "") {
  const expected = String(expectedUpdatedAt || "").trim();
  const current = String(part?.updated_date || "").trim();
  if (expected && current !== expected) {
    throw new Error(`Part “${part?.part_name || "Part"}” changed in another session. Reload the Product before continuing.`);
  }
}

function estimateBuilderLine(estimate, builderProductId) {
  return (estimate?.line_items || []).find((line) => line.builder_product_id === builderProductId) || null;
}

async function loadPendingAwarePartMutationContext(partId, options = {}, allowedKinds = []) {
  const part = await staffEntities.BuilderPart.get(partId);
  if (!part?.id) throw new Error("The Part could not be loaded.");
  const builder = await staffEntities.BuilderProduct.get(part.builder_product_id);
  if (!builder?.id || !builder.estimate_id) throw new Error("The Builder Product could not be verified against an estimate.");
  const estimate = await staffEntities.AllInOneEstimate.get(builder.estimate_id);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  const line = estimateBuilderLine(estimate, builder.id);
  if (!line) throw new Error("This Product is no longer part of the estimate. Reload before changing its Parts.");

  const pending = pendingBuilderMutation(line);
  if (pending) {
    if (!allowedKinds.includes(pending.kind) || String(pending.target_part_id || "") !== String(part.id)) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume that operation before changing this Part.");
    }
    await assertEstimateProductMutationAllowed(estimate, { allowPriceAcceptanceKey: pending.key });
    return { part, builder, estimate, line, pending, alreadyComplete: false };
  }

  if (typeof options.isAlreadyComplete === "function" && options.isAlreadyComplete({ part, builder, estimate, line })) {
    return { part, builder, estimate, line, pending: null, alreadyComplete: true };
  }

  assertEstimatorPartVersion(part, options.expectedPartUpdatedAt || "");
  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: options.expectedEstimateUpdatedAt || "" });
  return { part, builder, estimate, line, pending: null, alreadyComplete: false };
}

export async function detachBuilderPartOverride(partId, reason = "Detached for independent Part override.", options = {}) {
  if (!partId) return null;
  const context = await loadPendingAwarePartMutationContext(
    partId,
    {
      ...options,
      isAlreadyComplete: ({ part }) => part.builder_sync_state === "detached_override",
    },
    ["builder_detach_override"]
  );
  const { part, builder, estimate, line, pending, alreadyComplete } = context;

  if (pending) {
    const allParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
    await resumeBuilderMutation({
      estimateId: estimate.id,
      estimate,
      builder,
      parts: allParts,
      line,
      pending,
      applyPartPlan: applyBuilderPartPriceAcceptancePlan,
    });
    const step = (pending.part_acceptance_plan?.part_updates || []).find((item) => item.part_id === part.id);
    return { ...part, ...(step?.patch || {}) };
  }
  if (alreadyComplete) return part;
  if (["manual", "manual_addon"].includes(part.builder_sync_state)) {
    throw new Error("Independent manual Parts do not need to be detached from a Builder.");
  }

  const allParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
  if (!Array.isArray(allParts) || allParts.some((row) => row?.builder_product_id !== builder.id)) {
    throw new Error("Builder Parts could not be verified before detaching this Part.");
  }
  const detachedCount = allParts.filter((row) =>
    row.id === part.id ? row.is_active !== false : requiresBuilderReattach(row)
  ).length;
  const timestamp = nowIso();
  const detachedSnapshot = {
    part_name: part.part_name,
    client_label: part.client_label,
    quantity: part.quantity,
    unit: part.unit,
    inventory_entity: part.inventory_entity,
    inventory_item_id: part.inventory_item_id,
    inventory_item_name: part.inventory_item_name,
    frozen_unit_cost: num(part.frozen_unit_cost),
    frozen_extended_cost: num(part.frozen_extended_cost),
    builder_data: part.builder_data || {},
    calculation_snapshot: part.calculation_snapshot || {},
    pricing_basis_snapshot: part.pricing_basis_snapshot || {},
    detail_overrides: part.detail_overrides || {},
    source_path: part.source_path,
  };
  const me = await base44.auth.me().catch(() => null);
  const detachedBy = String(options.detachedBy || me?.full_name || me?.email || "").trim();
  const partPatch = {
    builder_sync_state: "detached_override",
    builder_detached_at: timestamp,
    builder_detached_reason: reason,
    builder_detached_by: detachedBy,
    builder_detached_snapshot: detachedSnapshot,
    reattach_candidate_id: part.inventory_item_id || part.original_inventory_item_id || "",
    reattach_candidate_name: part.inventory_item_name || part.part_name || "",
    price_state: "detached",
    last_price_check_at: timestamp,
    notes: `${part.notes ? `${part.notes}\n` : ""}Detached from Builder for independent override. Frozen pricing retained.`,
  };
  const changedParts = [{
    part_id: part.id,
    part_key: part.part_key,
    part_name: part.part_name,
    action: "detach_override",
    frozen_unit_cost: num(part.frozen_unit_cost),
    frozen_extended_cost: num(part.frozen_extended_cost),
    inventory_item_id: part.inventory_item_id || "",
    source_path: part.source_path || "",
  }];
  const builderPatch = {
    detached_part_count: detachedCount,
    needs_reattach_review: true,
    price_state: "detached_parts",
    last_price_check_at: timestamp,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    detached_part_count: detachedCount,
    needs_reattach_review: true,
    price_state: "detached_parts",
    last_price_check_at: timestamp,
  };
  const revision = {
    builder_product_id: builder.id,
    estimate_id: builder.estimate_id || "",
    reason: "manual_adjustment",
    previous_total_cost: num(builder.frozen_cost),
    new_total_cost: num(builder.frozen_cost),
    previous_customer_price: num(builder.frozen_customer_price, num(builder.frozen_cost)),
    new_customer_price: num(builder.frozen_customer_price, num(builder.frozen_cost)),
    changed_parts: changedParts,
    builder_snapshot_before: builder.builder_snapshot || {},
    builder_snapshot_after: builder.builder_snapshot || {},
    price_snapshot_before: { total: num(builder.frozen_cost), pricing_accepted: false },
    price_snapshot_after: { total: num(builder.frozen_cost), pricing_accepted: false },
    notes: reason,
  };
  const operationKey = `builder_detach_override:${builder.id}:${part.id}:${num(builder.builder_version, 1)}:${builderMutationHash({
    estimate_updated_date: estimate.updated_date || "",
    part_updated_date: part.updated_date || "",
    reason,
    part_patch: partPatch,
  })}`;
  const recoveryMarker = {
    key: operationKey,
    kind: "builder_detach_override",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: line.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    target_part_id: part.id,
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    part_acceptance_plan: {
      timestamp,
      part_updates: [{ part_id: part.id, expected_updated_date: part.updated_date || "", patch: partPatch }],
      changed_parts: changedParts,
      active_part_count: allParts.filter((row) => row.is_active !== false).length,
    },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision,
  };

  const marked = await markBuilderMutationPending({ estimate, builder, line, pending: recoveryMarker });
  await resumeBuilderMutation({
    estimateId: estimate.id,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });
  return { ...part, ...partPatch };
}

function detachedOverrideChangesAlreadyApplied(part, changes = {}) {
  if (part?.builder_sync_state !== "detached_override") return false;
  if (changes.part_name !== undefined && String(part.part_name || "") !== String(changes.part_name || "Part")) return false;
  if (changes.client_label !== undefined && String(part.client_label || "") !== String(changes.client_label || "")) return false;
  if (changes.quantity !== undefined && Math.abs(num(part.quantity) - Math.max(0, num(changes.quantity))) > 0.000001) return false;
  if (changes.unit !== undefined && String(part.unit || "") !== String(changes.unit || "")) return false;
  if (changes.frozen_unit_cost !== undefined && Math.abs(num(part.frozen_unit_cost) - num(changes.frozen_unit_cost)) > 0.000001) return false;
  if (changes.detail_overrides !== undefined && !same(part.detail_overrides || {}, changes.detail_overrides || {})) return false;
  if (changes.notes !== undefined && String(part.notes || "") !== String(changes.notes || "")) return false;
  if (changes.manual_cost_override_reason !== undefined && String(part.manual_cost_override_reason || "") !== String(changes.manual_cost_override_reason || "")) return false;
  return true;
}

export async function updateDetachedPartOverride(partId, changes = {}, options = {}) {
  const context = await loadPendingAwarePartMutationContext(
    partId,
    {
      ...options,
      isAlreadyComplete: ({ part }) => detachedOverrideChangesAlreadyApplied(part, changes),
    },
    ["builder_detached_override_update"]
  );
  const { part, builder, estimate, line, pending, alreadyComplete } = context;

  if (pending) {
    const allParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
    await resumeBuilderMutation({
      estimateId: estimate.id,
      estimate,
      builder,
      parts: allParts,
      line,
      pending,
      applyPartPlan: applyBuilderPartPriceAcceptancePlan,
    });
    const step = (pending.part_acceptance_plan?.part_updates || []).find((item) => item.part_id === part.id);
    return { ...part, ...(step?.patch || {}) };
  }
  if (alreadyComplete) return part;
  if (part.builder_sync_state !== "detached_override") {
    throw new Error("This Part must be detached from its Builder before it can be overridden independently.");
  }

  const allParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
  if (!Array.isArray(allParts) || allParts.some((row) => row?.builder_product_id !== builder.id)) {
    throw new Error("Builder Parts could not be verified before updating this detached override.");
  }
  const previousExtended = num(part.frozen_extended_cost);
  const quantity = changes.quantity !== undefined ? Math.max(0, num(changes.quantity)) : num(part.quantity, 1);
  const frozenUnitCost = changes.frozen_unit_cost !== undefined ? num(changes.frozen_unit_cost) : num(part.frozen_unit_cost);
  const nextExtended = quantity * frozenUnitCost;
  const delta = nextExtended - previousExtended;
  const timestamp = nowIso();
  const previousDetailOverrides = part.detail_overrides || {};
  const nextDetailOverrides = changes.detail_overrides !== undefined ? { ...(changes.detail_overrides || {}) } : previousDetailOverrides;
  const partPatch = {
    part_name: changes.part_name !== undefined ? String(changes.part_name || "Part") : part.part_name,
    client_label: changes.client_label !== undefined ? String(changes.client_label || "") : part.client_label,
    quantity,
    unit: changes.unit !== undefined ? String(changes.unit || "") : part.unit,
    frozen_unit_cost: frozenUnitCost,
    frozen_extended_cost: nextExtended,
    current_unit_cost: frozenUnitCost,
    current_extended_cost: nextExtended,
    manual_cost_override: true,
    manual_cost: nextExtended,
    manual_cost_override_reason: changes.manual_cost_override_reason !== undefined ? String(changes.manual_cost_override_reason || "") : String(part.manual_cost_override_reason || ""),
    detail_overrides: nextDetailOverrides,
    price_state: "detached",
    price_delta: 0,
    price_delta_percent: 0,
    notes: changes.notes !== undefined ? String(changes.notes || "") : part.notes,
    last_price_update_at: timestamp,
    last_price_check_at: timestamp,
  };

  const previousProductCost = num(builder.frozen_cost);
  const nextProductCost = previousProductCost + delta;
  const previousCustomerPrice = num(builder.frozen_customer_price, previousProductCost);
  const nextCustomerPrice = previousCustomerPrice + delta;
  const changedParts = [{
    part_id: part.id,
    part_key: part.part_key,
    part_name: partPatch.part_name,
    action: "override_update",
    previous_quantity: num(part.quantity, 1),
    new_quantity: quantity,
    previous_unit: part.unit || "",
    new_unit: partPatch.unit || "",
    previous_unit_cost: num(part.frozen_unit_cost),
    new_unit_cost: frozenUnitCost,
    previous_extended_cost: previousExtended,
    new_extended_cost: nextExtended,
    delta,
    previous_detail_overrides: previousDetailOverrides,
    new_detail_overrides: nextDetailOverrides,
  }];
  const builderPatch = {
    frozen_cost: nextProductCost,
    frozen_customer_price: nextCustomerPrice,
    price_state: "detached_parts",
    needs_reattach_review: true,
    last_price_update_at: timestamp,
    last_price_update_note: `Independent override updated for ${partPatch.part_name}.`,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    total_snapshot: num(line.total_snapshot, previousProductCost) + delta,
    customer_price_snapshot: acceptedCustomerUnitPrice(line) + delta,
    live_customer_price_snapshot: liveCustomerUnitPrice(line) + delta,
    price_state: "detached_parts",
    needs_reattach_review: true,
    last_price_update_at: timestamp,
    last_price_check_at: timestamp,
  };
  const revision = {
    builder_product_id: builder.id,
    estimate_id: builder.estimate_id || "",
    reason: "manual_adjustment",
    previous_total_cost: previousProductCost,
    new_total_cost: nextProductCost,
    previous_customer_price: previousCustomerPrice,
    new_customer_price: nextCustomerPrice,
    changed_parts: changedParts,
    builder_snapshot_before: builder.builder_snapshot || {},
    builder_snapshot_after: builder.builder_snapshot || {},
    price_snapshot_before: { total: previousProductCost, detached_override: true },
    price_snapshot_after: { total: nextProductCost, detached_override: true },
    notes: "Independent detached Part override updated. Builder synchronization remains disabled for this Part.",
  };
  const operationKey = `builder_detached_override_update:${builder.id}:${part.id}:${num(builder.builder_version, 1)}:${builderMutationHash({
    estimate_updated_date: estimate.updated_date || "",
    part_updated_date: part.updated_date || "",
    changes,
    next_product_cost: nextProductCost,
    next_customer_price: nextCustomerPrice,
  })}`;
  const recoveryMarker = {
    key: operationKey,
    kind: "builder_detached_override_update",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: line.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    target_part_id: part.id,
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    part_acceptance_plan: {
      timestamp,
      part_updates: [{ part_id: part.id, expected_updated_date: part.updated_date || "", patch: partPatch }],
      changed_parts: changedParts,
      active_part_count: allParts.filter((row) => row.is_active !== false).length,
    },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision,
  };

  const marked = await markBuilderMutationPending({ estimate, builder, line, pending: recoveryMarker });
  await resumeBuilderMutation({
    estimateId: estimate.id,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });
  return { ...part, ...partPatch };
}

function pathTokens(path) {
  return String(path || "")
    .replace(/\[(\d+)\]/g, ".$1")
    .split(".")
    .map((token) => token.trim())
    .filter(Boolean);
}

function setAtPath(target, path, value) {
  const tokens = pathTokens(path);
  if (!tokens.length) return false;
  let cursor = target;
  for (let i = 0; i < tokens.length - 1; i += 1) {
    const token = tokens[i];
    if (cursor?.[token] === undefined || cursor?.[token] === null) return false;
    cursor = cursor[token];
  }
  const last = tokens[tokens.length - 1];
  if (!cursor || typeof cursor !== "object") return false;
  cursor[last] = value;

  // Channel Letter / Maintenance history contains both inventory_id and
  // inventory_item_id generations. Keep an existing alias synchronized so the
  // old and new calculator/editor paths continue to agree after reattachment.
  if (last === "inventory_item_id" && Object.prototype.hasOwnProperty.call(cursor, "inventory_id")) {
    cursor.inventory_id = value;
  } else if (last === "inventory_id" && Object.prototype.hasOwnProperty.call(cursor, "inventory_item_id")) {
    cursor.inventory_item_id = value;
  }
  return true;
}

function topLevelField(path) {
  return pathTokens(path)[0] || "";
}

export async function reattachBuilderParts({ builderProductId, partIds = [], expectedEstimateUpdatedAt = "", expectedPartVersions = {} }) {
  if (!builderProductId || !partIds.length) {
    return { reattached: [], remainingDetached: await getDetachedBuilderParts(builderProductId) };
  }

  const builder = await staffEntities.BuilderProduct.get(builderProductId);
  if (!builder?.id || !builder.estimate_id) throw new Error("The Builder Product could not be verified against an estimate.");
  const estimate = await staffEntities.AllInOneEstimate.get(builder.estimate_id);
  if (!estimate) throw new Error("Estimate could not be loaded.");
  const line = estimateBuilderLine(estimate, builder.id);
  if (!line) throw new Error("This Product is no longer part of the estimate. Reload before reattaching Parts.");

  const existingPending = pendingBuilderMutation(line);
  if (existingPending) {
    if (existingPending.kind !== "builder_reattach_parts" || String(existingPending.builder_product_id || "") !== String(builder.id)) {
      throw new Error("Another Builder mutation is still being recovered for this Product. Resume that operation before reattaching Parts.");
    }
    const currentParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
    await resumeBuilderMutation({
      estimateId: estimate.id,
      estimate,
      builder,
      parts: currentParts,
      line,
      pending: existingPending,
      applyPartPlan: applyBuilderPartPriceAcceptancePlan,
    });
    return {
      reattached: existingPending.revision?.changed_parts || [],
      remainingDetached: await getDetachedBuilderParts(builder.id),
      builderProject: existingPending.patched_source || null,
      recovered: true,
    };
  }

  const allParts = await loadAllEntityRows({ entity: staffEntities.BuilderPart, query: { builder_product_id: builder.id }, sort: "sort_order", label: "Builder Parts" });
  if (!Array.isArray(allParts) || allParts.some((part) => part?.builder_product_id !== builder.id)) {
    throw new Error("Builder Parts could not be verified before reattachment.");
  }
  const requestedIds = new Set(partIds);
  const requestedParts = allParts.filter((part) => requestedIds.has(part.id));
  if (requestedParts.length !== requestedIds.size) {
    throw new Error("One or more selected Parts no longer belong to this Product. Reload before reattaching.");
  }

  // A lost final response leaves the browser with stale Part versions even though
  // the server already completed the requested reattachment. Treat that verified
  // server state as a no-op rather than creating another reattach revision.
  if (requestedParts.every((part) => !requiresBuilderReattach(part))) {
    return {
      reattached: requestedParts.map((part) => ({ part_id: part.id, part_key: part.part_key, part_name: part.part_name })),
      remainingDetached: await getDetachedBuilderParts(builder.id),
      builderProject: builder.source_entity && builder.source_project_id
        ? await staffEntities[builder.source_entity].get(builder.source_project_id).catch(() => null)
        : null,
      alreadyCompleted: true,
    };
  }

  await assertEstimateProductMutationAllowed(estimate, { expectedUpdatedAt: expectedEstimateUpdatedAt });
  requestedParts.forEach((part) => assertEstimatorPartVersion(part, expectedPartVersions?.[part.id] || ""));

  if (!builder.source_entity || !builder.source_project_id) {
    throw new Error("This Builder no longer has an editable source project to reattach Parts to.");
  }

  const [source, catalogs] = await Promise.all([
    staffEntities[builder.source_entity].get(builder.source_project_id),
    loadBuilderCatalogs(builder.module_key, { strict: true }),
  ]);
  if (!source) throw new Error("The Builder source project could not be loaded.");

  const detached = allParts
    .filter(requiresBuilderReattach)
    .sort((a, b) => num(a.sort_order) - num(b.sort_order))
    .map((part) => ({ ...part, can_reattach: part.builder_sync_state === "detached_override" || !!part.reattach_candidate_id }));
  const selected = detached.filter((part) => requestedIds.has(part.id));
  if (selected.length !== requestedIds.size) {
    throw new Error("One or more selected Parts changed or are no longer detached. Reload the Product before reattaching.");
  }

  const beforeSnapshot = builder.builder_snapshot || source;
  const patchedSource = JSON.parse(JSON.stringify(source));
  const changedRoots = new Set();
  const reattached = [];
  const selectedPatches = new Map();

  for (const part of selected) {
    const builderOverride = part.builder_sync_state === "detached_override";
    if (builderOverride) {
      selectedPatches.set(part.id, {
        builder_sync_state: "linked",
        builder_detached_at: "",
        builder_detached_reason: "",
        builder_detached_by: "",
        detail_overrides: {},
        price_state: "changed",
      });
    } else {
      if (!part.reattach_candidate_id) throw new Error(`Part “${part.part_name || "Part"}” no longer has a verified reattach candidate.`);
      const candidateEntity = findEntity(catalogs, part.reattach_candidate_id, part.inventory_entity || "");
      const candidateRow = findRow(catalogs, candidateEntity, part.reattach_candidate_id);
      if (!candidateEntity || !candidateRow) {
        throw new Error(`The replacement Master Inventory record for Part “${part.part_name || "Part"}” could not be verified.`);
      }
      const changed = setAtPath(patchedSource, part.source_path, part.reattach_candidate_id);
      if (!changed) throw new Error(`Part “${part.part_name || "Part"}” could not be mapped back into the current Builder source record.`);
      const root = topLevelField(part.source_path);
      if (root) changedRoots.add(root);
      selectedPatches.set(part.id, { detail_overrides: {} });
    }
    reattached.push({
      part_id: part.id,
      part_key: part.part_key,
      part_name: part.part_name,
      reattach_type: builderOverride ? "builder_override" : "inventory_replacement",
      previous_inventory_item_id: part.inventory_item_id || part.original_inventory_item_id || "",
      current_inventory_item_id: part.reattach_candidate_id || part.inventory_item_id || "",
      previous_inventory_name: part.inventory_item_name || "",
      current_inventory_name: part.reattach_candidate_name || part.inventory_item_name || "",
      frozen_unit_cost: num(part.frozen_unit_cost),
      frozen_extended_cost: num(part.frozen_extended_cost),
      cleared_detail_overrides: part.detail_overrides || {},
      source_path: part.source_path,
    });
  }

  const sourcePatch = {};
  changedRoots.forEach((root) => { sourcePatch[root] = patchedSource[root]; });

  const inventoryRowsOverride = new Map();
  for (const part of allParts) {
    if (part.builder_sync_state !== "manual_addon" || !part.inventory_entity || !part.inventory_item_id || part.manual_cost_override) continue;
    const row = await staffEntities[part.inventory_entity].get(part.inventory_item_id);
    if (!row) throw new Error(`${part.inventory_entity} inventory could not be verified for Part “${part.part_name || "Part"}”.`);
    inventoryRowsOverride.set(`${part.inventory_entity}:${part.inventory_item_id}`, row);
  }
  const existingPartsForSync = allParts.map((part) =>
    selectedPatches.has(part.id) ? { ...part, ...selectedPatches.get(part.id) } : part
  );

  const timestamp = nowIso();
  const plannedSummary = await syncBuilderParts({
    builderProduct: builder,
    sourceProject: patchedSource,
    acceptPrices: false,
    legacyMode: false,
    catalogsOverride: catalogs,
    strictCatalogs: true,
    existingPartsOverride: existingPartsForSync,
    inventoryRowsOverride,
    planOnly: true,
    planTimestamp: timestamp,
  });
  const plannedPartUpdates = (plannedSummary.partWritePlan || []).map((step) =>
    step.operation !== "create" && selectedPatches.has(step.part_id)
      ? { ...step, patch: { ...selectedPatches.get(step.part_id), ...(step.patch || {}) } }
      : step
  );
  const remainingDetached = (plannedSummary.parts || [])
    .filter(requiresBuilderReattach)
    .sort((a, b) => num(a.sort_order) - num(b.sort_order))
    .map((part) => ({
      ...part,
      can_reattach: part.builder_sync_state === "detached_override" || !!part.reattach_candidate_id,
    }));

  const builderPatch = {
    builder_snapshot: patchedSource,
    builder_snapshot_at: timestamp,
    builder_snapshot_source_updated_date: timestamp,
    part_count: plannedSummary.partCount,
    detached_part_count: remainingDetached.length,
    needs_reattach_review: remainingDetached.length > 0,
    price_state: remainingDetached.length > 0 ? "detached_parts" : "changed",
    last_price_check_at: timestamp,
    builder_version: num(builder.builder_version, 1) + 1,
  };
  const linePatch = {
    detached_part_count: remainingDetached.length,
    needs_reattach_review: remainingDetached.length > 0,
    price_state: remainingDetached.length > 0 ? "detached_parts" : "changed",
    last_price_check_at: timestamp,
  };
  const revision = {
    builder_product_id: builder.id,
    estimate_id: builder.estimate_id || "",
    reason: "reattach",
    previous_total_cost: num(builder.frozen_cost),
    new_total_cost: num(builder.frozen_cost),
    previous_customer_price: num(builder.frozen_customer_price, num(builder.frozen_cost)),
    new_customer_price: num(builder.frozen_customer_price, num(builder.frozen_cost)),
    changed_parts: reattached,
    builder_snapshot_before: beforeSnapshot,
    builder_snapshot_after: patchedSource,
    price_snapshot_before: { total: num(builder.frozen_cost), pricing_accepted: false },
    price_snapshot_after: { total: num(builder.frozen_cost), pricing_accepted: false },
    notes: `Reattached ${reattached.length} Part${reattached.length === 1 ? "" : "s"}. Frozen pricing was preserved; a separate Update Price action is required to accept recalculated pricing.`,
  };
  const operationKey = `builder_reattach_parts:${builder.id}:${num(builder.builder_version, 1)}:${builderMutationHash({
    estimate_updated_date: estimate.updated_date || "",
    source_updated_date: source.updated_date || "",
    selected_parts: selected.map((part) => ({ id: part.id, updated_date: part.updated_date || "", candidate: part.reattach_candidate_id || "", state: part.builder_sync_state })),
    source_patch: sourcePatch,
    part_updates: plannedPartUpdates,
  })}`;
  const recoveryMarker = {
    key: operationKey,
    kind: "builder_reattach_parts",
    started_at: timestamp,
    estimate_id: estimate.id,
    estimate_line_id: line.line_id || builder.estimate_line_id || "",
    builder_product_id: builder.id,
    target_part_ids: selected.map((part) => part.id),
    builder_updated_date_before: builder.updated_date || "",
    builder_version_before: num(builder.builder_version, 1),
    source_entity: builder.source_entity,
    source_project_id: builder.source_project_id,
    source_updated_date_before: source.updated_date || "",
    source_patch: sourcePatch,
    patched_source: patchedSource,
    part_acceptance_plan: {
      timestamp,
      part_updates: plannedPartUpdates,
      changed_parts: reattached,
      active_part_count: plannedSummary.partCount,
    },
    builder_patch: builderPatch,
    line_patch: linePatch,
    revision,
  };

  // Re-read the source immediately before taking the durable Estimate marker so
  // a pre-existing concurrent source edit aborts before any recovery state exists.
  const latestSource = await staffEntities[builder.source_entity].get(builder.source_project_id);
  if (!latestSource) throw new Error("The Builder source project could not be verified before starting reattachment.");
  if (source.updated_date && latestSource.updated_date && source.updated_date !== latestSource.updated_date) {
    throw new Error("The Builder source project changed in another session before reattachment started. No source or Part changes were written.");
  }

  const marked = await markBuilderMutationPending({ estimate, builder, pending: recoveryMarker });
  await resumeBuilderMutation({
    estimateId: estimate.id,
    estimate: marked.markedEstimate,
    builder: marked.currentBuilder,
    parts: marked.currentParts,
    line: marked.markedLine,
    pending: marked.canonicalPending,
    applyPartPlan: applyBuilderPartPriceAcceptancePlan,
  });

  return {
    reattached,
    remainingDetached,
    builderProject: patchedSource,
  };
}

