  };

  const patch = (changes) => commit(() => changes);

  const patchItem = (index, changes) =>
    commit((prev) => ({
      items: prev.items.map((it, i) => (i === index ? { ...it, ...changes } : it)),
    }));

  const removeItem = (index) => {
    const label = project.items?.[index]?.description || `item ${index + 1}`;
