      "type": "string",
      "format": "date-time"
    },
    "deleted_by": {
      "type": "string"
    },
    "production_type": {
      "type": "string",
      "enum": [
        "inhouse",
        "outsource"
      ]
    },
    "sip_checklist": {
      "type": "array",
      "description": "SIP meeting checklist with product groupings and hierarchy",
      "items": {
        "type": "object"
      }
    },
    "mmm_sip_checklist": {
      "type": "array",
      "description": "Monday Morning Meeting checklist - completely separate from SIPs",
      "items": {
        "type": "object"
      }
    },
    "mmm_checklist": {
      "type": "array",
      "description": "Legacy Monday Morning Meeting checklist items",
      "items": {
        "type": "object"
      }
    },
    "sip_completed": {
      "type": "boolean",
